static QString resolveSecureSettingFromProfiles(QString const& settingKey,
                                                QString const& rawValue,
                                                QStringList profiles)
{
    QString plain = rawValue.trimmed();
    if (secure_settings::is_placeholder(plain)) {
        plain.clear();
    }

    profiles.removeAll(QString {});
    profiles.removeDuplicates();
    if (!profiles.contains(QStringLiteral("DEFAULT"), Qt::CaseInsensitive)) {
        profiles << QStringLiteral("DEFAULT");
    }

    auto const& backend = secure_settings::default_backend();
    for (QString profile : profiles) {
        profile = profile.trimmed().toUpper();
        if (profile.isEmpty()) {
            continue;
        }

        auto const lookup = backend.lookup(secure_settings::service(profile), settingKey);
        if (lookup.found) {
            return lookup.value.trimmed();
        }
    }

    return plain;
}

static QString ft2LinkCleanEmailAddress(QString raw)
{
    raw = raw.trimmed();
    static QRegularExpression const emailRe(
        QStringLiteral(R"(([A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}))"),
        QRegularExpression::CaseInsensitiveOption);
    QRegularExpressionMatch const match = emailRe.match(raw);
    return match.hasMatch() ? match.captured(1).toLower() : QString();
}

static QString ft2LinkSmtpConfigString(QVariantMap const& config,
                                       QString const& key,
                                       QString const& fallback = QString())
{
    return config.value(key, fallback).toString().trimmed();
}

static QString ft2LinkSmtpSecretKey(QVariantMap const& config)
{
    QString host = ft2LinkSmtpConfigString(config, QStringLiteral("host")).toLower();
    QString user = ft2LinkSmtpConfigString(config, QStringLiteral("username")).toLower();
    if (host.isEmpty()) {
        host = QStringLiteral("default-host");
    }
    if (user.isEmpty()) {
        user = QStringLiteral("default-user");
    }
    host.replace(QRegularExpression(QStringLiteral(R"([^a-z0-9._-])")), QStringLiteral("_"));
    user.replace(QRegularExpression(QStringLiteral(R"([^a-z0-9._@+-])")), QStringLiteral("_"));
    return QStringLiteral("ft2LinkSmtpPassword/%1/%2").arg(host, user);
}

static QByteArray ft2LinkSmtpLine(QString const& text)
{
    return text.toUtf8() + "\r\n";
}

static QByteArray ft2LinkSmtpData(QString eml)
{
    eml.replace(QStringLiteral("\r\n"), QStringLiteral("\n"));
    eml.replace(QLatin1Char('\r'), QLatin1Char('\n'));
    QStringList lines = eml.split(QLatin1Char('\n'));
    QByteArray data;
    for (QString line : lines) {
        if (line.startsWith(QLatin1Char('.'))) {
            line.prepend(QLatin1Char('.'));
        }
        data += line.toUtf8();
        data += "\r\n";
    }
    data += ".\r\n";
    return data;
}

static QString normalizeUtcDisplayToken(QString raw)
{
    QString const original = raw.trimmed();
    auto validSixDigitTime = [] (QString const& token) {
        if (token.size() != 6) {
            return false;
        }
        bool hhOk = false;
        bool mmOk = false;
        bool ssOk = false;
        int const hh = token.left(2).toInt(&hhOk);
        int const mm = token.mid(2, 2).toInt(&mmOk);
        int const ss = token.mid(4, 2).toInt(&ssOk);
        return hhOk && mmOk && ssOk
            && hh >= 0 && hh <= 23
            && mm >= 0 && mm <= 59
            && ss >= 0 && ss <= 59;
    };

    for (int i = 0; i + 7 < original.size(); ++i) {
        if (original.at(i).isDigit()
            && original.at(i + 1).isDigit()
            && original.at(i + 2) == QLatin1Char(':')
            && original.at(i + 3).isDigit()
            && original.at(i + 4).isDigit()
            && original.at(i + 5) == QLatin1Char(':')
            && original.at(i + 6).isDigit()
            && original.at(i + 7).isDigit()) {
            QString const token = original.mid(i, 2) + original.mid(i + 3, 2) + original.mid(i + 6, 2);
            if (validSixDigitTime(token)) {
                return token;
            }
        }
    }

    QString digits;
    digits.reserve(raw.size());
    for (QChar const ch : std::as_const(raw)) {
        if (ch >= QLatin1Char('0') && ch <= QLatin1Char('9')) {
            digits.append(ch);
        }
    }
    raw = digits;
    QTime const nowUtc = QDateTime::currentDateTimeUtc().time();
    if (raw.size() >= 6) {
        if (raw.size() >= 12) {
            QString const tail = raw.right(6);
            if (validSixDigitTime(tail)) {
                return tail;
            }
        }
        return raw.left(6);
    }
    if (raw.size() == 4) {
        return raw;
    }
    if (raw.isEmpty()) {
        return nowUtc.toString(QStringLiteral("HHmmss"));
    }
    return raw;
}

static int secondsFromUtcDisplayToken(QString raw)
{
    raw = normalizeUtcDisplayToken(raw);
    if (raw.size() >= 4) {
        bool hhOk = false;
        bool mmOk = false;
        int const hh = raw.left(2).toInt(&hhOk);
        int const mm = raw.mid(2, 2).toInt(&mmOk);
        if (!hhOk || !mmOk || hh < 0 || hh > 23 || mm < 0 || mm > 59) {
            return -1;
        }
        int ss = 0;
        if (raw.size() >= 6) {
            bool ssOk = false;
            ss = raw.mid(4, 2).toInt(&ssOk);
            if (!ssOk || ss < 0 || ss > 59) {
                return -1;
            }
        }
        return hh * 3600 + mm * 60 + ss;
    }
    return -1;
}

static int signedUtcSecondDelta(int earlierSeconds, int laterSeconds)
{
    if (earlierSeconds < 0 || laterSeconds < 0) {
        return 0;
    }
    int delta = laterSeconds - earlierSeconds;
    if (delta < -43200) {
        delta += 86400;
    } else if (delta > 43200) {
        delta -= 86400;
    }
    return delta;
}

// bridgeTxPeriodIsEven e autoSeqTxRank vivono in Sequencer/SequencerTiming
// (step D2 dell'estrazione): qui restano solo i using.
using decodium::seq::bridgeTxPeriodIsEven;
using decodium::seq::autoSeqTxRank;

static int replyTxPeriodForClickedDecode(QString const& mode,
                                         QString const& timeStr,
                                         int fallbackTxPeriod,
                                         int configuredPeriodMs = 0)
{
    int const msgSecond = secondsFromUtcDisplayToken(timeStr);
    if (msgSecond < 0) {
        return fallbackTxPeriod != 0 ? 1 : 0;
    }

    QString const normalizedMode = mode.trimmed().toUpper();
    if (normalizedMode == QStringLiteral("FT8")) {
        bool const dxIsFirstSequence = (msgSecond % 30) < 15;
        return dxIsFirstSequence ? 0 : 1;
    }
    if (normalizedMode == QStringLiteral("FT4")) {
        // FT4 second sequence starts at .5s (:07.5, :22.5, :37.5, :52.5)
        // but decoded rows are displayed as whole seconds (:07, :22, :37, :52).
        // Dividing the floored display second by 7500ms puts those rows in the
        // previous bucket and makes D4 transmit on top of the caller.
        bool const dxIsFirstSequence = (msgSecond % 15) < 7;
        return dxIsFirstSequence ? 0 : 1;
    }

    int pMs = 0;
    if (normalizedMode == QStringLiteral("FT2")) {
        pMs = 3750;
    } else if (normalizedMode == QStringLiteral("MSK144")) {
        pMs = configuredPeriodMs > 0 ? configuredPeriodMs : 15000;
    }
    if (pMs <= 0) {
        return fallbackTxPeriod != 0 ? 1 : 0;
    }
    // P0 fix (log ZL3DMH/ZL1BW 2026-06-11): la label e' troncata ai secondi
    // interi -> lo slot FT2 :18.75 diventa "18" e 18000/3750=4 (pari) invece
    // di 5 (dispari): parita' di mira sbagliata in 12 posizioni su 16 -> la
    // risposta atterra nello stesso sub-slot del CQer (sordita' reciproca,
    // 93% di overlap RF misurato). Round-to-nearest: identico al fix FT4
    // documentato sopra; corregge tutte le 16 posizioni e copre anche MSK144.
    int const dxPidx = (msgSecond * 1000 + pMs / 2) / pMs;
    return dxPidx % 2;
}

static QString decodeDedupKey(QString const& time,
                              QString const& freq,
                              QString const& message)
{
    return normalizeUtcDisplayToken(time).trimmed()
        + QLatin1Char('|')
        + freq.trimmed()
        + QLatin1Char('|')
        + canonicalDecodeMessage(message);
}

static constexpr int kFt2AsyncUiDedupeFallbackWindowMs = 3750;
static constexpr int kFt2AsyncAutoSeqDedupeSeconds = 9;
static constexpr int kFt2AsyncAutoSeqDedupeMs = kFt2AsyncAutoSeqDedupeSeconds * 1000;

// FT2 async turbo (100ms windows): lo stage7 DSP può riportare lo stesso messaggio
// in scansioni consecutive con freq leggermente diversa (±1-10 Hz di jitter). Quantizza
// la frequenza in bucket da 20 Hz così gli stessi decode non producono righe duplicate
// nello stesso slot, ma senza attraversare slot FT2 successivi.
static QString decodeDedupKeyFt2Async(QString const& time,
                                      QString const& freq,
                                      QString const& message,
                                      qint64 timestampMs = 0)
{
    bool ok = false;
    int const f = freq.trimmed().toInt(&ok);
    QString const fBucket = ok ? QString::number((f / 20) * 20) : freq.trimmed();
    QString timeToken = normalizeUtcDisplayToken(time).trimmed();
    if (timeToken.isEmpty() && timestampMs > 0) {
        timeToken = QStringLiteral("@ft2slot")
            + QString::number(timestampMs / kFt2AsyncUiDedupeFallbackWindowMs);
    }
    return timeToken
        + QLatin1Char('|')
        + fBucket
        + QLatin1Char('|')
        + canonicalDecodeMessage(message);
}

static int legacyDepthBitsToModernDepth(int legacyBits)
{
    int depth = legacyBits & 0x7;
    if (depth <= 0) {
        depth = 3;
    }
    if (legacyBits & 0xF0) {
        depth = 4;
    }
    return qBound(1, depth, 4);
}

static int modernDepthToLegacyBits(int depth, bool avgDecodeEnabled, bool deepSearchEnabled)
{
    int bits = qBound(1, depth, 3);
    if (avgDecodeEnabled) {
        bits |= 0x10;
    }
    if (deepSearchEnabled) {
        bits |= 0x20;
    }
    return bits;
}

static QDateTime approxUtcDateTimeForDisplayToken(QString const& utcToken)
{
    QDateTime nowUtc = QDateTime::currentDateTimeUtc();
    QString const normalized = normalizeUtcDisplayToken(utcToken);

    QTime decodedTime;
    if (normalized.size() >= 6) {
        decodedTime = QTime::fromString(normalized.left(6), QStringLiteral("hhmmss"));
    } else if (normalized.size() == 4) {
        decodedTime = QTime::fromString(normalized, QStringLiteral("hhmm"));
    }

    if (!decodedTime.isValid()) {
        return nowUtc;
    }

    QDate decodedDate = nowUtc.date();
    if (decodedTime > nowUtc.time().addSecs(60)) {
        decodedDate = decodedDate.addDays(-1);
    }

    nowUtc.setDate(decodedDate);
    nowUtc.setTime(decodedTime);
    return nowUtc;
}

static qint64 decodeEntryTimestampMsecs(QString const& utcToken, qint64 fallbackMs)
{
    if (utcToken.trimmed().isEmpty()) {
        return fallbackMs;
    }

    QDateTime const approxUtc = approxUtcDateTimeForDisplayToken(utcToken);
    if (!approxUtc.isValid()) {
        return fallbackMs;
    }
    return approxUtc.toMSecsSinceEpoch();
}

static qint64 decodeDisplaySortMsecsFromTime(QString const& normalizedTime, QDateTime const& nowUtc)
{
    int const decodeSeconds = secondsFromUtcDisplayToken(normalizedTime);
    if (decodeSeconds < 0) {
        return std::numeric_limits<qint64>::max();
    }

    QDate decodedDate = nowUtc.date();
    int const nowSeconds = nowUtc.time().msecsSinceStartOfDay() / 1000;
    int const deltaSeconds = decodeSeconds - nowSeconds;
    if (deltaSeconds > 60) {
        decodedDate = decodedDate.addDays(-1);
    } else if (deltaSeconds < -86340) {
        decodedDate = decodedDate.addDays(1);
    }

    QTime decodedTime(0, 0, 0);
    decodedTime = decodedTime.addSecs(decodeSeconds);
    return QDateTime(decodedDate, decodedTime, Qt::UTC).toMSecsSinceEpoch();
}

static qint64 decodeDisplaySortMsecs(QVariantMap const& entry, QDateTime const& nowUtc)
{
    // 1.0.139: preferisci entry["timestamp"] ms epoch (sempre popolato in FT2
    // async, dove entry["time"] è vuoto — vedi commento riga ~18734 e fix
    // dedup 1.0.136). Se manca, fallback al parsing del campo time. Senza
    // questa preferenza i decode FT2 async finivano tutti con sortMsecs =
    // INT_MAX e venivano mescolati a entries con time valido (es. quelle
    // mirrorate da ALL.TXT legacy) → ordinamento sporadico, vecchie entries
    // potevano apparire "fresche" in cima alla list visibile.
    QString const normalizedTime = normalizeUtcDisplayToken(entry.value(QStringLiteral("time")).toString());
    if (entry.value(QStringLiteral("isTx")).toBool()) {
        qint64 const txVisualSortMs = decodeDisplaySortMsecsFromTime(normalizedTime, nowUtc);
        if (txVisualSortMs != std::numeric_limits<qint64>::max()) {
            return txVisualSortMs;
        }
    }

    qulonglong const tsMs = entry.value(QStringLiteral("timestamp")).toULongLong();
    if (tsMs > 0) {
        return static_cast<qint64>(tsMs);
    }

    return decodeDisplaySortMsecsFromTime(normalizedTime, nowUtc);
}

static void sortDecodeEntriesChronologically(QVariantList& entries)
{
    struct IndexedEntry
    {
        QVariantMap entry;
        int originalIndex {0};
        qint64 sortMsecs {0};
        int freq {0};
        QString message;
        bool freqValid {false};
    };

    QVector<IndexedEntry> indexed;
    QDateTime const sortReferenceUtc = QDateTime::currentDateTimeUtc();
    indexed.reserve(entries.size());
    for (int i = 0; i < entries.size(); ++i) {
        QVariantMap entry = entries.at(i).toMap();
        bool freqOk = false;
        int const freq = entry.value(QStringLiteral("freq")).toString().trimmed().toInt(&freqOk);
        indexed.push_back(IndexedEntry {
            entry,
            i,
            decodeDisplaySortMsecs(entry, sortReferenceUtc),
            freq,
            entry.value(QStringLiteral("message")).toString().trimmed(),
            freqOk
        });
    }

    std::stable_sort(indexed.begin(), indexed.end(), [] (IndexedEntry const& lhs, IndexedEntry const& rhs) {
        bool const lhsValid = lhs.sortMsecs != std::numeric_limits<qint64>::max();
        bool const rhsValid = rhs.sortMsecs != std::numeric_limits<qint64>::max();
        if (lhsValid != rhsValid) {
            return lhsValid;
        }
        if (lhs.sortMsecs != rhs.sortMsecs) {
            return lhs.sortMsecs < rhs.sortMsecs;
        }
        if (lhs.freqValid && rhs.freqValid && lhs.freq != rhs.freq) {
            return lhs.freq < rhs.freq;
        }
        int const msgCompare = QString::compare(lhs.message, rhs.message, Qt::CaseInsensitive);
        if (msgCompare != 0) {
            return msgCompare < 0;
        }
        return lhs.originalIndex < rhs.originalIndex;
    });

    QVariantList sorted;
    sorted.reserve(entries.size());
    for (IndexedEntry const& item : std::as_const(indexed)) {
        sorted.append(item.entry);
    }
    entries = sorted;
}

static int displayDedupPeriodMsForMode(QString mode)
{
    mode = mode.trimmed().toUpper();
    if (mode == QStringLiteral("FT2")) return 3750;
    if (mode == QStringLiteral("FT4")) return 7500;
    if (mode == QStringLiteral("FT8")) return 15000;
    return 0;
}

static QString decodeDisplayTimeKey(QString const& time, QString const& mode)
{
    QString const normalized = normalizeUtcDisplayToken(time).trimmed();
    int const periodMs = displayDedupPeriodMsForMode(mode);
    if (periodMs <= 0) {
        return normalized;
    }

    QDateTime const approxUtc = approxUtcDateTimeForDisplayToken(normalized);
    if (!approxUtc.isValid()) {
        return normalized;
    }

    qint64 const slotIndex = approxUtc.toMSecsSinceEpoch() / static_cast<qint64>(periodMs);
    QTime const slotTime = QDateTime::fromMSecsSinceEpoch(slotIndex * static_cast<qint64>(periodMs), Qt::UTC).time();
    return slotTime.toString(QStringLiteral("HHmmss"));
}

static QString decodeDisplayFrequencyKey(QString const& freq, QString const& mode)
{
    bool ok = false;
    int const value = freq.trimmed().toInt(&ok);
    if (!ok) {
        return freq.trimmed();
    }

    int const bucketHz = displayDedupPeriodMsForMode(mode) > 0 ? 20 : 1;
    return QString::number(qRound(static_cast<double>(value) / bucketHz) * bucketHz);
}

static QString decodeDisplayDuplicateKey(QVariantMap const& entry, QString const& fallbackMode)
{
    QString const message = canonicalDecodeMessage(entry.value(QStringLiteral("message")).toString());
    if (message.isEmpty()) {
        return {};
    }

    QString mode = entry.value(QStringLiteral("mode")).toString().trimmed().toUpper();
    if (mode.isEmpty()) {
        mode = fallbackMode.trimmed().toUpper();
    }

    return mode
        + QLatin1Char('|')
        + decodeDisplayTimeKey(entry.value(QStringLiteral("time")).toString(), mode)
        + QLatin1Char('|')
        + decodeDisplayFrequencyKey(entry.value(QStringLiteral("freq")).toString(), mode)
        + QLatin1Char('|')
        + message
        + QLatin1Char('|')
        + (entry.value(QStringLiteral("isTx")).toBool() ? QStringLiteral("1") : QStringLiteral("0"));
}

static int decodeDisplayEntryScore(QVariantMap const& entry)
{
    int score = 0;
    if (normalizeUtcDisplayToken(entry.value(QStringLiteral("time")).toString()).size() >= 6) {
        score += 10000;
    }
    if (!entry.value(QStringLiteral("dxCountry")).toString().trimmed().isEmpty()) {
        score += 1000;
    }

    bool qualityOk = false;
    int const quality = entry.value(QStringLiteral("quality")).toString().trimmed().toInt(&qualityOk);
    if (qualityOk) {
        score += qBound(0, quality, 100);
    }

    bool snrOk = false;
    int const snr = entry.value(QStringLiteral("db")).toString().trimmed().toInt(&snrOk);
    if (snrOk) {
        score += qBound(-99, snr, 99) + 100;
    }
    return score;
}

static void coalesceDecodeEntriesForDisplay(QVariantList& entries, QString const& fallbackMode)
{
    QHash<QString, int> keptIndexByKey;
    for (int i = 0; i < entries.size(); ) {
        QVariantMap const entry = entries.at(i).toMap();
        QString const key = decodeDisplayDuplicateKey(entry, fallbackMode);
        if (key.isEmpty()) {
            ++i;
            continue;
        }

        auto const it = keptIndexByKey.constFind(key);
        if (it == keptIndexByKey.constEnd()) {
            keptIndexByKey.insert(key, i);
            ++i;
            continue;
        }

        int const keptIndex = it.value();
        QVariantMap const keptEntry = entries.at(keptIndex).toMap();
        if (decodeDisplayEntryScore(entry) > decodeDisplayEntryScore(keptEntry)) {
            entries[keptIndex] = entry;
        }
        entries.removeAt(i);
    }
}

static void normalizeDecodeEntriesForDisplay(QVariantList& entries,
                                             int maxEntries = 1500,
                                             QString const& fallbackMode = QString())
{
    coalesceDecodeEntriesForDisplay(entries, fallbackMode);
    sortDecodeEntriesChronologically(entries);
    if (maxEntries > 0 && entries.size() > maxEntries) {
        entries = entries.mid(entries.size() - maxEntries);
    }
}

static int utcTokenForSlotStart(qint64 slotIndex, int periodMs)
{
    if (slotIndex < 0 || periodMs <= 0) {
        return 0;
    }

    qint64 const slotStartMs = slotIndex * static_cast<qint64>(periodMs);
    QTime const slotTime = QDateTime::fromMSecsSinceEpoch(slotStartMs, Qt::UTC).time();
    if (periodMs < 60000) {
        return slotTime.hour() * 10000 + slotTime.minute() * 100 + slotTime.second();
    }
    return slotTime.hour() * 100 + slotTime.minute();
}

static QString utcDisplayTokenForSlotStart(qint64 slotIndex, int periodMs)
{
    if (slotIndex < 0 || periodMs <= 0) {
        return QString();
    }

    qint64 const slotStartMs = slotIndex * static_cast<qint64>(periodMs);
    QTime const slotTime = QDateTime::fromMSecsSinceEpoch(slotStartMs, Qt::UTC).time();
    QString const fmt = periodMs < 60000 ? QStringLiteral("HHmmss")
                                         : QStringLiteral("HHmm");
    return slotTime.toString(fmt);
}

struct ParsedAdifRecord
{
    QMap<QString, QString> fields;
};

struct ParsedAdifDocument
{
    QString header;
    QList<ParsedAdifRecord> records;
    bool loaded {false};
};

static QString freqHzToBandToken(quint64 freqHz);

static QString adifDigitsOnly(QString const& value)
{
    QString digits;
    digits.reserve(value.size());
    for (QChar const& ch : value.trimmed()) {
        if (ch.isDigit()) {
            digits.append(ch);
        }
    }
    return digits;
}

static QString normalizedAdifDateToken(QString const& value)
{
    QString const digits = adifDigitsOnly(value);
    return digits.size() >= 8 ? digits.left(8) : QString {};
}

static QString normalizedAdifTimeToken(QString const& value)
{
    QString const digits = adifDigitsOnly(value);
    if (digits.isEmpty()) {
        return {};
    }
    return digits.leftJustified(6, QLatin1Char('0')).left(6);
}

static QString normalizeAdifModeForDisplay(QMap<QString, QString> const& fields)
{
    QString const submode = fields.value(QStringLiteral("SUBMODE")).trimmed().toUpper();
    if (!submode.isEmpty()) {
        return submode;
    }
    return fields.value(QStringLiteral("MODE")).trimmed().toUpper();
}

static QString normalizedAdifDateTime(QMap<QString, QString> const& fields)
{
    QString const date = normalizedAdifDateToken(fields.value(QStringLiteral("QSO_DATE")));
    if (date.size() != 8) {
        return {};
    }
    QString time = normalizedAdifTimeToken(fields.value(QStringLiteral("TIME_ON")));
    if (time.isEmpty()) {
        time = normalizedAdifTimeToken(fields.value(QStringLiteral("TIME_OFF")));
    }
    QDateTime utc = QDateTime::fromString(date + time, QStringLiteral("yyyyMMddHHmmss"));
    utc.setTimeSpec(Qt::UTC);
    return utc.isValid() ? utc.toString(QStringLiteral("yyyy-MM-dd HH:mm:ss")) : QString {};
}

static quint64 adifFrequencyHzFromFields(QMap<QString, QString> const& fields)
{
    QString freqMhzText = fields.value(QStringLiteral("FREQ")).trimmed();
    if (freqMhzText.isEmpty()) {
        freqMhzText = fields.value(QStringLiteral("FREQ_RX")).trimmed();
    }
    if (freqMhzText.isEmpty()) {
        return 0;
    }

    freqMhzText.replace(QLatin1Char(','), QLatin1Char('.'));
    bool ok = false;
    double const freqMhz = freqMhzText.toDouble(&ok);
    if (!ok || freqMhz <= 0.0) {
        return 0;
    }
    return static_cast<quint64>(freqMhz * 1'000'000.0 + 0.5);
}

static QString adifBandFromFields(QMap<QString, QString> const& fields)
{
    QString const band = fields.value(QStringLiteral("BAND")).trimmed().toUpper();
    if (!band.isEmpty()) {
        return band;
    }

    quint64 const freqHz = adifFrequencyHzFromFields(fields);
    return freqHz > 0 ? freqHzToBandToken(freqHz).toUpper() : QString {};
}

static QVariantMap qsoMapFromAdifRecord(QMap<QString, QString> const& fields, QString const& myGrid)
{
    QVariantMap map;
    QString const call = fields.value(QStringLiteral("CALL")).trimmed().toUpper();
    QString const grid = fields.value(QStringLiteral("GRIDSQUARE")).trimmed().toUpper();
    QString const band = adifBandFromFields(fields);
    QString const mode = normalizeAdifModeForDisplay(fields);
    QString const dateTime = normalizedAdifDateTime(fields);
    QString const reportSent = fields.value(QStringLiteral("RST_SENT")).trimmed().toUpper();
    QString const reportReceived = fields.value(QStringLiteral("RST_RCVD")).trimmed().toUpper();
    QString const comment = fields.value(QStringLiteral("COMMENT")).trimmed();

    map.insert(QStringLiteral("call"), call);
    map.insert(QStringLiteral("grid"), grid);
    map.insert(QStringLiteral("band"), band);
    map.insert(QStringLiteral("mode"), mode);
    map.insert(QStringLiteral("dateTime"), dateTime);
    map.insert(QStringLiteral("reportSent"), reportSent);
    map.insert(QStringLiteral("reportReceived"), reportReceived);
    map.insert(QStringLiteral("comment"), comment);

    if (!myGrid.trimmed().isEmpty() && !grid.isEmpty()) {
        GeoDistanceInfo const geo = geo_distance(myGrid.trimmed().toUpper(), grid, 0.0);
        if (geo.km > 0) {
            map.insert(QStringLiteral("distanceKm"), geo.km);
        }
    }

    return map;
}

static ParsedAdifRecord normalizeImportedAdifRecord(ParsedAdifRecord record)
{
    auto normalizeUpperField = [&record](QString const& key) mutable {
        QString const value = record.fields.value(key).trimmed().toUpper();
        if (value.isEmpty()) {
            record.fields.remove(key);
        } else {
            record.fields.insert(key, value);
        }
    };

    normalizeUpperField(QStringLiteral("CALL"));
    normalizeUpperField(QStringLiteral("GRIDSQUARE"));
    normalizeUpperField(QStringLiteral("BAND"));
    normalizeUpperField(QStringLiteral("MODE"));
    normalizeUpperField(QStringLiteral("SUBMODE"));
    normalizeUpperField(QStringLiteral("RST_SENT"));
    normalizeUpperField(QStringLiteral("RST_RCVD"));

    QString const date = normalizedAdifDateToken(record.fields.value(QStringLiteral("QSO_DATE")));
    if (!date.isEmpty()) {
        record.fields.insert(QStringLiteral("QSO_DATE"), date);
    }

    QString time = normalizedAdifTimeToken(record.fields.value(QStringLiteral("TIME_ON")));
    if (time.isEmpty()) {
        time = normalizedAdifTimeToken(record.fields.value(QStringLiteral("TIME_OFF")));
    }
    if (!time.isEmpty()) {
        record.fields.insert(QStringLiteral("TIME_ON"), time);
    }

    QString const band = adifBandFromFields(record.fields);
    if (!band.isEmpty()) {
        record.fields.insert(QStringLiteral("BAND"), band);
    }

    return record;
}

static QString adifRecordDedupeKey(QMap<QString, QString> const& fields)
{
    QString const call = fields.value(QStringLiteral("CALL")).trimmed().toUpper();
    if (call.isEmpty()) {
        return {};
    }

    QString const dateTime = normalizedAdifDateTime(fields);
    QString const mode = normalizeAdifModeForDisplay(fields);
    QString const band = adifBandFromFields(fields);
    if (!dateTime.isEmpty()) {
        return QStringList { call, dateTime, mode, band }.join(QLatin1Char('|'));
    }

    QString time = normalizedAdifTimeToken(fields.value(QStringLiteral("TIME_ON")));
    if (time.isEmpty()) {
        time = normalizedAdifTimeToken(fields.value(QStringLiteral("TIME_OFF")));
    }

    return QStringList {
        call,
        QStringLiteral("RAW"),
        normalizedAdifDateToken(fields.value(QStringLiteral("QSO_DATE"))),
        time,
        mode,
        band,
        fields.value(QStringLiteral("FREQ")).trimmed(),
        fields.value(QStringLiteral("RST_SENT")).trimmed().toUpper(),
        fields.value(QStringLiteral("RST_RCVD")).trimmed().toUpper(),
        fields.value(QStringLiteral("GRIDSQUARE")).trimmed().toUpper()
    }.join(QLatin1Char('|'));
}

constexpr qint64 kMaxAdifDocumentBytes = 32LL * 1024LL * 1024LL;
constexpr int kMaxAdifRecords = 200000;
constexpr int kMaxAdifFieldBytes = 65536;
constexpr int kMaxAdifFieldsPerRecord = 128;

static QList<ParsedAdifRecord> parseAdifRecordsBytes(QByteArray const& bodyBytes)
{
    QList<ParsedAdifRecord> records;
    ParsedAdifRecord record;
    int fieldsInRecord = 0;
    int cursor = 0;
    while (cursor < bodyBytes.size()) {
        if (records.size() >= kMaxAdifRecords) {
            qWarning().noquote() << "[ADIF] record cap reached while parsing log:" << kMaxAdifRecords;
            break;
        }

        int const tagStart = bodyBytes.indexOf('<', cursor);
        if (tagStart < 0) {
            break;
        }
        int const tagEnd = bodyBytes.indexOf('>', tagStart + 1);
        if (tagEnd < 0) {
            break;
        }

        QByteArray const spec = bodyBytes.mid(tagStart + 1, tagEnd - tagStart - 1).trimmed();
        QByteArray const specLower = spec.toLower();
        if (specLower == "eor") {
            if (!record.fields.isEmpty()) {
                records.append(record);
                record = ParsedAdifRecord {};
                fieldsInRecord = 0;
            }
            cursor = tagEnd + 1;
            continue;
        }
        if (specLower == "eoh") {
            record = ParsedAdifRecord {};
            fieldsInRecord = 0;
            cursor = tagEnd + 1;
            continue;
        }

        int const lengthSeparator = spec.indexOf(':');
        if (lengthSeparator <= 0) {
            cursor = tagEnd + 1;
            continue;
        }

        QByteArray const fieldNameBytes = spec.left(lengthSeparator).trimmed().toUpper();
        QByteArray lengthBytes = spec.mid(lengthSeparator + 1);
        int const typeSeparator = lengthBytes.indexOf(':');
        if (typeSeparator >= 0) {
            lengthBytes = lengthBytes.left(typeSeparator);
        }
        lengthBytes = lengthBytes.trimmed();

        bool ok = false;
        int const valueLength = lengthBytes.toInt(&ok);
        if (!ok || valueLength < 0) {
            cursor = tagEnd + 1;
            continue;
        }

        int const valueStart = tagEnd + 1;
        if (valueStart > bodyBytes.size()) {
            break;
        }

        int const available = bodyBytes.size() - valueStart;
        if (valueLength > available) {
            qWarning().noquote() << "[ADIF] truncated field discarded at byte" << valueStart;
            break;
        }
        if (valueLength > kMaxAdifFieldBytes) {
            qWarning().noquote() << "[ADIF] oversized field discarded at byte" << valueStart
                                 << "length" << valueLength;
            cursor = valueStart + valueLength;
            continue;
        }
        if (fieldsInRecord >= kMaxAdifFieldsPerRecord) {
            cursor = valueStart + valueLength;
            continue;
        }

        QByteArray const valueBytes = bodyBytes.mid(valueStart, valueLength);
        QString const fieldName = QString::fromLatin1(fieldNameBytes).trimmed().toUpper();
        QString const value = QString::fromUtf8(valueBytes).trimmed();
        if (!fieldName.isEmpty()) {
            record.fields.insert(fieldName, value);
            ++fieldsInRecord;
        }
        cursor = valueStart + valueLength;
    }

    if (!record.fields.isEmpty() && records.size() < kMaxAdifRecords) {
        records.append(record);
    }
    return records;
}

static ParsedAdifDocument loadAdifDocument(QString const& path)
{
    ParsedAdifDocument doc;
    QFile file(path);
    if (!file.exists()) {
        doc.header = QStringLiteral("Decodium4 ADIF Log\n<EOH>\n");
        return doc;
    }
    QFileInfo const info(path);
    if (info.size() > kMaxAdifDocumentBytes) {
        doc.header = QStringLiteral("Decodium4 ADIF Log\n<EOH>\n");
        qWarning().noquote() << "[ADIF] skipped oversized ADIF document"
                             << path
                             << "size" << info.size()
                             << "limit" << kMaxAdifDocumentBytes;
        return doc;
    }
    if (!file.open(QIODevice::ReadOnly)) {
        return doc;
    }

    QByteArray raw = file.readAll();
    file.close();
    if (raw.startsWith("\xEF\xBB\xBF")) {
        raw.remove(0, 3);
    }

    QByteArray const rawLower = raw.toLower();
    int const eohStart = rawLower.indexOf("<eoh>");
    QByteArray body = raw;
    if (eohStart >= 0) {
        int const eohEnd = eohStart + 5;
        doc.header = QString::fromUtf8(raw.left(eohEnd)).trimmed() + QLatin1Char('\n');
        body = raw.mid(eohEnd);
    } else {
        doc.header = QStringLiteral("Decodium4 ADIF Log\n<EOH>\n");
    }

    doc.records = parseAdifRecordsBytes(body);
    doc.loaded = true;
    return doc;
}

static bool writeAdifDocument(QString const& path, ParsedAdifDocument const& doc)
{
    QDir().mkpath(QFileInfo(path).absolutePath());
    QFile file(path);
    if (!file.open(QIODevice::WriteOnly | QIODevice::Text | QIODevice::Truncate)) {
        return false;
    }

    QTextStream ts(&file);
    ts << (doc.header.isEmpty() ? QStringLiteral("Decodium4 ADIF Log\n<EOH>\n") : doc.header);
    if (!doc.header.endsWith(QLatin1Char('\n'))) {
        ts << '\n';
    }

    auto writeField = [&ts](QString const& tag, QString const& value) {
        if (!tag.isEmpty() && !value.isNull() && !value.isEmpty()) {
            ts << '<' << tag << ':' << value.toUtf8().size() << '>' << value << ' ';
        }
    };

    for (ParsedAdifRecord const& record : doc.records) {
        for (auto it = record.fields.cbegin(); it != record.fields.cend(); ++it) {
            writeField(it.key(), it.value());
        }
        ts << "<EOR>\n";
    }
    return true;
}

// Map a frequency in Hz to the standard band token used by ADIF / WSJT-X
// (e.g. "20m"). Returns empty string for invalid/out-of-range frequencies.
static QString freqHzToBandToken(quint64 freqHz)
{
    const double mhz = freqHz / 1'000'000.0;
    if      (mhz <  1.8)   return QString();
    else if (mhz <  2.0)   return QStringLiteral("160m");
    else if (mhz <  4.0)   return QStringLiteral("80m");
    else if (mhz <  6.0)   return QStringLiteral("60m");
    else if (mhz <  8.0)   return QStringLiteral("40m");
    else if (mhz < 11.0)   return QStringLiteral("30m");
    else if (mhz < 15.0)   return QStringLiteral("20m");
    else if (mhz < 19.0)   return QStringLiteral("17m");
    else if (mhz < 22.0)   return QStringLiteral("15m");
    else if (mhz < 25.0)   return QStringLiteral("12m");
    else if (mhz < 30.0)   return QStringLiteral("10m");
    else if (mhz < 52.0)   return QStringLiteral("6m");
    else if (mhz < 150.0)  return QStringLiteral("2m");
    else if (mhz < 440.0)  return QStringLiteral("70cm");
    else                    return QString();
}

static void rebuildWorkedCallsFromDocument(QSet<QString>& workedCalls, QList<ParsedAdifRecord> const& records)
{
    workedCalls.clear();
    for (ParsedAdifRecord const& record : records) {
        QString const call = record.fields.value(QStringLiteral("CALL")).trimmed().toUpper();
        if (!call.isEmpty()) {
            workedCalls.insert(call);
        }
    }
}

static int countAdifRecordsLightweight(QString const& path)
{
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) {
        return 0;
    }

    int count = 0;
    QByteArray carry;
    while (!file.atEnd()) {
        QByteArray chunk = carry + file.read(64 * 1024).toUpper();
        int cursor = 0;
        while (true) {
            int const pos = chunk.indexOf("<EOR", cursor);
            if (pos < 0) {
                break;
            }
            ++count;
            cursor = pos + 4;
        }
        carry = chunk.right(3);
    }
    return count;
}

struct QsoLogSnapshot
{
    QString path;
    QDateTime modified;
    qint64 size {-1};
    QVariantList rows;
    QVariantMap stats;
};

static QVariantMap qsoStatsFromRows(QVariantList const& rows)
{
    QSet<QString> uniqueCalls;
    QSet<QString> uniqueGrids;
    int maxDistance = 0;
    QString farthestCall;

    for (QVariant const& rowValue : rows) {
        QVariantMap const row = rowValue.toMap();
        QString const call = row.value(QStringLiteral("call")).toString().trimmed().toUpper();
        QString const grid = row.value(QStringLiteral("grid")).toString().trimmed().toUpper();
        int const distanceKm = row.value(QStringLiteral("distanceKm")).toInt();
        if (!call.isEmpty()) {
            uniqueCalls.insert(call);
        }
        if (!grid.isEmpty()) {
            uniqueGrids.insert(grid);
        }
        if (distanceKm > maxDistance) {
            maxDistance = distanceKm;
            farthestCall = call;
        }
    }

    QVariantMap stats;
    stats.insert(QStringLiteral("totalQsos"), rows.size());
    stats.insert(QStringLiteral("uniqueCalls"), uniqueCalls.size());
    stats.insert(QStringLiteral("uniqueGrids"), uniqueGrids.size());
    stats.insert(QStringLiteral("maxDistance"), maxDistance);
    stats.insert(QStringLiteral("farthestCall"), farthestCall);
    return stats;
}

static QsoLogSnapshot buildQsoLogSnapshot(QString const& path, QString const& myGrid)
{
    QElapsedTimer timer;
    timer.start();

    QFileInfo const info(path);
    QsoLogSnapshot snapshot;
    snapshot.path = path;
    snapshot.modified = info.exists() ? info.lastModified() : QDateTime();
    snapshot.size = info.exists() ? info.size() : 0;

    ParsedAdifDocument const doc = loadAdifDocument(path);
    QList<QVariantMap> sortedRows;
    sortedRows.reserve(doc.records.size());
    for (ParsedAdifRecord const& record : doc.records) {
        sortedRows.append(qsoMapFromAdifRecord(record.fields, myGrid));
    }

    std::sort(sortedRows.begin(), sortedRows.end(), [] (QVariantMap const& lhs, QVariantMap const& rhs) {
        return lhs.value(QStringLiteral("dateTime")).toString()
             > rhs.value(QStringLiteral("dateTime")).toString();
    });

    snapshot.rows.reserve(sortedRows.size());
    for (QVariantMap const& row : sortedRows) {
        snapshot.rows.append(row);
    }
    snapshot.stats = qsoStatsFromRows(snapshot.rows);

    if (timer.elapsed() > 250) {
        DIAG_INFO(QStringLiteral("QSO log cache built: records=%1 elapsed=%2ms path=%3")
                      .arg(snapshot.rows.size())
                      .arg(timer.elapsed())
                      .arg(path));
    }
    return snapshot;
}

static void setAdifModeFields(QMap<QString, QString>& fields, QString const& modeValue)
{
    QString const normalized = modeValue.trimmed().toUpper();
    if (normalized.isEmpty()) {
        return;
    }

    if (normalized == QStringLiteral("FT2")
        || normalized == QStringLiteral("FT4")
        || normalized == QStringLiteral("FST4")
        || normalized == QStringLiteral("Q65")
        || normalized.startsWith(QStringLiteral("Q65-"))) {
        fields.insert(QStringLiteral("MODE"), QStringLiteral("MFSK"));
        fields.insert(QStringLiteral("SUBMODE"), normalized);
        return;
    }

    fields.insert(QStringLiteral("MODE"), normalized);
    fields.remove(QStringLiteral("SUBMODE"));
}

