static bool isPlainSignalReportToken(QString const& token)
{
    static const QRegularExpression plainReportPattern {
        R"(\A[-+]\d{2}\z)"
    };
    return plainReportPattern.match(normalizeCallToken(token).toUpper()).hasMatch();
}

static bool isRogerSignalReportToken(QString const& token)
{
    static const QRegularExpression rogerReportPattern {
        R"(\A(?:R[-+]\d{2}|R\d{2})\z)"
    };
    return rogerReportPattern.match(normalizeCallToken(token).toUpper()).hasMatch();
}

static bool isQsoSignoffToken(QString const& token)
{
    QString const upper = normalizeCallToken(token).toUpper();
    return upper == QStringLiteral("73")
        || upper == QStringLiteral("RR73")
        || upper == QStringLiteral("RRR");
}

static bool isDirectedDecodeTerminalToken(QString const& token)
{
    QString const upper = normalizeCallToken(token).toUpper();
    return isQsoSignoffToken(upper)
        || isGridTokenStrict(upper)
        || isPlainSignalReportToken(upper)
        || isRogerSignalReportToken(upper);
}

// 1.0.373 - ghost strutturale FT2/FT8: token "R" NUDO (singola lettera) seguito da un
// grid valido (es. "CALL1 CALL2 R MK86", "CQ CALL/P R LD05"). Nessun tipo-messaggio
// 77-bit standard produce "R <GRID>" (l'exchange con R e' "CALL CALL R-NN", mai "R GRID";
// un CQ valido e' "CQ CALL GRID" senza R). Tipico falso-positivo LDPC a SNR basso con
// callsign compound spazzatura. Sicuro: NON confonde R-12/R+05/Rdd (token interi != "R")
// ne' RR73 col token "R" nudo. Default-ON: un TX conforme non lo genera mai.
static bool looksLikeMalformedRGrid(QString const& msgText)
{
    QStringList const tokens = msgText.split(QLatin1Char(' '), Qt::SkipEmptyParts);
    for (int i = 0; i + 1 < tokens.size(); ++i) {
        if (tokens[i].trimmed().toUpper() == QStringLiteral("R")
            && isGridTokenStrict(tokens[i + 1].trimmed().toUpper())) {
            return true;
        }
    }
    return false;
}

static bool hasPortableOperatingDesignator(QString const& token)
{
    QString const upper = normalizeCallToken(token).trimmed().toUpper();
    int const slashIdx = upper.lastIndexOf(QLatin1Char('/'));
    if (slashIdx <= 0 || slashIdx >= upper.size() - 1) {
        return false;
    }

    QString const suffix = upper.mid(slashIdx + 1);
    static const QSet<QString> portableSuffixes {
        QStringLiteral("P"), QStringLiteral("M"), QStringLiteral("MM"),
        QStringLiteral("AM"), QStringLiteral("A"), QStringLiteral("R"),
        QStringLiteral("QRP"), QStringLiteral("PM"), QStringLiteral("MA")
    };
    return portableSuffixes.contains(suffix);
}

// Sanity gate per callsign — rifiuta i ghost del decoder LDPC.
// Pattern ITU-R 19.68: prefisso (1-2 lettere | lettera+cifra | cifra 2-9 + lettera)
// + cifra (0-9) + suffisso (1-4 lettere). Esempi rifiutati: 0Z4SYH, 0L0MYK,
// L74PVK, 6H9IV5Y0. Esempi accettati: IU8LMC, K1JT, 9A3A, EA5JMN, A29TTX/P.
// Strippa suffissi portatili comuni (/P /M /MM /AM /A /R /QRP) prima del check.
static bool isStrictAmateurCallsign(QString const& token)
{
    QString t = token.trimmed().toUpper();
    if (t.isEmpty()) return false;
    // Rimuovi suffisso portatile
    int const slashIdx = t.indexOf('/');
    if (slashIdx > 0) {
        QString const suffix = t.mid(slashIdx + 1);
        QString const prefix = t.left(slashIdx);
        // Suffix portatile: P/M/MM/AM/A/R/QRP — nessun digit
        // Prefix portatile country: es. F/IK8XYZ → tieni IK8XYZ
        static const QSet<QString> portableSuffixes {
            "P", "M", "MM", "AM", "A", "R", "QRP", "PM", "MA"
        };
        if (portableSuffixes.contains(suffix)) {
            t = prefix;
        } else if (portableSuffixes.contains(prefix) || (prefix.size() <= 3 && !prefix.contains(QRegularExpression(R"([0-9])")))) {
            t = suffix;
        }
    }
    if (t.size() < 3 || t.size() > 7) return false;
    static const QRegularExpression re(
        R"(^(?:[A-Z]{1,2}|[A-Z][0-9]|[2-9][A-Z])[0-9][A-Z]{1,4}$)"
    );
    return re.match(t).hasMatch();
}

static bool isSpecialEventStyleCallsign(QString const& token)
{
    QString t = normalizeCallToken(token).trimmed().toUpper();
    if (t.isEmpty() || isPlaceholderCallToken(t)) {
        return false;
    }

    QString const base = Radio::base_callsign(t).trimmed().toUpper();
    if (base.size() < 4 || base.size() > 10) {
        return false;
    }

    bool hasLetter = false;
    bool hasDigit = false;
    bool digitSeen = false;
    bool hasLetterBeforeDigit = false;
    bool hasLetterAfterDigit = false;
    bool allHex = true;
    int digitCount = 0;
    for (QChar const& ch : base) {
        if (ch.isLetter()) {
            hasLetter = true;
            if (!digitSeen) {
                hasLetterBeforeDigit = true;
            } else {
                hasLetterAfterDigit = true;
            }
            if (ch < QLatin1Char('A') || ch > QLatin1Char('F')) {
                allHex = false;
            }
        } else if (ch.isDigit()) {
            hasDigit = true;
            digitSeen = true;
            ++digitCount;
        } else {
            return false;
        }
    }

    if (!hasLetter || !hasDigit || digitCount < 2
        || !hasLetterBeforeDigit || !hasLetterAfterDigit) {
        return false;
    }
    if (allHex && base.size() >= 7) {
        return false;
    }
    return Radio::is_callsign(base);
}

static bool isPlausibleDecodedCallsign(QString const& token)
{
    return isStrictAmateurCallsign(token)
        || isSpecialEventStyleCallsign(token);
}

static QString customCqPrefixFromMessage(QString const& message, QString const& myCall)
{
    QStringList const tokens = message.trimmed().toUpper().split(QLatin1Char(' '), Qt::SkipEmptyParts);
    QString const call = normalizedTxCallToken(myCall);
    if (tokens.size() < 3 || tokens.first() != QStringLiteral("CQ") || call.isEmpty()) {
        return {};
    }

    int const callIndex = tokens.indexOf(call);
    if (callIndex <= 1) {
        return {};
    }
    return tokens.mid(0, callIndex).join(QLatin1Char(' '));
}

static QString ftxCqMessageWithCustomPrefix(QString const& standardMessage, QString const& customPrefix)
{
    QStringList const standardTokens = standardMessage.split(QLatin1Char(' '), Qt::SkipEmptyParts);
    QStringList const prefixTokens = customPrefix.trimmed().toUpper().split(QLatin1Char(' '), Qt::SkipEmptyParts);
    if (standardTokens.size() < 2 || standardTokens.first() != QStringLiteral("CQ")
        || prefixTokens.size() < 2 || prefixTokens.first() != QStringLiteral("CQ")) {
        return standardMessage;
    }
    return prefixTokens.join(QLatin1Char(' '))
        + QLatin1Char(' ')
        + standardTokens.mid(1).join(QLatin1Char(' '));
}

static bool isSyntheticLabCallsign(QString const& token)
{
    QString const base = Radio::base_callsign(normalizeCallToken(token))
                             .trimmed()
                             .toUpper();
    static const QRegularExpression re(R"(\ATEST[A-Z0-9]\z)");
    return re.match(base).hasMatch();
}

static int digitRunCount(QString const& token)
{
    int runs = 0;
    bool inDigitRun = false;
    for (QChar const& ch : token) {
        if (ch.isDigit()) {
            if (!inDigitRun) {
                ++runs;
                inDigitRun = true;
            }
        } else {
            inDigitRun = false;
        }
    }
    return runs;
}

static bool isPlausibleFt2CqCallsign(QString const& token)
{
    if (isStrictAmateurCallsign(token)) {
        return true;
    }
    if (!isSpecialEventStyleCallsign(token)) {
        return false;
    }

    QString const base = Radio::base_callsign(normalizeCallToken(token))
                             .trimmed()
                             .toUpper();
    // FT2 CQ false positives often pass the broad special-event gate as
    // long letter/digit soup with multiple separated numeric islands
    // (for example "CQ KS58OQ94M"). Real event calls normally have one
    // contiguous event number, while normal calls are accepted above.
    return digitRunCount(base) <= 1;
}

static bool isCqRoutingModifierToken(QString const& token)
{
    QString const upper = normalizeCallToken(token).trimmed().toUpper();
    if (isDirectedCqModifierToken(upper)) {
        return true;
    }
    static const QRegularExpression numericCqTag {
        R"(\A[0-9]{3}\z)"
    };
    return numericCqTag.match(upper).hasMatch();
}

static bool isValidFt2CqTrailingPayload(QStringList const& tokens,
                                        int callIdx,
                                        QString* reason)
{
    for (int i = callIdx + 1; i < tokens.size(); ++i) {
        QString const token = normalizeCallToken(tokens.at(i)).trimmed().toUpper();
        if (token == QStringLiteral("?")) {
            continue;
        }
        if (i == callIdx + 1 && isGridTokenStrict(token)) {
            continue;
        }
        if (reason) {
            *reason = QStringLiteral("FT2 CQ trailing payload invalid (ghost)");
        }
        return false;
    }
    return true;
}

static bool hasHighConfidenceGhostPrefix(QString const& callRaw)
{
    QString call = callRaw.trimmed().toUpper();
    int const slashIdx = call.indexOf('/');
    if (slashIdx > 0) call = call.left(slashIdx);
    if (call.size() < 2) return false;

    QString const prefix2 = call.left(2);
    if (prefix2.at(0) == QLatin1Char('0')) {
        return true;
    }
    if (prefix2.at(0) == QLatin1Char('1') && prefix2 != QStringLiteral("1A")) {
        return true;
    }

    static const QSet<QString> impossiblePrefixes {
        "H1", "ZH", "ZQ",
        // 1.0.224 — VZ non e' assegnato da ITU (V* assegnati: VA-VG, VK-VO, VP-VV, VX-VY).
        // HE non aggiunto: Switzerland storica (anche se ora HB9 standard).
        "VZ"
    };
    return impossiblePrefixes.contains(prefix2);
}

