static bool directedPeerLooksStructurallyGhost(QString const& peerToken)
{
    if (peerToken.trimmed().isEmpty() || isPlaceholderCallToken(peerToken)) {
        return false;
    }
    return !isPlausibleDecodedCallsign(peerToken)
        || hasHighConfidenceGhostPrefix(peerToken);
}

static bool isDirectedDecodePayloadValid(QStringList const& payload,
                                         bool contestExchangeEnabled,
                                         QString* reason)
{
    if (payload.isEmpty()) {
        if (reason) *reason = QStringLiteral("missing directed payload");
        return false;
    }

    if (payload.size() == 1) {
        if (isDirectedDecodeTerminalToken(payload.constFirst())) {
            return true;
        }
        if (reason) *reason = QStringLiteral("unknown directed payload");
        return false;
    }

    if (payload.size() == 2) {
        QString const first = normalizeCallToken(payload.at(0)).toUpper();
        QString const second = normalizeCallToken(payload.at(1)).toUpper();
        if (second == QStringLiteral("TU")
            && (isPlainSignalReportToken(first) || isRogerSignalReportToken(first))) {
            return true;
        }
        if (first == QStringLiteral("R") && isGridTokenStrict(second)) {
            if (contestExchangeEnabled) {
                return true;
            }
            if (reason) *reason = QStringLiteral("contest R+grid payload while contest is disabled");
            return false;
        }
        if (reason) *reason = QStringLiteral("unknown two-token directed payload");
        return false;
    }

    if (!contestExchangeEnabled) {
        for (int i = 0; i + 1 < payload.size(); ++i) {
            QString const current = normalizeCallToken(payload.at(i)).toUpper();
            QString const next = normalizeCallToken(payload.at(i + 1)).toUpper();
            if (current == QStringLiteral("R") && isGridTokenStrict(next)) {
                if (reason) *reason = QStringLiteral("contest R+grid payload while contest is disabled");
                return false;
            }
        }
    }

    return true;
}

static bool isResolvablePlaceholderDirectedPayload(QStringList const& payload,
                                                   bool contestExchangeEnabled)
{
    if (payload.size() == 1) {
        return isDirectedDecodeTerminalToken(payload.constFirst());
    }

    if (payload.size() == 2) {
        QString const first = normalizeCallToken(payload.at(0)).toUpper();
        QString const second = normalizeCallToken(payload.at(1)).toUpper();
        if (second == QStringLiteral("TU")
            && (isPlainSignalReportToken(first) || isRogerSignalReportToken(first))) {
            return true;
        }
        return first == QStringLiteral("R")
            && isGridTokenStrict(second)
            && contestExchangeEnabled;
    }

    return false;
}

static bool shouldCoalesceVisualTxRows(QString const& mode)
{
    QString const upperMode = mode.trimmed().toUpper();
    return upperMode == QStringLiteral("FT8")
        || upperMode == QStringLiteral("FT4")
        || upperMode == QStringLiteral("FT2");
}

static QString canonicalApplicationDecodeMode(QString mode)
{
    QString const upperMode = mode.trimmed().toUpper();
    if (upperMode == QStringLiteral("FT2-LINK")
        || upperMode == QStringLiteral("FT2LINK")
        || upperMode == QStringLiteral("D4LINK")
        || upperMode == QStringLiteral("D4 LINK")) {
        return QStringLiteral("FT2-Link");
    }
    if (upperMode == QStringLiteral("FT8")
        || upperMode == QStringLiteral("FT2")
        || upperMode == QStringLiteral("FT4")
        || upperMode == QStringLiteral("Q65")
        || upperMode == QStringLiteral("MSK144")
        || upperMode == QStringLiteral("JT65")
        || upperMode == QStringLiteral("JT9")
        || upperMode == QStringLiteral("JT4")
        || upperMode == QStringLiteral("FST4")
        || upperMode == QStringLiteral("FST4W")
        || upperMode == QStringLiteral("WSPR")
        || upperMode.startsWith(QStringLiteral("Q65-"))
        || upperMode.startsWith(QStringLiteral("FST4-"))
        || upperMode.startsWith(QStringLiteral("FST4W-"))) {
        return upperMode;
    }
    if (upperMode == QStringLiteral("ECHO")) {
        return QStringLiteral("Echo");
    }
    return {};
}

static bool isFt2LinkApplicationMode(QString mode)
{
    QString const upperMode = mode.trimmed().toUpper();
    return upperMode == QStringLiteral("FT2-LINK")
        || upperMode == QStringLiteral("FT2LINK")
        || upperMode == QStringLiteral("D4LINK")
        || upperMode == QStringLiteral("D4 LINK");
}

static bool isRadioOnlyModeLabel(QString mode)
{
    QString const upperMode = mode.trimmed().toUpper();
    return upperMode == QStringLiteral("DATA")
        || upperMode == QStringLiteral("DATA-U")
        || upperMode == QStringLiteral("DATA-L")
        || upperMode == QStringLiteral("DATA-USB")
        || upperMode == QStringLiteral("DATA-LSB")
        || upperMode == QStringLiteral("USB-D")
        || upperMode == QStringLiteral("DIGU")
        || upperMode == QStringLiteral("DIGL")
        || upperMode == QStringLiteral("PKT")
        || upperMode == QStringLiteral("PKT-U")
        || upperMode == QStringLiteral("PKT-L")
        || upperMode == QStringLiteral("USB")
        || upperMode == QStringLiteral("LSB")
        || upperMode == QStringLiteral("CW")
        || upperMode == QStringLiteral("CW-R")
        || upperMode == QStringLiteral("AM")
        || upperMode == QStringLiteral("FM")
        || upperMode == QStringLiteral("RTTY")
        || upperMode == QStringLiteral("RTTY-U")
        || upperMode == QStringLiteral("RTTY-L");
}

static QString normalizedVisualTxTimeToken(QString const& rawTime, QString const& mode)
{
    QString const normalizedTime = normalizeUtcDisplayToken(rawTime);
    if (!shouldCoalesceVisualTxRows(mode)) {
        return normalizedTime;
    }

    QString const upperMode = mode.trimmed().toUpper();
    int periodMs = 0;
    if (upperMode == QStringLiteral("FT8")) {
        periodMs = 15000;
    } else if (upperMode == QStringLiteral("FT4")) {
        periodMs = 7500;
    } else if (upperMode == QStringLiteral("FT2")) {
        periodMs = 3750;
    }
    if (periodMs <= 0 || periodMs >= 60000) {
        return normalizedTime;
    }

    QDateTime const approxUtc = approxUtcDateTimeForDisplayToken(normalizedTime);
    if (!approxUtc.isValid()) {
        return normalizedTime;
    }

    qint64 const slotIndex = approxUtc.toMSecsSinceEpoch() / static_cast<qint64>(periodMs);
    QString const slotTime = utcDisplayTokenForSlotStart(slotIndex, periodMs);
    if (slotTime == normalizedTime || periodMs % 1000 == 0) {
        return slotTime.isEmpty() ? normalizedTime : slotTime;
    }

    // FT2/FT4 slot boundaries can land at .750/.500 seconds. Their display
    // token is floored to HHMMSS, so reconstructing it as exactly .000 would
    // incorrectly push it into the previous slot. If any point inside the
    // displayed second maps back to the displayed token, keep that token.
    QDateTime const endOfDisplayedSecond = approxUtc.addMSecs(999);
    qint64 const endSlotIndex = endOfDisplayedSecond.toMSecsSinceEpoch() / static_cast<qint64>(periodMs);
    QString const endSlotTime = utcDisplayTokenForSlotStart(endSlotIndex, periodMs);
    if (endSlotTime == normalizedTime) {
        return normalizedTime;
    }

    return slotTime.isEmpty() ? normalizedTime : slotTime;
}

static QString rxPaneVisualTxSlotKey(QVariantMap const& entry, QString const& mode)
{
    if (!shouldCoalesceVisualTxRows(mode) || !entry.value(QStringLiteral("isTx")).toBool()) {
        return {};
    }

    QString const time = normalizedVisualTxTimeToken(entry.value(QStringLiteral("time")).toString(), mode).trimmed();
    if (time.isEmpty()) {
        return {};
    }

    // Only one local TX can be valid in a time-synced slot. Different mirror
    // sources may report different audio frequencies for the same TX event, so
    // frequency must not be part of the visual coalescing key.
    return time;
}

static void coalesceRxPaneTxRows(QVariantList& entries, QString const& mode)
{
    if (!shouldCoalesceVisualTxRows(mode) || entries.isEmpty()) {
        return;
    }

    QHash<QString, int> keptIndexBySlot;
    for (int i = 0; i < entries.size(); ) {
        QVariantMap const entry = entries.at(i).toMap();
        QString const slotKey = rxPaneVisualTxSlotKey(entry, mode);
        if (slotKey.isEmpty()) {
            ++i;
            continue;
        }

        auto const it = keptIndexBySlot.constFind(slotKey);
        if (it == keptIndexBySlot.constEnd()) {
            keptIndexBySlot.insert(slotKey, i);
            ++i;
            continue;
        }

        int const keptIndex = it.value();
        QVariantMap const keptEntry = entries.at(keptIndex).toMap();
        bool const keptLocal = keptEntry.value(QStringLiteral("localTxMirror")).toBool();
        bool const currentLocal = entry.value(QStringLiteral("localTxMirror")).toBool();
        bool const preferCurrent =
            currentLocal && !keptLocal;

        if (preferCurrent) {
            entries[keptIndex] = entry;
        }

        entries.removeAt(i);
    }
}

static QString decodeMirrorEntryKey(QVariantMap const& entry)
{
    QString const time = entry.value(QStringLiteral("isTx")).toBool()
        ? normalizedVisualTxTimeToken(entry.value(QStringLiteral("time")).toString(),
                                      entry.value(QStringLiteral("mode")).toString())
        : entry.value(QStringLiteral("time")).toString();
    QString const message = canonicalDecodeMessage(entry.value(QStringLiteral("message")).toString());
    return time + "|" +
           entry.value("freq").toString() + "|" +
           message + "|" +
           (entry.value("isTx").toBool() ? QStringLiteral("1") : QStringLiteral("0"));
}

static QString decodeMirrorSemanticKey(QVariantMap const& entry)
{
    return entry.value(QStringLiteral("mode")).toString().trimmed().toUpper()
        + QLatin1Char('|')
        + entry.value(QStringLiteral("freq")).toString().trimmed()
        + QLatin1Char('|')
        + canonicalDecodeMessage(entry.value(QStringLiteral("message")).toString())
        + QLatin1Char('|')
        + (entry.value(QStringLiteral("isTx")).toBool()
               ? QStringLiteral("1") : QStringLiteral("0"));
}

static QString decodeRxClearEntryKey(QVariantMap const& entry)
{
    QString key = decodeMirrorEntryKey(entry);
    QString const time = entry.value(QStringLiteral("time")).toString().trimmed();
    if (time.isEmpty()) {
        qulonglong const timestamp =
            entry.value(QStringLiteral("timestamp")).toULongLong();
        if (timestamp > 0) {
            key += QStringLiteral("|ts=") + QString::number(timestamp);
        }
    }
    return key;
}

static QVariantList decodeEntriesNotInPrevious(QVariantList const& entries,
                                                QVariantList const& previousEntries)
{
    QSet<QString> previousKeys;
    previousKeys.reserve(previousEntries.size());
    for (QVariant const& value : previousEntries) {
        QString const key = decodeMirrorEntryKey(value.toMap());
        if (!key.isEmpty()) {
            previousKeys.insert(key);
        }
    }

    QVariantList added;
    added.reserve(qMax(0, entries.size() - previousEntries.size()));
    for (QVariant const& value : entries) {
        QVariantMap const entry = value.toMap();
        QString const key = decodeMirrorEntryKey(entry);
        if (key.isEmpty() || !previousKeys.contains(key)) {
            added.append(entry);
        }
    }
    return added;
}

static QString currentTxVisualTimeToken(QString const& mode)
{
    QString const upperMode = mode.trimmed().toUpper();
    int periodMs = 0;
    if (upperMode == QStringLiteral("FT8")) {
        periodMs = 15000;
    } else if (upperMode == QStringLiteral("FT4")) {
        periodMs = 7500;
    } else if (upperMode == QStringLiteral("FT2")) {
        periodMs = 3750;
    }

    if (periodMs > 0 && periodMs < 60000) {
        qint64 const slotIndex = ntpCorrectedCurrentMSecsSinceEpoch() / static_cast<qint64>(periodMs);
        QString const slotTime = utcDisplayTokenForSlotStart(slotIndex, periodMs);
        if (!slotTime.isEmpty()) {
            return slotTime;
        }
    }

    return QDateTime::currentDateTimeUtc().toString(QStringLiteral("HHmmss"));
}

static QString decodeMirrorLooseKey(QVariantMap const& entry)
{
    return entry.value("db").toString().trimmed() + "|" +
           entry.value("dt").toString().trimmed() + "|" +
           entry.value("freq").toString().trimmed() + "|" +
           canonicalDecodeMessage(entry.value("message").toString()) + "|" +
           (entry.value("isTx").toBool() ? QStringLiteral("1") : QStringLiteral("0"));
}

static QStringList readTextLinesFromOffset(QString const& path, qint64 startOffset, int maxLines)
{
    if (maxLines <= 0 || startOffset < 0) {
        return {};
    }

    QFile file(path);
    if (!file.exists() || !file.open(QIODevice::ReadOnly | QIODevice::Text)) {
        return {};
    }

    qint64 const size = file.size();
    if (startOffset >= size) {
        file.close();
        return {};
    }

    file.seek(startOffset);
    QByteArray data = file.readAll();
    file.close();

    QStringList lines = QString::fromUtf8(data).split(QRegularExpression {R"([\r\n]+)"},
                                                      Qt::SkipEmptyParts);
    if (lines.size() > maxLines) {
        lines = lines.mid(lines.size() - maxLines);
    }
    return lines;
}

static QStringList readTextTailLines(QString const& path, qint64 tailBytes, int maxLines)
{
    if (path.trimmed().isEmpty() || tailBytes <= 0 || maxLines <= 0) {
        return {};
    }

    QFile file(path);
    if (!file.exists() || !file.open(QIODevice::ReadOnly | QIODevice::Text)) {
        return {};
    }

    qint64 const size = file.size();
    qint64 const startOffset = qMax<qint64>(0, size - tailBytes);
    if (!file.seek(startOffset)) {
        return {};
    }
    if (startOffset > 0) {
        file.readLine();
    }

    QByteArray const data = file.readAll();
    QStringList lines = QString::fromUtf8(data).split(QRegularExpression {R"([\r\n]+)"},
                                                      Qt::SkipEmptyParts);
    if (lines.size() > maxLines) {
        lines = lines.mid(lines.size() - maxLines);
    }
    return lines;
}

struct HashResolveAllTxtCandidate
{
    QString timeToken;
    int audioHz {-1};
    QString message;
    QString source;
};

static QString cleanHashResolveMessage(QString message)
{
    QString aptype;
    message = stripDecodeApAnnotation(message.trimmed(), &aptype).simplified();
    static const QRegularExpression trailingDecodeMark {R"(\s+[?*#^]\s*$)"};
    message.remove(trailingDecodeMark);
    return message.trimmed();
}

static bool parseHashResolveAllTxtLine(QString const& rawLine,
                                       HashResolveAllTxtCandidate* candidate)
{
    if (!candidate) {
        return false;
    }

    QString const line = rawLine.trimmed();
    if (line.isEmpty()) {
        return false;
    }

    static const QRegularExpression legacyPattern {
        R"(^\d{6}_(\d{6})\s+\S+\s+(Rx|Tx|Ck)\s+([A-Z0-9_+\-]+)\s+(-?\d+)\s+(-?\d+(?:\.\d+)?)\s+(\d+)\s+(.+)$)",
        QRegularExpression::CaseInsensitiveOption
    };
    QRegularExpressionMatch match = legacyPattern.match(line);
    if (match.hasMatch()) {
        if (match.captured(2).compare(QStringLiteral("Rx"), Qt::CaseInsensitive) != 0
            || match.captured(3).trimmed().toUpper() != QStringLiteral("FT8")) {
            return false;
        }

        bool freqOk = false;
        int const audioHz = match.captured(6).trimmed().toInt(&freqOk);
        QString const message = cleanHashResolveMessage(match.captured(7));
        if (!freqOk || message.isEmpty()) {
            return false;
        }
        candidate->timeToken = normalizeUtcDisplayToken(match.captured(1));
        candidate->audioHz = audioHz;
        candidate->message = message;
        return true;
    }

    static const QRegularExpression jtStylePattern {
        R"(^\d{6,8}_(\d{6})\s+(-?\d+)\s+(-?\d+(?:\.\d+)?)\s+(\d+)\s+\S+\s+(.+)$)",
        QRegularExpression::CaseInsensitiveOption
    };
    match = jtStylePattern.match(line);
    if (!match.hasMatch()) {
        return false;
    }

    bool freqOk = false;
    int const audioHz = match.captured(4).trimmed().toInt(&freqOk);
    QString const message = cleanHashResolveMessage(match.captured(5));
    if (!freqOk || message.isEmpty()) {
        return false;
    }
    candidate->timeToken = normalizeUtcDisplayToken(match.captured(1));
    candidate->audioHz = audioHz;
    candidate->message = message;
    return true;
}

static QStringList hashResolveLogCandidatePaths(QString const& primaryAllTxtPath)
{
    QStringList paths;
    QSet<QString> seen;
    auto addPath = [&](QString const& path) {
        QString const cleaned = path.trimmed();
        if (cleaned.isEmpty()) {
            return;
        }
        QString const absolute = QFileInfo(cleaned).absoluteFilePath();
        if (seen.contains(absolute)) {
            return;
        }
        seen.insert(absolute);
        paths.append(absolute);
    };

    addPath(primaryAllTxtPath);

    QString const appData = QStandardPaths::writableLocation(QStandardPaths::AppDataLocation);
    QString const appLocal = QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation);
    QString const generic = QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation);
    QString const homeSupport = QDir(QDir::homePath()).absoluteFilePath(
        QStringLiteral("Library/Application Support"));

    for (QString const& root : {appData, appLocal}) {
        if (root.isEmpty()) {
            continue;
        }
        QDir const dir(root);
        addPath(dir.absoluteFilePath(QStringLiteral("embedded-ft2/ALL.TXT")));
        addPath(dir.absoluteFilePath(QStringLiteral("ALL.TXT")));
        addPath(dir.absoluteFilePath(QStringLiteral("all.txt")));
    }

    QStringList monthFiles;
    QDate const currentMonth = QDate::currentDate();
    for (int i = 0; i < 2; ++i) {
        monthFiles.append(currentMonth.addMonths(-i).toString(QStringLiteral("yyyyMM"))
                          + QStringLiteral("_ALL.TXT"));
    }
    auto addLogDirectory = [&](QString const& path) {
        QDir const dir(path);
        if (!dir.exists()) {
            return;
        }
        static QStringList const filters {
            QStringLiteral("ALL.TXT"),
            QStringLiteral("all.txt"),
            QStringLiteral("*_ALL.TXT")
        };
        for (QString const& name : dir.entryList(filters, QDir::Files, QDir::Name)) {
            addPath(dir.absoluteFilePath(name));
        }
        for (QString const& monthFile : std::as_const(monthFiles)) {
            addPath(dir.absoluteFilePath(monthFile));
        }
    };
    auto addExternalEntry = [&](QString const& path) {
        QString const cleaned = path.trimmed();
        if (cleaned.isEmpty()) {
            return;
        }
        QFileInfo const info(cleaned);
        if (info.isDir()) {
            QDir const dir(info.absoluteFilePath());
            addLogDirectory(dir.absolutePath());
            addLogDirectory(dir.absoluteFilePath(QStringLiteral("JTDX")));
            addLogDirectory(dir.absoluteFilePath(QStringLiteral("WSJT-X")));
            return;
        }
        addPath(info.absoluteFilePath());
    };

    for (QString const& root : {generic, homeSupport}) {
        if (root.isEmpty()) {
            continue;
        }
        QDir const dir(root);
        for (QString const& monthFile : std::as_const(monthFiles)) {
            addPath(dir.absoluteFilePath(QStringLiteral("JTDX/") + monthFile));
        }
        addPath(dir.absoluteFilePath(QStringLiteral("JTDX/ALL.TXT")));
        addPath(dir.absoluteFilePath(QStringLiteral("WSJT-X/ALL.TXT")));
        addPath(dir.absoluteFilePath(QStringLiteral("Decodium/ALL.TXT")));
        addPath(dir.absoluteFilePath(QStringLiteral("ft2/ALL.TXT")));
        addPath(dir.absoluteFilePath(QStringLiteral("IU8LMC/ft2/ALL.TXT")));
    }
    for (char const* name : {"DECODIUM_HASH_SEED_PATHS", "DECODIUM_EXTERNAL_LOG_DIRS"}) {
        QString const value = qEnvironmentVariable(name).trimmed();
        if (value.isEmpty()) {
            continue;
        }
        for (QString const& entry : value.split(QDir::listSeparator(), Qt::SkipEmptyParts)) {
            addExternalEntry(entry);
        }
    }

    return paths;
}

static QStringList hashResolveMessageTokens(QString const& message)
{
    return canonicalDecodeMessage(message).toUpper().simplified().split(
        QLatin1Char(' '), Qt::SkipEmptyParts);
}

static bool hashResolveMessagesCompatible(QString const& hashedMessage,
                                          QString const& resolvedMessage)
{
    if (!hashedMessage.contains(QStringLiteral("<...>"))
        || resolvedMessage.contains(QStringLiteral("<...>"))) {
        return false;
    }

    QStringList const hashedTokens = hashResolveMessageTokens(hashedMessage);
    QStringList const resolvedTokens = hashResolveMessageTokens(resolvedMessage);
    if (hashedTokens.size() != resolvedTokens.size() || hashedTokens.isEmpty()) {
        return false;
    }

    int placeholderCount = 0;
    for (int i = 0; i < hashedTokens.size(); ++i) {
        QString const hashedToken = hashedTokens.at(i).trimmed().toUpper();
        QString const resolvedToken = resolvedTokens.at(i).trimmed().toUpper();
        if (isPlaceholderCallToken(hashedToken)) {
            ++placeholderCount;
            if (!isPlausibleDecodedCallsign(resolvedToken)) {
                return false;
            }
            continue;
        }
        if (normalizeCallToken(hashedToken).toUpper()
            != normalizeCallToken(resolvedToken).toUpper()) {
            return false;
        }
    }
    return placeholderCount > 0;
}

static QString resolveHashMessageFromCandidates(QString const& timeToken,
                                                int targetAudioHz,
                                                QString const& hashedMessage,
                                                QVector<HashResolveAllTxtCandidate> const& candidates,
                                                QString* sourceOut)
{
    int const targetSeconds = secondsFromUtcDisplayToken(timeToken);
    if (targetSeconds < 0 || targetAudioHz <= 0) {
        return hashedMessage;
    }

    QString resolved;
    QString resolvedSource;
    for (HashResolveAllTxtCandidate const& candidate : candidates) {
        int const candidateSeconds = secondsFromUtcDisplayToken(candidate.timeToken);
        if (candidateSeconds < 0) {
            continue;
        }
        if (qAbs(signedUtcSecondDelta(candidateSeconds, targetSeconds)) > 2) {
            continue;
        }
        if (qAbs(candidate.audioHz - targetAudioHz) > 5) {
            continue;
        }
        if (!hashResolveMessagesCompatible(hashedMessage, candidate.message)) {
            continue;
        }

        QString const candidateMessage = canonicalDecodeMessage(candidate.message);
        if (resolved.isEmpty()) {
            resolved = candidateMessage;
            resolvedSource = candidate.source;
            continue;
        }
        if (resolved.compare(candidateMessage, Qt::CaseInsensitive) != 0) {
            return hashedMessage;
        }
    }

    if (!resolved.isEmpty()) {
        if (sourceOut) {
            *sourceOut = resolvedSource;
        }
        return resolved;
    }
    return hashedMessage;
}

static QString inferPartnerFromDirectedMessage(QString const& message,
                                               QString const& myCall,
                                               QString const& myBase)
{
    QStringList const words = message.simplified().split(QLatin1Char(' '), Qt::SkipEmptyParts);
    if (words.size() < 2) {
        return {};
    }

    QString const first = normalizeCallToken(words.at(0));
    QString const second = normalizeCallToken(words.at(1));
    QString const third = words.size() > 2 ? normalizeCallToken(words.at(2)) : QString {};
    if (first.isEmpty() || second.isEmpty()) {
        return {};
    }

    auto const isMyCall = [&](QString const& token) {
        return token.compare(myCall, Qt::CaseInsensitive) == 0
            || token.compare(myBase, Qt::CaseInsensitive) == 0;
    };
    auto const looksLikePartnerCall = [](QString const& token) {
        QString const upper = token.trimmed().toUpper();
        if (isPlaceholderCallToken(upper)) {
            return false;
        }
        if (upper == QStringLiteral("CQ")
            || upper == QStringLiteral("QRZ")
            || upper == QStringLiteral("DE")
            || upper == QStringLiteral("TU")
            || upper == QStringLiteral("TU;")
            || upper == QStringLiteral("73")
            || upper == QStringLiteral("RR73")
            || upper == QStringLiteral("RRR")) {
            return false;
        }
        QString const base = Radio::base_callsign(upper).trimmed().toUpper();
        return !base.isEmpty() && Radio::is_callsign(base);
    };

    if (isMyCall(first) && looksLikePartnerCall(second)) return second;
    if (isMyCall(second) && looksLikePartnerCall(first)) return first;
    if (first.compare(QStringLiteral("DE"), Qt::CaseInsensitive) == 0
        && isMyCall(second)
        && looksLikePartnerCall(third)) {
        return third;
    }

    return {};
}

