static QString audioFormatToString(const QAudioFormat& fmt)
{
    if (!fmt.isValid()) {
        return QStringLiteral("invalid");
    }
    return QString("rate=%1 ch=%2 fmt=%3 bytes=%4")
        .arg(fmt.sampleRate())
        .arg(fmt.channelCount())
        .arg(sampleFormatName(fmt.sampleFormat()))
        .arg(fmt.bytesPerFrame());
}

static QString audioStateToString(QAudio::State state)
{
    switch (state) {
    case QAudio::ActiveState: return QStringLiteral("ActiveState");
    case QAudio::SuspendedState: return QStringLiteral("SuspendedState");
    case QAudio::StoppedState: return QStringLiteral("StoppedState");
    case QAudio::IdleState: return QStringLiteral("IdleState");
    }
    return QStringLiteral("UnknownState(%1)").arg(static_cast<int>(state));
}

static QString audioErrorToString(QAudio::Error error)
{
    switch (error) {
    case QAudio::NoError: return QStringLiteral("NoError");
    case QAudio::OpenError: return QStringLiteral("OpenError");
    case QAudio::IOError: return QStringLiteral("IOError");
    case QAudio::UnderrunError: return QStringLiteral("UnderrunError");
    case QAudio::FatalError: return QStringLiteral("FatalError");
    }
    return QStringLiteral("UnknownError(%1)").arg(static_cast<int>(error));
}

static QAudioFormat makeAudioFormat(int sampleRate, int channelCount, QAudioFormat::SampleFormat sampleFormat)
{
    channelCount = channelCount <= 1 ? 1 : 2;
    QAudioFormat fmt;
    fmt.setSampleRate(sampleRate);
    fmt.setChannelCount(channelCount);
    if (channelCount == 1) {
        fmt.setChannelConfig(QAudioFormat::ChannelConfigMono);
    } else if (channelCount == 2) {
        fmt.setChannelConfig(QAudioFormat::ChannelConfigStereo);
    }
    fmt.setSampleFormat(sampleFormat);
    return fmt;
}

static bool sameAudioFormat(const QAudioFormat& a, const QAudioFormat& b)
{
    return a.sampleRate() == b.sampleRate()
        && a.channelCount() == b.channelCount()
        && a.sampleFormat() == b.sampleFormat();
}

static int txPcmChannelCountForDeviceFormat(const QAudioFormat& preferred)
{
    return preferred.channelCount() <= 1 ? 1 : 2;
}

static QAudioFormat chooseTxAudioFormat(const QAudioDevice& device)
{
    const QAudioFormat preferred = device.preferredFormat();
    const int requestedChannels = txPcmChannelCountForDeviceFormat(preferred);
    const QAudioFormat requested = makeAudioFormat(48000, requestedChannels, QAudioFormat::Int16);

    bridgeLog("TX audio requested: " + audioFormatToString(requested));
    bridgeLog("TX audio preferred: " + audioFormatToString(preferred) +
              " dev=" + device.description());

    QList<QAudioFormat> candidates;
#if defined(Q_OS_MAC)
    QAudioFormat stereoPreferred48k = makeAudioFormat(48000,
                                                      qMin(2, qMax(1, preferred.channelCount())),
                                                      QAudioFormat::Int16);
    if (preferred.channelCount() > 1)
        candidates.append(stereoPreferred48k);
#elif defined(Q_OS_LINUX)
    if (preferred.channelCount() > 1) {
        candidates.append(makeAudioFormat(48000, 2, QAudioFormat::Int16));
    }
#elif defined(Q_OS_WIN)
    if (preferred.channelCount() > 1) {
        candidates.append(makeAudioFormat(48000, qMin(2, preferred.channelCount()), QAudioFormat::Int16));
    }
#endif

    candidates.append(requested);

    if (preferred.channelCount() > 0) {
        candidates.append(makeAudioFormat(48000, txPcmChannelCountForDeviceFormat(preferred), QAudioFormat::Int16));
    }
    if (preferred.sampleFormat() != QAudioFormat::Unknown) {
        candidates.append(makeAudioFormat(48000, 1, preferred.sampleFormat()));
        if (preferred.channelCount() > 0) {
            candidates.append(makeAudioFormat(48000, txPcmChannelCountForDeviceFormat(preferred), preferred.sampleFormat()));
        }
    }
    if (preferred.sampleRate() > 0) {
        candidates.append(makeAudioFormat(preferred.sampleRate(), 1, QAudioFormat::Int16));
        if (preferred.channelCount() > 0) {
            candidates.append(makeAudioFormat(preferred.sampleRate(), txPcmChannelCountForDeviceFormat(preferred), QAudioFormat::Int16));
        }
        if (preferred.sampleFormat() != QAudioFormat::Unknown) {
            candidates.append(makeAudioFormat(preferred.sampleRate(), 1, preferred.sampleFormat()));
            if (preferred.channelCount() > 0) {
                candidates.append(makeAudioFormat(preferred.sampleRate(), txPcmChannelCountForDeviceFormat(preferred), preferred.sampleFormat()));
            }
        }
    }
    if (preferred.isValid()) {
        candidates.append(makeAudioFormat(preferred.sampleRate(),
                                          txPcmChannelCountForDeviceFormat(preferred),
                                          preferred.sampleFormat()));
    }

    QList<QAudioFormat> uniqueCandidates;
    for (const QAudioFormat& candidate : candidates) {
        if (!candidate.isValid() || candidate.sampleRate() <= 0 || candidate.channelCount() <= 0
            || candidate.sampleFormat() == QAudioFormat::Unknown) {
            continue;
        }
        bool duplicate = false;
        for (const QAudioFormat& existing : uniqueCandidates) {
            if (sameAudioFormat(candidate, existing)) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) uniqueCandidates.append(candidate);
    }

    for (const QAudioFormat& candidate : uniqueCandidates) {
        if (device.isFormatSupported(candidate)) {
            bridgeLog("TX audio chosen: " + audioFormatToString(candidate) +
                      " dev=" + device.description());
            return candidate;
        }
    }

    bridgeLog("TX audio fallback to requested format: " + audioFormatToString(requested) +
              " dev=" + device.description());
    return requested;
}

static qreal txAttenuationFromSlider(double outputLevel)
{
    // Slider 0..450 → attenuazione legacy reale: 0=0dB (massima uscita), 450=45dB
    return qBound<qreal>(0.0, static_cast<qreal>(outputLevel / 10.0), 45.0);
}

static constexpr qreal kTxAudioHeadroomGain = 0.9;

static float rxInputGainFromLevel(double inputLevel)
{
    double const bounded = qBound(0.0, inputLevel, 100.0);
    if (bounded <= 50.0) {
        return static_cast<float>(bounded / 50.0);
    }
    return static_cast<float>(1.0 + ((bounded - 50.0) / 50.0) * 3.0);
}

static double rxInputLevelFromGain(double gain)
{
    double const bounded = qBound(0.0, gain, 4.0);
    if (bounded <= 1.0) {
        return bounded * 50.0;
    }
    return 50.0 + ((bounded - 1.0) / 3.0) * 50.0;
}

static constexpr double kAutoRxInputMaxLevel = 100.0;

static qreal txGainFromSlider(double outputLevel)
{
    return static_cast<qreal>(kTxAudioHeadroomGain
                              * std::pow(10.0, -txAttenuationFromSlider(outputLevel) / 20.0));
}

static int fst4PeriodSecondsForMode(QString const& mode, double fallbackSeconds);
static int fst4SamplesPerSymbolAt48k(QString const& mode, double fallbackSeconds);

static int txSyncLeadInMsForMode(const QString& mode)
{
    QString const normalized = mode.trimmed().toUpper();
    if (normalized == QStringLiteral("FT2LINK")) {
        return 300;
    }
    if (normalized == QStringLiteral("FT8") || normalized == QStringLiteral("FT4")) {
        return 500;
    }
    if (normalized == QStringLiteral("Q65") || normalized.startsWith(QStringLiteral("Q65-"))) {
        return 1000;
    }
    if (normalized == QStringLiteral("JT4")) {
        return 1000;
    }
    if (normalized == QStringLiteral("FST4")
        || normalized == QStringLiteral("FST4W")
        || normalized.startsWith(QStringLiteral("FST4-"))
        || normalized.startsWith(QStringLiteral("FST4W-"))) {
        return fst4PeriodSecondsForMode(normalized, 0.0) == 15 ? 500 : 1000;
    }
    if (normalized == QStringLiteral("FT2")) {
#if defined(Q_OS_LINUX)
        return 0;
#else
        return 300;
#endif
    }
    return 0;
}

static int legacyTxAttenuationFromLevel(double outputLevel)
{
    return qRound(qBound(0.0, outputLevel, 450.0));
}

static double txLevelFromLegacyAttenuation(int attenuation)
{
    return qBound(0.0, static_cast<double>(attenuation), 450.0);
}

static AudioDevice::Channel boundedAudioChannel(int channel)
{
    return static_cast<AudioDevice::Channel>(qBound(0, channel, 3));
}

static bool txChannelCarriesSample(int channelIndex, int channelCount, AudioDevice::Channel requestedChannel)
{
    if (channelCount <= 1) {
        return true;
    }
    switch (requestedChannel) {
    case AudioDevice::Left:
        return channelIndex == 0;
    case AudioDevice::Right:
        return channelIndex == 1;
    case AudioDevice::Mono:
    case AudioDevice::Both:
    default:
        return true;
    }
}

static QByteArray buildTxPcmBuffer(const QVector<float>& wave48kMono, const QAudioFormat& format,
                                   AudioDevice::Channel outputChannel = AudioDevice::Both)
{
    if (wave48kMono.isEmpty() || !format.isValid()) return {};

    const int dstRate = qMax(1, format.sampleRate());
    const int dstChannels = qMax(1, format.channelCount());
    const int bytesPerSample = qMax(0, format.bytesPerSample());
    if (bytesPerSample <= 0 || format.sampleFormat() == QAudioFormat::Unknown) return {};

    const qint64 dstFrames = qMax<qint64>(1, qRound64((double)wave48kMono.size() * dstRate / 48000.0));
    const qint64 totalBytes = dstFrames * dstChannels * bytesPerSample;
    if (totalBytes <= 0 || totalBytes > std::numeric_limits<int>::max()) return {};

    QByteArray pcm(static_cast<int>(totalBytes), Qt::Uninitialized);
    char* out = pcm.data();
    const int srcCount = wave48kMono.size();

    for (qint64 frame = 0; frame < dstFrames; ++frame) {
        const double srcPos = (static_cast<double>(frame) * 48000.0) / dstRate;
        const int src0 = qBound(0, static_cast<int>(std::floor(srcPos)), srcCount - 1);
        const int src1 = qMin(src0 + 1, srcCount - 1);
        const float frac = static_cast<float>(srcPos - src0);
        float sample = wave48kMono[src0];
        if (src1 != src0) sample += (wave48kMono[src1] - wave48kMono[src0]) * frac;
        sample = qBound(-1.0f, sample, 1.0f);

        for (int ch = 0; ch < dstChannels; ++ch) {
            float const outSample = txChannelCarriesSample(ch, dstChannels, outputChannel) ? sample : 0.0f;
            switch (format.sampleFormat()) {
            case QAudioFormat::UInt8: {
                const quint8 v = static_cast<quint8>(qRound((outSample * 0.5f + 0.5f) * 255.0f));
                std::memcpy(out, &v, sizeof(v));
                out += sizeof(v);
                break;
            }
            case QAudioFormat::Int16: {
                const qint16 v = static_cast<qint16>(qRound(outSample * 32767.0f));
                std::memcpy(out, &v, sizeof(v));
                out += sizeof(v);
                break;
            }
            case QAudioFormat::Int32: {
                const qint32 v = static_cast<qint32>(qRound64(outSample * 2147483647.0f));
                std::memcpy(out, &v, sizeof(v));
                out += sizeof(v);
                break;
            }
            case QAudioFormat::Float: {
                const float v = outSample;
                std::memcpy(out, &v, sizeof(v));
                out += sizeof(v);
                break;
            }
            case QAudioFormat::Unknown:
            default:
                return {};
            }
        }
    }

    return pcm;
}

static qsizetype txAudioBufferBytesForMode(const QAudioFormat& format, const QString& mode,
                                           bool tune, bool conservative)
{
    if (!format.isValid()) {
        return 0;
    }
    static_cast<void>(conservative);

    int frames = tune ? 16384 : (mode == QStringLiteral("FT2") ? 8192 : 16384);
#if defined(Q_OS_WIN)
    // Older Windows machines are more likely to underrun the output callback
    // while FT8/FT4 decode/UI work is still settling. Keep FT2 lower to avoid
    // pushing a short 3.75 s payload too far into the slot.
    frames = tune ? 32768 : (mode == QStringLiteral("FT2") ? 12288 : 32768);
    if (conservative && !tune) {
        frames = (mode == QStringLiteral("FT2")) ? 16384 : 65536;
    }
#elif defined(Q_OS_LINUX)
    // PipeWire/PulseAudio can expose USB radios as stereo profiles and may
    // underrun small pull buffers while the UI/decode threads are active.
    frames = tune ? 65536 : (mode == QStringLiteral("FT2") ? 16384 : 32768);
#endif
    return static_cast<qsizetype>(format.bytesForFrames(frames));
}

static int txAudioPrecomputeRetryDelayMs(const QString& mode, bool monitoring)
{
    if (!monitoring) {
        return 0;
    }

    QString const normalized = mode.trimmed().toUpper();
    int periodMs = 0;
    int quietAfterSlotStartMs = 0;
    int quietBeforeSlotEndMs = 0;
    if (normalized == QStringLiteral("FT8")) {
        periodMs = 15000;
        quietAfterSlotStartMs = 8500;
        quietBeforeSlotEndMs = 1200;
    } else if (normalized == QStringLiteral("FT4")) {
        periodMs = 7500;
        quietAfterSlotStartMs = 3500;
        quietBeforeSlotEndMs = 800;
    } else if (normalized == QStringLiteral("FT2")) {
        periodMs = 3750;
        quietAfterSlotStartMs = 900;
        quietBeforeSlotEndMs = 450;
    } else {
        return 0;
    }

    qint64 const nowMs = ntpCorrectedCurrentMSecsSinceEpoch();
    int const msInSlot = static_cast<int>(nowMs % periodMs);
    if (msInSlot < quietAfterSlotStartMs) {
        return qMax(50, quietAfterSlotStartMs - msInSlot);
    }
    int const latestSafeMs = periodMs - quietBeforeSlotEndMs;
    if (msInSlot > latestSafeMs) {
        return qMax(50, periodMs - msInSlot + quietAfterSlotStartMs);
    }
    return 0;
}

static QString expandedLocalFilePath(QString path)
{
    path = QDir::fromNativeSeparators(path.trimmed());
    if (path == QStringLiteral("~")) {
        return QDir::homePath();
    }
    if (path.startsWith(QStringLiteral("~/"))) {
        return QDir::home().absoluteFilePath(path.mid(2));
    }
    return path;
}

static bool ensureParentDirectoryForFile(QString const& filePath, QString* errorMessage = nullptr)
{
    QFileInfo const info(filePath);
    QDir dir = info.dir();
    if (dir.exists() || dir.mkpath(QStringLiteral("."))) {
        return true;
    }
    if (errorMessage) {
        *errorMessage = QStringLiteral("Impossibile creare la cartella: %1")
                            .arg(QDir::toNativeSeparators(dir.absolutePath()));
    }
    return false;
}

static bool isProbablyCall3TxtPayload(QByteArray const& data, QString* errorMessage = nullptr)
{
    if (data.size() < 1024) {
        if (errorMessage) {
            *errorMessage = QStringLiteral("risposta troppo piccola (%1 byte)").arg(data.size());
        }
        return false;
    }

    QByteArray const head = data.left(4096).trimmed().toLower();
    if (head.startsWith("<!doctype") || head.startsWith("<html")
        || head.contains("404 not found") || head.contains("cloudflare")) {
        if (errorMessage) {
            *errorMessage = QStringLiteral("il server ha restituito una pagina HTML/errore invece di CALL3.TXT");
        }
        return false;
    }

    if (!data.contains(',') || !data.contains('\n')) {
        if (errorMessage) {
            *errorMessage = QStringLiteral("formato CALL3.TXT non riconosciuto");
        }
        return false;
    }

    return true;
}

static bool writeMono16WavFile(QString const& path, QVector<float> const& wave, int sampleRate)
{
    if (wave.isEmpty() || sampleRate <= 0) {
        return false;
    }

    QString error;
    if (!ensureParentDirectoryForFile(path, &error)) {
        qWarning() << error;
        return false;
    }

    QFile f(path);
    if (!f.open(QIODevice::WriteOnly)) {
        qWarning() << "Cannot open TX WAV for write:" << path;
        return false;
    }

    QDataStream s(&f);
    s.setByteOrder(QDataStream::LittleEndian);

    quint32 const dataSize = static_cast<quint32>(wave.size() * sizeof(qint16));
    quint32 const fileSize = 36u + dataSize;

    f.write("RIFF", 4);
    s << fileSize;
    f.write("WAVE", 4);
    f.write("fmt ", 4);
    s << quint32(16);
    s << quint16(1);
    s << quint16(1);
    s << quint32(sampleRate);
    s << quint32(sampleRate * sizeof(qint16));
    s << quint16(sizeof(qint16));
    s << quint16(16);
    f.write("data", 4);
    s << dataSize;

    for (float sample : wave) {
        qint16 const v = static_cast<qint16>(qRound(qBound(-1.0f, sample, 1.0f) * 32767.0f));
        s << v;
    }

    return true;
}

static bool writeMono16WavFile(QString const& path, QVector<short> const& samples, int sampleRate)
{
    if (samples.isEmpty() || sampleRate <= 0) {
        return false;
    }

    QString error;
    if (!ensureParentDirectoryForFile(path, &error)) {
        qWarning() << error;
        return false;
    }

    QFile f(path);
    if (!f.open(QIODevice::WriteOnly)) {
        qWarning() << "Cannot open RX WAV for write:" << path;
        return false;
    }

    QDataStream s(&f);
    s.setByteOrder(QDataStream::LittleEndian);

    quint32 const dataSize = static_cast<quint32>(samples.size() * sizeof(qint16));
    quint32 const fileSize = 36u + dataSize;

    f.write("RIFF", 4);
    s << fileSize;
    f.write("WAVE", 4);
    f.write("fmt ", 4);
    s << quint32(16);
    s << quint16(1);
    s << quint16(1);
    s << quint32(sampleRate);
    s << quint32(sampleRate * sizeof(qint16));
    s << quint16(sizeof(qint16));
    s << quint16(16);
    f.write("data", 4);
    s << dataSize;

    for (short sample : samples) {
        s << static_cast<qint16>(sample);
    }

    return true;
}

static QString buildTxRecordingPath(QString const& mode, bool tune)
{
    QString dir = QStandardPaths::writableLocation(QStandardPaths::DocumentsLocation);
    if (dir.isEmpty()) {
        dir = QStandardPaths::writableLocation(QStandardPaths::AppDataLocation);
    }
    dir += QStringLiteral("/Decodium/recordings");
    QString const stamp = QDateTime::currentDateTimeUtc().toString(QStringLiteral("yyyyMMdd_HHmmss_zzz"));
    QString const tag = tune ? QStringLiteral("tune") : QStringLiteral("tx");
    QString const safeMode = mode.trimmed().isEmpty() ? QStringLiteral("FT8") : mode.trimmed().toUpper();
    return QDir(dir).absoluteFilePath(QStringLiteral("decodium_%1_%2_%3.wav").arg(tag, safeMode, stamp));
}

static QString buildWsprDecodeWavPath(quint64 serial, QString const& utcToken)
{
    QString dir = QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation);
    if (dir.isEmpty()) {
        dir = QStandardPaths::writableLocation(QStandardPaths::TempLocation);
    }
    dir += QStringLiteral("/wspr/%1").arg(serial);
    QDateTime slotUtc = approxUtcDateTimeForDisplayToken(utcToken);
    if (!slotUtc.isValid()) {
        slotUtc = QDateTime::currentDateTimeUtc();
    }
    QString const date = slotUtc.toString(QStringLiteral("yyMMdd"));
    QString const time = slotUtc.toString(QStringLiteral("hhmm"));
    return QDir(dir).absoluteFilePath(QStringLiteral("%1_%2.wav").arg(date, time));
}

static QVector<float> buildTuneWaveform(double freq, int sampleRate, int durationSeconds)
{
    int const nFrames = sampleRate * durationSeconds;
    double const twoPi = 2.0 * 3.14159265358979323846;
    double const dphi = twoPi * freq / static_cast<double>(sampleRate);

    QVector<float> wave;
    wave.resize(nFrames);
    double phi = 0.0;
    for (int i = 0; i < nFrames; ++i) {
        wave[i] = static_cast<float>(std::sin(phi));
        phi += dphi;
        if (phi > twoPi) phi -= twoPi;
    }
    return wave;
}

static bool bridgeGeneratedTxWaveMode(QString const& mode)
{
    QString const normalized = mode.trimmed().toUpper();
    return normalized == QStringLiteral("FT8")
        || normalized == QStringLiteral("FT4")
        || normalized == QStringLiteral("FT2")
        || normalized == QStringLiteral("JT65")
        || normalized == QStringLiteral("JT9")
        || normalized == QStringLiteral("MSK144")
        || normalized == QStringLiteral("Q65")
        || normalized.startsWith(QStringLiteral("Q65-"))
        || normalized == QStringLiteral("FST4")
        || normalized == QStringLiteral("FST4W")
        || normalized.startsWith(QStringLiteral("FST4-"))
        || normalized.startsWith(QStringLiteral("FST4W-"))
        || normalized == QStringLiteral("WSPR");
}

static int normalizeWsprPowerDbm(int dbm)
{
    static constexpr int kWsprPowerDbmValues[] = {
        0, 3, 7, 10, 13, 17, 20, 23, 27, 30,
        33, 37, 40, 43, 47, 50, 53, 57, 60
    };

    int best = kWsprPowerDbmValues[0];
    int bestDelta = std::abs(dbm - best);
    for (int value : kWsprPowerDbmValues) {
        int const delta = std::abs(dbm - value);
        if (delta < bestDelta) {
            best = value;
            bestDelta = delta;
        }
    }
    return best;
}

static QString wsprPowerDbmLabel(int dbm)
{
    switch (normalizeWsprPowerDbm(dbm)) {
    case 0:  return QStringLiteral("0 dBm  1 mW");
    case 3:  return QStringLiteral("3 dBm  2 mW");
    case 7:  return QStringLiteral("7 dBm  5 mW");
    case 10: return QStringLiteral("10 dBm  10 mW");
    case 13: return QStringLiteral("13 dBm  20 mW");
    case 17: return QStringLiteral("17 dBm  50 mW");
    case 20: return QStringLiteral("20 dBm  100 mW");
    case 23: return QStringLiteral("23 dBm  200 mW");
    case 27: return QStringLiteral("27 dBm  500 mW");
    case 30: return QStringLiteral("30 dBm  1 W");
    case 33: return QStringLiteral("33 dBm  2 W");
    case 37: return QStringLiteral("37 dBm  5 W");
    case 40: return QStringLiteral("40 dBm  10 W");
    case 43: return QStringLiteral("43 dBm  20 W");
    case 47: return QStringLiteral("47 dBm  50 W");
    case 50: return QStringLiteral("50 dBm  100 W");
    case 53: return QStringLiteral("53 dBm  200 W");
    case 57: return QStringLiteral("57 dBm  500 W");
    case 60: return QStringLiteral("60 dBm  1 kW");
    default: return QStringLiteral("37 dBm  5 W");
    }
}

static double wsprPowerDbmToWatts(int dbm)
{
    return std::pow(10.0, (normalizeWsprPowerDbm(dbm) - 30.0) / 10.0);
}

static QString txWaveMetricsSummary(QVector<float> const& wave)
{
    double peak = 0.0;
    double avgAbs = 0.0;
    qsizetype nonzero = 0;
    for (float const sample : wave) {
        double const value = std::abs(static_cast<double>(sample));
        peak = std::max(peak, value);
        avgAbs += value;
        if (value > 1.0e-7) {
            ++nonzero;
        }
    }
    if (!wave.isEmpty()) {
        avgAbs /= static_cast<double>(wave.size());
    }

    qint64 const durationMs = wave.isEmpty()
        ? 0
        : qRound64(static_cast<double>(wave.size()) * 1000.0 / 48000.0);

    return QStringLiteral("samples=%1 duration_ms=%2 peak=%3 avgAbs=%4 nonzero=%5/%6")
        .arg(wave.size())
        .arg(durationMs)
        .arg(peak, 0, 'f', 6)
        .arg(avgAbs, 0, 'f', 6)
        .arg(nonzero)
        .arg(wave.size());
}

static double txWavePeak(QVector<float> const& wave)
{
    double peak = 0.0;
    for (float const sample : wave) {
        peak = std::max(peak, std::abs(static_cast<double>(sample)));
    }
    return peak;
}

static int q65PeriodSecondsFromModeLabel(QString const& mode)
{
    QString const normalized = mode.trimmed().toUpper();
    if (!normalized.startsWith(QStringLiteral("Q65-"))) {
        return 60;
    }

    int end = 4;
    while (end < normalized.size() && normalized.at(end).isDigit()) {
        ++end;
    }
    bool ok = false;
    int const periodSeconds = normalized.mid(4, end - 4).toInt(&ok);
    if (ok && (periodSeconds == 15 || periodSeconds == 30 || periodSeconds == 60
               || periodSeconds == 120 || periodSeconds == 300)) {
        return periodSeconds;
    }
    return 60;
}

static int q65SamplesPerSymbolAt48k(QString const& mode)
{
    switch (q65PeriodSecondsFromModeLabel(mode)) {
    case 15:  return 4 * 1800;
    case 30:  return 4 * 3600;
    case 120: return 4 * 16000;
    case 300: return 4 * 41472;
    case 60:
    default:  return 4 * 7200;
    }
}

static int fst4PeriodSecondsForMode(QString const& mode, double fallbackSeconds)
{
    QString const normalized = mode.trimmed().toUpper();
    int dashPos = normalized.indexOf(QLatin1Char('-'));
    if (dashPos >= 0) {
        bool ok = false;
        int const parsed = normalized.mid(dashPos + 1).toInt(&ok);
        if (ok && (parsed == 15 || parsed == 30 || parsed == 60
                   || parsed == 120 || parsed == 300 || parsed == 900
                   || parsed == 1800)) {
            return parsed;
        }
    }

    int const fallback = qRound(fallbackSeconds);
    if (fallback == 15 || fallback == 30 || fallback == 60
        || fallback == 120 || fallback == 300 || fallback == 900
        || fallback == 1800) {
        return fallback;
    }

    return normalized.startsWith(QStringLiteral("FST4W")) ? 120 : 60;
}

static int fst4SamplesPerSymbolAt12k(int trPeriodSeconds)
{
    switch (trPeriodSeconds) {
    case 15:   return 720;
    case 30:   return 1680;
    case 60:   return 3888;
    case 120:  return 8200;
    case 300:  return 21504;
    case 900:  return 66560;
    case 1800: return 134400;
    default:   return 3888;
    }
}

static int fst4SamplesPerSymbolAt48k(QString const& mode, double fallbackSeconds)
{
    return 4 * fst4SamplesPerSymbolAt12k(fst4PeriodSecondsForMode(mode, fallbackSeconds));
}

static QVector<float> buildTxWaveformForMessage(QString const& mode,
                                                QString const& msg,
                                                int txFrequency,
                                                double trPeriodSeconds,
                                                QString* errorOut = nullptr)
{
    QVector<float> wave;
    float const freq = static_cast<float>(txFrequency);
    QString const normalizedMode = mode.trimmed().toUpper();

    if (normalizedMode == QStringLiteral("FT2")) {
        auto enc = decodium::txmsg::encodeFt2(msg);
        if (!enc.ok) {
            if (errorOut) *errorOut = QStringLiteral("Codifica FT2 fallita");
            return {};
        }
        wave = decodium::txwave::generateFt2Wave(enc.tones.constData(), 103, 4 * 288, 48000.0f, freq);
    } else if (normalizedMode == QStringLiteral("FT4")) {
        auto enc = decodium::txmsg::encodeFt4(msg);
        if (!enc.ok) {
            if (errorOut) *errorOut = QStringLiteral("Codifica FT4 fallita");
            return {};
        }
        wave = decodium::txwave::generateFt4Wave(enc.tones.constData(), 103, 4 * 576, 48000.0f, freq);
    } else if (normalizedMode == QStringLiteral("FT8") || normalizedMode.isEmpty()) {
        auto enc = decodium::txmsg::encodeFt8(msg);
        if (!enc.ok) {
            if (errorOut) *errorOut = QStringLiteral("Codifica FT8 fallita");
            return {};
        }
        wave = decodium::txwave::generateFt8Wave(enc.tones.constData(), 79, 7680, 2.0f, 48000.0f, freq);
    } else if (normalizedMode == QStringLiteral("JT65")) {
        auto enc = decodium::txmsg::encodeJt65(msg);
        if (!enc.ok || enc.tones.size() < 126) {
            if (errorOut) *errorOut = QStringLiteral("Codifica JT65 fallita");
            return {};
        }
        wave = decodium::txwave::generateJt65Wave(enc.tones.constData(), 126, 48000.0f, freq);
    } else if (normalizedMode == QStringLiteral("JT4")) {
        auto enc = decodium::txmsg::encodeJt4(msg);
        if (!enc.ok || enc.tones.size() < 206) {
            if (errorOut) *errorOut = QStringLiteral("Codifica JT4 fallita");
            return {};
        }
        wave = decodium::txwave::generateJt4Wave(enc.tones.constData(), 206, 48000.0f, freq);
    } else if (normalizedMode == QStringLiteral("JT9")) {
        auto enc = decodium::txmsg::encodeJt9(msg);
        if (!enc.ok || enc.tones.size() < 85) {
            if (errorOut) *errorOut = QStringLiteral("Codifica JT9 fallita");
            return {};
        }
        // JT9-1: 85 symbols, 6912 samples/symbol at 12 kHz. Render at the
        // bridge's 48 kHz audio rate while preserving 1.736111 Hz spacing.
        static constexpr int kJt9Symbols = 85;
        static constexpr int kJt9SamplesPerSymbol = 4 * 6912;
        static constexpr float kJt9ToneSpacing = 12000.0f / 6912.0f;
        wave = decodium::txwave::generateToneWave(enc.tones.constData(),
                                                   kJt9Symbols,
                                                   kJt9SamplesPerSymbol,
                                                   48000.0f,
                                                   kJt9ToneSpacing,
                                                   freq);
    } else if (normalizedMode == QStringLiteral("MSK144")) {
        auto enc = decodium::txmsg::encodeMsk144(msg);
        if (!enc.ok || enc.tones.isEmpty()) {
            if (errorOut) *errorOut = QStringLiteral("Codifica MSK144 fallita");
            return {};
        }
        int symbolCount = 144;
        if (enc.tones.size() > 40 && enc.tones.at(40) < 0) {
            symbolCount = 40;
        }
        if (enc.tones.size() < symbolCount) {
            if (errorOut) *errorOut = QStringLiteral("Sequenza MSK144 incompleta");
            return {};
        }
        wave = decodium::txwave::generateMsk144Wave(enc.tones.constData(), symbolCount,
                                                     48000.0f, freq,
                                                     qBound(5.0, trPeriodSeconds, 60.0));
    } else if (normalizedMode == QStringLiteral("WSPR")) {
        auto enc = decodium::txmsg::encodeWspr(msg);
        if (!enc.ok || enc.tones.size() < 162) {
            if (errorOut) *errorOut = QStringLiteral("Codifica WSPR fallita");
            return {};
        }
        static constexpr int kWsprSymbols = 162;
        static constexpr int kWsprSamplesPerSymbol = 32768; // 8192 samples at 12 kHz, rendered at 48 kHz
        static constexpr float kWsprToneSpacing = 12000.0f / 8192.0f;
        wave = decodium::txwave::generateToneWave(enc.tones.constData(),
                                                  kWsprSymbols,
                                                  kWsprSamplesPerSymbol,
                                                  48000.0f,
                                                  kWsprToneSpacing,
                                                  freq);
    } else if (normalizedMode == QStringLiteral("FST4")
               || normalizedMode == QStringLiteral("FST4W")
               || normalizedMode.startsWith(QStringLiteral("FST4-"))
               || normalizedMode.startsWith(QStringLiteral("FST4W-"))) {
        bool const wsprHint = normalizedMode.startsWith(QStringLiteral("FST4W"));
        auto enc = decodium::txmsg::encodeFst4WithHint(msg, wsprHint, false);
        if (!enc.ok || enc.tones.size() < 160) {
            if (errorOut) *errorOut = wsprHint
                ? QStringLiteral("Codifica FST4W fallita")
                : QStringLiteral("Codifica FST4 fallita");
            return {};
        }
        static constexpr int kFst4Symbols = 160;
        static constexpr int kFst4Hmod = 1;
        int const fst4SamplesPerSymbol = fst4SamplesPerSymbolAt48k(normalizedMode, trPeriodSeconds);
        float const dfreq = static_cast<float>(kFst4Hmod) * 48000.0f
                            / static_cast<float>(fst4SamplesPerSymbol);
        float const f0 = freq + 1.5f * dfreq;
        wave = decodium::txwave::generateFst4Wave(enc.tones.constData(),
                                                  kFst4Symbols,
                                                  fst4SamplesPerSymbol,
                                                  48000.0f,
                                                  kFst4Hmod,
                                                  f0);
    } else if (normalizedMode == QStringLiteral("Q65") || normalizedMode.startsWith(QStringLiteral("Q65-"))) {
        auto enc = decodium::txmsg::encodeQ65(msg);
        if (!enc.ok || enc.tones.size() < 85) {
            if (errorOut) *errorOut = QStringLiteral("Codifica Q65 fallita");
            return {};
        }
        static constexpr int kQ65Symbols = 85;
        int const q65SamplesPerSymbol = q65SamplesPerSymbolAt48k(normalizedMode);
        float const q65ToneSpacing = 48000.0f / static_cast<float>(q65SamplesPerSymbol);
        wave = decodium::txwave::generateToneWave(enc.tones.constData(),
                                                  kQ65Symbols,
                                                  q65SamplesPerSymbol,
                                                  48000.0f,
                                                  q65ToneSpacing,
                                                  freq);
    } else {
        if (errorOut) {
            *errorOut = QStringLiteral("Modo TX non supportato dal bridge audio: %1").arg(normalizedMode);
        }
        return {};
    }

    if (wave.isEmpty() && errorOut) {
        *errorOut = QStringLiteral("Generazione onda TX fallita");
    }
    return wave;
}

// 1.0.364+ — MAM multi-stream nativo (FASE 1). Genera N stream FTx (uno per
// messaggio/frequenza), li somma campione-per-campione e peak-normalizza il
// risultato (stessa logica di normalize_wave/foxcom). Usato solo quando
// multiStreamActive() e' true; abort su qualunque errore di codifica.
// 1.0.365+ — parametrico per modo: FT8/FT4/FT2 condividono questo path
// (encoder + generatore d'onda + nsym/nsps presi da buildTxWaveformForMessage).
// I parametri d'onda DEVONO restare allineati a buildTxWaveformForMessage.
static QVector<float> generateMultiStreamFtxWave(QString const& mode,
                                                 QStringList const& messages,
                                                 QVector<int> const& f0sHz,
                                                 QString* errorOut = nullptr)
{
    if (messages.isEmpty() || messages.size() != f0sHz.size()) {
        if (errorOut) *errorOut = QStringLiteral("MAM multi-stream: input non valido");
        return {};
    }

    // Parametri per modo (identici a buildTxWaveformForMessage). nsym include
    // i simboli di sync; nsps = campioni/simbolo a 48 kHz. acc = nsym*nsps.
    QString const normalizedMode = mode.trimmed().toUpper();
    int nsym = 0;
    int nsps = 0;
    if (normalizedMode == QStringLiteral("FT8") || normalizedMode.isEmpty()) {
        nsym = 79; nsps = 7680;
    } else if (normalizedMode == QStringLiteral("FT4")) {
        nsym = 103; nsps = 4 * 576;
    } else if (normalizedMode == QStringLiteral("FT2")) {
        nsym = 103; nsps = 4 * 288;
    } else {
        if (errorOut) {
            *errorOut = QStringLiteral("MAM multi-stream: modo non supportato %1").arg(normalizedMode);
        }
        return {};
    }

    QVector<float> acc(nsym * nsps, 0.0f);

    for (int i = 0; i < messages.size(); ++i) {
        decodium::txmsg::EncodedMessage enc;
        if (normalizedMode == QStringLiteral("FT4")) {
            enc = decodium::txmsg::encodeFt4(messages.at(i));
        } else if (normalizedMode == QStringLiteral("FT2")) {
            enc = decodium::txmsg::encodeFt2(messages.at(i));
        } else {
            enc = decodium::txmsg::encodeFt8(messages.at(i));
        }
        if (!enc.ok || enc.tones.size() < nsym) {
            if (errorOut) {
                *errorOut = QStringLiteral("MAM multi-stream: codifica %1 fallita per [%2]")
                                .arg(normalizedMode, messages.at(i));
            }
            return {};
        }
        QVector<float> slot;
        float const f0 = static_cast<float>(f0sHz.at(i));
        if (normalizedMode == QStringLiteral("FT4")) {
            slot = decodium::txwave::generateFt4Wave(enc.tones.constData(), nsym, nsps, 48000.0f, f0);
        } else if (normalizedMode == QStringLiteral("FT2")) {
            slot = decodium::txwave::generateFt2Wave(enc.tones.constData(), nsym, nsps, 48000.0f, f0);
        } else {
            slot = decodium::txwave::generateFt8Wave(enc.tones.constData(), nsym, nsps, 2.0f, 48000.0f, f0);
        }
        int const samples = std::min(static_cast<int>(acc.size()),
                                     static_cast<int>(slot.size()));
        for (int k = 0; k < samples; ++k) {
            acc[k] += slot.at(k);
        }
    }

    // Peak-normalize a 0.98 (come normalize_wave foxcom ma con ~2% di headroom):
    // evita i campioni a fondo scala (Int16 32767) dopo la conversione del sink,
    // senza distorsione percepibile su FT8 (envelope costante, -0.17 dB).
    float peak = 0.0f;
    for (float const sample : acc) {
        peak = std::max(peak, std::abs(sample));
    }
    if (peak > 0.0f) {
        float const norm = 0.98f / peak;
        for (float& sample : acc) {
            sample *= norm;
        }
    }

    return acc;
}

static int estimatedSyncPayloadMs(const QString& mode)
{
    QString const normalized = mode.trimmed().toUpper();
    if (normalized == QStringLiteral("FT8"))
        return qRound((79.0 * 4.0 * 1920.0 * 1000.0) / 48000.0);
    if (normalized == QStringLiteral("FT4"))
        return qRound(((103.0 + 2.0) * 4.0 * 576.0 * 1000.0) / 48000.0);
    if (normalized == QStringLiteral("FT2"))
        return qRound(((103.0 + 2.0) * 4.0 * 288.0 * 1000.0) / 48000.0);
    if (normalized == QStringLiteral("WSPR"))
        return qRound((162.0 * 32768.0 * 1000.0) / 48000.0);
    if (normalized == QStringLiteral("FST4")
        || normalized == QStringLiteral("FST4W")
        || normalized.startsWith(QStringLiteral("FST4-"))
        || normalized.startsWith(QStringLiteral("FST4W-"))) {
        return qRound((162.0 * fst4SamplesPerSymbolAt48k(normalized, 0.0) * 1000.0) / 48000.0);
    }
    if (normalized == QStringLiteral("Q65") || normalized.startsWith(QStringLiteral("Q65-")))
        return qRound((85.0 * q65SamplesPerSymbolAt48k(normalized) * 1000.0) / 48000.0);
    return 0;
}

static int syncTxStartBudgetMs(const QString& mode)
{
#if defined(Q_OS_MAC)
    if (mode == QStringLiteral("FT8"))
        return 700;   // 500 ms start delay + small safety margin
    if (mode == QStringLiteral("FT4") || mode == QStringLiteral("FT2"))
        return 500;   // 300 ms start delay + safety margin
    return 400;
#else
    if (mode == QStringLiteral("FT2"))
        return 300;   // ptt1 + sink spin-up safety
    return 350;       // conservative cross-platform margin for sink start/PTT
#endif
}

static int minimumUsefulSyncPayloadMs(const QString& mode)
{
    QString const normalized = mode.trimmed().toUpper();
    if (normalized == QStringLiteral("FT8"))
        return 2500;
    if (normalized == QStringLiteral("FT4"))
        return 1200;
    if (normalized == QStringLiteral("FT2"))
        return 700;
    if (normalized == QStringLiteral("Q65") || normalized.startsWith(QStringLiteral("Q65-")))
        return qMax(5000, estimatedSyncPayloadMs(normalized) - 2000);
    if (normalized == QStringLiteral("FST4")
        || normalized == QStringLiteral("FST4W")
        || normalized.startsWith(QStringLiteral("FST4-"))
        || normalized.startsWith(QStringLiteral("FST4W-"))) {
        return qMax(5000, estimatedSyncPayloadMs(normalized) - 2000);
    }
    return 0;
}

static int ft2AsyncTxStartSafetyMs(bool conservative)
{
    // FIX B (1.0.353): 180ms basta a coprire PTT spin-up + sink start e libera
    // ~76% dello slot per il TX async (tollera il troncamento del payload).
    // 1.0.367 — con ft2ConservativeTiming (default ON) torna a 550ms: finestra
    // utile ~18%, niente frame troncati (comportamento calmo stile Decodium 3.0).
    return conservative ? 550 : 180;
}

static int latestFt2AsyncTxStartMs(int periodMs, bool conservative)
{
    // 1.0.367 — gate SOFT: oltre questo punto del periodo si rinvia il TX al
    // prossimo slot invece di trasmettere ORA.
    //  - conservative (default ON): richiede spazio per il payload FT2 INTERO
    //    (~2520ms) -> finestra ~18%, mai un frame troncato (l'utente preferisce
    //    stabilità: feedback_ft2_stability_over_reactivity).
    //  - non-conservative (FIX B 1.0.353): basta il payload UTILE minimo
    //    (~700ms) -> finestra fino a ~76%, TX più reattivo ma può troncare.
    int const payloadMs = conservative
                              ? estimatedSyncPayloadMs(QStringLiteral("FT2"))
                              : minimumUsefulSyncPayloadMs(QStringLiteral("FT2"));
    if (periodMs <= 0 || payloadMs <= 0) {
        return 0;
    }
    return qMax(0, periodMs - payloadMs - ft2AsyncTxStartSafetyMs(conservative));
}

static int latestD3CompatibleSyncTxStartMs(const QString& mode, int periodMs, bool immediateClickTx = false)
{
    if (periodMs <= 0) {
        return 0;
    }

    // JT4 sync acquisition expects the 206-symbol payload to begin about one
    // second into its 60-second UTC window. Once that lead-in has passed, wait
    // for the next owned slot instead of shifting or trimming the preamble.
    if (mode.trimmed().toUpper() == QStringLiteral("JT4")) {
        return qMin((periodMs * 3) / 4,
                    txSyncLeadInMsForMode(QStringLiteral("JT4")) + 150);
    }

    // Decodium3 accepted starts inside the first 75% of a sync slot, but the
    // bridge audio path trims PCM by elapsed slot time. Near the end of FT4/FT8
    // that can leave only a few milliseconds of payload. Keep the D3 upper cap
    // and also require a minimum useful payload window.
    if (mode == QStringLiteral("FT8")
        || mode == QStringLiteral("FT4")
        || mode == QStringLiteral("FT2")
        || mode == QStringLiteral("MSK144")
        || mode == QStringLiteral("Q65")
        || mode.startsWith(QStringLiteral("Q65-"))
        || mode == QStringLiteral("FST4")
        || mode == QStringLiteral("FST4W")
        || mode.startsWith(QStringLiteral("FST4-"))
        || mode.startsWith(QStringLiteral("FST4W-"))) {
        int const d3CapMs = (periodMs * 3) / 4;
        int const payloadMs = estimatedSyncPayloadMs(mode);
        int const minUsefulPayloadMs = minimumUsefulSyncPayloadMs(mode);
        if (payloadMs <= 0 || minUsefulPayloadMs <= 0) {
            return d3CapMs;
        }
        // FT8/FT4 must keep the Costas start close to the nominal 500 ms slot lead-in.
        // A shifted CQ at +1.4s is decodable only by luck and is visibly out of slot,
        // so defer late starts to the next valid TX period instead of sending now.
        // 1.0.314 — opt-in: con ftxImmediateClickTx ON il cap sale a 2000ms (D3/JTDX
        // accettano shift fino a ~2s; ripristina il "TX immediato al click" stile 1.0.283).
        if (mode == QStringLiteral("FT8")
            || mode == QStringLiteral("FT4")
            || mode == QStringLiteral("MSK144")
            || mode == QStringLiteral("Q65")
            || mode.startsWith(QStringLiteral("Q65-"))
            || mode == QStringLiteral("FST4")
            || mode == QStringLiteral("FST4W")
            || mode.startsWith(QStringLiteral("FST4-"))
            || mode.startsWith(QStringLiteral("FST4W-"))) {
            // 1.0.316 (hotfix Pasquale): 2000ms era troppo stretto — su FT8 (slot 15s)
            // l'utente clicca tipicamente dopo 2-5s e ricadeva nel defer. Ora con
            // immediateClickTx ON la finestra sale a d3CapMs (75% slot) = comportamento
            // 1.0.283 reale. Trade-off: click molto tardi (>50% slot) → TX shiftato e
            // il partner potrebbe non decodificare; il toggle è opt-in e l'utente sceglie.
            // MSK144 fills all but the final 500 ms of its configured T/R
            // period. A late start therefore crosses into the peer's slot even
            // though the repeated frame itself may decode. Never relax this
            // boundary for immediate-click operation.
            int const latestCleanStartMs = immediateClickTx
                && mode != QStringLiteral("MSK144")
                ? d3CapMs
                : (txSyncLeadInMsForMode(mode) + 150);
            return qMax(0, qMin(d3CapMs, latestCleanStartMs));
        }
        int const payloadCapMs =
            txSyncLeadInMsForMode(mode) + qMax(0, payloadMs - minUsefulPayloadMs);
        return qMax(0, qMin(d3CapMs, payloadCapMs));
    }

    int const payloadMs = estimatedSyncPayloadMs(mode);
    if (payloadMs <= 0) {
        return periodMs;
    }
    return qMax(0, periodMs - payloadMs - syncTxStartBudgetMs(mode));
}

static int autoTxDecodeGraceMs(const QString& mode, bool ft8FastSequence = false)
{
    QString const normalized = mode.trimmed().toUpper();
    // Grace = quanto aspettare al boundary il decode dello slot appena finito prima
    // di committare il TX auto. Deve superare (settle 650ms + decode + advanceQsoState)
    // ~0.95-1.0s in FT8, altrimenti la fallback committa CQ con lo stato vecchio e la
    // risposta al partner viene persa (QSO non si chiude).
    // 1.0.317 — opt-in ft8FastSequence: grace FT8 ridotta a 400ms per reattività stile
    // WSJT-X/JTDX. Sotto pressione CPU il qMax(900,...) in effectiveAutoTxDecodeGraceMs
    // sovrascrive automaticamente (sicurezza > reattività su PC carichi).
    if (normalized == QStringLiteral("FT8"))
        return ft8FastSequence ? 400 : 1200;
    if (normalized == QStringLiteral("FT4"))
        return 700;
    if (normalized == QStringLiteral("FT2"))
        return 250;
    return 500;
}

