void DecodiumBridge::setWsprPowerDbm(int v)
{
    int const normalized = normalizeWsprPowerDbm(v);
    if (m_wsprPowerDbm == normalized) {
        return;
    }
    m_wsprPowerDbm = normalized;
    emit wsprPowerDbmChanged();
    QString const mode = m_mode.trimmed().toUpper();
    if (mode == QStringLiteral("WSPR") || mode.startsWith(QStringLiteral("FST4W"))) {
        regenerateTxMessages();
    }
}

QVariantList DecodiumBridge::wsprPowerOptions() const
{
    QVariantList options;
    static constexpr int kWsprPowerDbmValues[] = {
        0, 3, 7, 10, 13, 17, 20, 23, 27, 30,
        33, 37, 40, 43, 47, 50, 53, 57, 60
    };
    for (int value : kWsprPowerDbmValues) {
        options.append(wsprPowerDbmLabel(value));
    }
    return options;
}

// Rigenera TX6 (CQ) sempre da callsign+grid; TX1-5 solo se dxCall è noto.
// Chiamato quando cambiano callsign, grid o dxCall.
// Non sovrascrive messaggi già personalizzati con dati correnti (formato standard).
void DecodiumBridge::regenerateTxMessages()
{
    if (m_callsign.isEmpty()) return;

    // Grid a 4 caratteri (Maidenhead sub-square)
    QString grid4 = m_grid.left(4).toUpper();
    QString const mode = m_mode.trimmed().toUpper();

    if (mode == QStringLiteral("WSPR") || mode.startsWith(QStringLiteral("FST4W"))) {
        QString const my = m_callsign.toUpper();
        int const dbm = normalizeWsprPowerDbm(m_wsprPowerDbm);
        QString const wsprMessage = my + (grid4.isEmpty() ? QString() : " " + grid4)
            + " " + QString::number(dbm);
        setTx6(wsprMessage);
        setTx1(QString());
        setTx2(QString());
        setTx3(QString());
        setTx4(QString());
        setTx5(QString());
        if (m_currentTx >= 1 && m_currentTx <= 5) {
            setCurrentTx(6);
        }
        bridgeLog(QStringLiteral("regenerateTxMessages %1: tx6=%2 power=%3")
                      .arg(mode)
                      .arg(m_tx6)
                      .arg(wsprPowerDbmLabel(dbm)));
        return;
    }

    // TX6 — rebuild callsign/grid while retaining an operator-entered CQ
    // modifier such as "CQ WWA".  The legacy widget path does this through
    // m_CQtype; the QML bridge needs to retain it independently as well.
    // I nominativi speciali non standard (es. II9MESC) in FT8/FT4/FT2 devono
    // usare type-4 senza locator, altrimenti il packing standard li tronca.
    if (m_skipCustomCqPrefixRecovery) {
        m_skipCustomCqPrefixRecovery = false;
    } else if (m_customCqPrefix.isEmpty()) {
        m_customCqPrefix = customCqPrefixFromMessage(m_tx6, m_callsign);
    }
    QString newTx6 = ftxCqMessageWithCustomPrefix(
        standardFtxCqMessage(m_callsign, grid4, mode), m_customCqPrefix);
    setTx6(newTx6);

    // TX1-5: rigenerati solo se dxCall è noto
    if (!m_dxCall.isEmpty()) {
        QString rptSent = m_reportSent.isEmpty() ? "-10" : m_reportSent;

        setTx1(standardFtxQsoMessage(1, m_dxCall, m_callsign, grid4, rptSent,
                                     m_sendRR73, false, mode));                    // DX MY GRID
        setTx2(standardFtxQsoMessage(2, m_dxCall, m_callsign, grid4, rptSent,
                                     m_sendRR73, false, mode));                    // DX MY REPORT
        setTx3(standardFtxQsoMessage(3, m_dxCall, m_callsign, grid4, rptSent,
                                     m_sendRR73, false, mode));                    // DX MY R+SENT_RPT
        setTx4(standardFtxQsoMessage(4, m_dxCall, m_callsign, grid4, rptSent,
                                     m_sendRR73, false, mode));                    // DX MY RR73/RRR
        setTx5(standardFtxQsoMessage(5, m_dxCall, m_callsign, grid4, rptSent,
                                     m_sendRR73, false, mode));                    // DX MY 73
    } else {
        setTx1(QString());
        setTx2(QString());
        setTx3(QString());
        setTx4(QString());
        setTx5(QString());
        if (m_currentTx >= 1 && m_currentTx <= 5 && !m_tx6.trimmed().isEmpty()) {
            setCurrentTx(6);
        }
    }

    bridgeLog("regenerateTxMessages: tx6=" + m_tx6 +
              " tx1=" + m_tx1 + " dxCall=" + m_dxCall);
}
double DecodiumBridge::frequency() const { return m_frequency; }
double DecodiumBridge::displayFrequency() const
{
    if (m_transmitting || m_tuning) {
        double const txDialHz = catSplitTxDialFrequencyHz();
        if (txDialHz > 0.0) {
            return txDialHz;
        }
    }
    return m_frequency;
}

void DecodiumBridge::setFrequency(double v) {
    bool const monitorShouldStayActive = m_monitoring || m_monitorRequested;
    quint64 const monitorSessionId = m_periodTimerSessionId;
    bool frequencyChangedForRecovery = false;
    double oldFreq = m_frequency;
    bool const legacyDialNeedsSync =
        legacyBackendAvailable()
        && (m_legacyBackend->dialFrequency() <= 0.0
            || std::abs(m_legacyBackend->dialFrequency() - v) > 1.0);
    if (!qFuzzyCompare(m_frequency + 1.0, v + 1.0)) {
        m_frequency = v;
        frequencyChangedForRecovery = true;
        emit frequencyChanged();
        // Pulisci le finestre decode quando cambia banda (differenza > 100kHz)
        if (std::abs(v - oldFreq) > 100000.0) {
            clearDecodeWindowsForBandChange(oldFreq, v, QStringLiteral("set-frequency"));
        }
    }
    // A legacy mode switch can retune its own band selector while the bridge
    // already holds the requested dial frequency. Reassert the dial in that
    // case as well, otherwise UI and decoder can silently use different bands.
    if (legacyBackendAvailable()
        && (frequencyChangedForRecovery || legacyDialNeedsSync)) {
        m_legacyBackend->setDialFrequency(v);
    }
    if (m_bandManager) {
        m_bandManager->updateFromFrequency(v);
    }
    if (frequencyChangedForRecovery && std::abs(v - oldFreq) > 50000.0) {
        scheduleMonitorRecovery(QStringLiteral("frequency QSY %1 -> %2 Hz")
                                    .arg(QString::number(oldFreq, 'f', 0),
                                         QString::number(v, 'f', 0)),
                                monitorSessionId,
                                monitorShouldStayActive);
    }
}

QString DecodiumBridge::startupModeForFrequency(double dialFrequency) const
{
    if (dialFrequency <= 0.0 || !m_bandManager) {
        return {};
    }
    return m_bandManager->detectModeForFrequency(dialFrequency);
}

void DecodiumBridge::maybeApplyStartupModeFromRigFrequency(double dialFrequency,
                                                           bool authoritativeRigFrequency)
{
    if (dialFrequency <= 0.0) {
        return;
    }

    qint64 const nowMs = QDateTime::currentMSecsSinceEpoch();
    bool const startupWindowExpired = m_startupModeAutoUntilMs > 0 && nowMs > m_startupModeAutoUntilMs;
    if (startupWindowExpired) {
        m_startupModeAutoPending = false;
        return;
    }

    bool const canApplyStartupMode =
        m_startupModeAutoPending
        || (authoritativeRigFrequency && !m_startupModeAutoAuthoritativeApplied);
    if (!canApplyStartupMode) {
        return;
    }

    QString const startupMode = startupModeForFrequency(dialFrequency);
    if (startupMode.isEmpty()) {
        return;
    }

    m_startupModeAutoPending = false;
    if (authoritativeRigFrequency) {
        m_startupModeAutoAuthoritativeApplied = true;
    }
    if (startupMode == m_mode) {
        return;
    }
    if (authoritativeRigFrequency && (m_transmitting || m_tuning)) {
        bridgeLog(QStringLiteral("CAT auto-mode deferred during TX/tune: %1 Hz -> %2 (current %3)")
                      .arg(QString::number(dialFrequency, 'f', 0), startupMode, m_mode));
        return;
    }

    bridgeLog(QStringLiteral("startup auto-mode%1: %2 Hz -> %3 (was %4)")
                  .arg(authoritativeRigFrequency ? QStringLiteral(" from CAT") : QString(),
                       QString::number(dialFrequency, 'f', 0), startupMode, m_mode));

    bool const previousPreserveFrequency = m_preserveFrequencyOnModeChange;
    m_preserveFrequencyOnModeChange = true;
    setMode(startupMode);
    m_preserveFrequencyOnModeChange = previousPreserveFrequency;
}

bool DecodiumBridge::isTimeSyncDecodeMode(const QString& mode) const
{
    QString const normalized = mode.trimmed().toUpper();
    return normalized == QStringLiteral("FT2")
        || normalized == QStringLiteral("FT4")
        || normalized == QStringLiteral("FT8")
        || normalized == QStringLiteral("JT4")
        || normalized == QStringLiteral("JT65")
        || normalized == QStringLiteral("JT9")
        || normalized == QStringLiteral("Q65")
        || normalized.startsWith(QStringLiteral("Q65-"))
        || normalized == QStringLiteral("FST4")
        || normalized == QStringLiteral("FST4W")
        || normalized.startsWith(QStringLiteral("FST4-"))
        || normalized.startsWith(QStringLiteral("FST4W-"))
        || normalized == QStringLiteral("WSPR");
}

bool DecodiumBridge::ft8LiveDecodeBacklogActive(qint64 nowMs, int minAgeMs,
                                                quint64 ignoreSerial,
                                                QString* detail) const
{
    int pendingFt8 = 0;
    qint64 oldestAgeMs = 0;
    quint64 oldestSerial = 0;
    QString oldestKind;

    for (auto it = m_decodeStartMsBySerial.constBegin(); it != m_decodeStartMsBySerial.constEnd(); ++it) {
        quint64 const serial = it.key();
        if (serial == ignoreSerial) {
            continue;
        }
        if (m_decodeModeBySerial.value(serial).trimmed().toUpper() != QStringLiteral("FT8")) {
            continue;
        }

        ++pendingFt8;
        qint64 const ageMs = qMax<qint64>(0, nowMs - it.value());
        if (ageMs > oldestAgeMs) {
            oldestAgeMs = ageMs;
            oldestSerial = serial;
            if (m_ft8EarlyDecodeSerials.contains(serial)) {
                oldestKind = QStringLiteral("early");
            } else if (m_ft8DeepInTxSerials.contains(serial)) {
                oldestKind = QStringLiteral("list-only");
            } else if (m_ft8PendingDeepFollowups.contains(serial)) {
                oldestKind = QStringLiteral("fast-pending-deep");
            } else if (m_ft8PendingSubpassHarvest.contains(serial)) {
                oldestKind = QStringLiteral("deep-pending-harvest");
            } else {
                oldestKind = QStringLiteral("live");
            }
        }
    }

    bool const tooOld = oldestAgeMs >= minAgeMs;
    bool const tooQueued = pendingFt8 >= 5 && oldestAgeMs >= 4000;
    bool const active = tooOld || tooQueued;
    if (detail) {
        *detail = QStringLiteral("pending=%1 oldestSerial=%2 oldestAgeMs=%3 oldestKind=%4 minAgeMs=%5")
            .arg(pendingFt8)
            .arg(oldestSerial)
            .arg(oldestAgeMs)
            .arg(oldestKind)
            .arg(minAgeMs);
    }
    return active;
}

void DecodiumBridge::drainFt8LiveDecodeBacklog(quint64 keepSerial, const QString& reason)
{
    int removedMeta = 0;
    QList<quint64> const serials = m_decodeStartMsBySerial.keys();
    for (quint64 const serial : serials) {
        if (serial == keepSerial) {
            continue;
        }
        if (m_decodeModeBySerial.value(serial).trimmed().toUpper() != QStringLiteral("FT8")) {
            continue;
        }
        m_decodeStartMsBySerial.remove(serial);
        m_decodeModeBySerial.remove(serial);
        m_decodeUtcTokenBySerial.remove(serial);
        m_decodeSessionBySerial.remove(serial);
        m_ft8EarlyDecodeSerials.remove(serial);
        m_ft8DeepInTxSerials.remove(serial);
        ++removedMeta;
    }

    m_ft8PendingDeepFollowups.clear();
    m_ft8PendingSubpassHarvest.clear();
    m_ft8DeepFollowupCooldownSlots = qMax(m_ft8DeepFollowupCooldownSlots, 6);

    if (m_ft8Worker) {
        m_ft8Worker->cancelCurrentDecode();
        QCoreApplication::removePostedEvents(m_ft8Worker, QEvent::MetaCall);
    }

    qint64 const nowMs = QDateTime::currentMSecsSinceEpoch();
    if (nowMs - m_lastFt8BacklogDrainLogMs >= 2000) {
        m_lastFt8BacklogDrainLogMs = nowMs;
        bridgeLog(QStringLiteral("FT8 live backlog drain: keepSerial=%1 removed=%2 cooldown=%3 %4")
                      .arg(keepSerial)
                      .arg(removedMeta)
                      .arg(m_ft8DeepFollowupCooldownSlots)
                      .arg(reason));
    }
}

bool DecodiumBridge::ft4LiveDecodeBacklogActive(qint64 nowMs, int minAgeMs,
                                                quint64 ignoreSerial,
                                                QString* detail) const
{
    int pendingFt4 = 0;
    qint64 oldestAgeMs = 0;
    quint64 oldestSerial = 0;

    for (auto it = m_decodeStartMsBySerial.constBegin(); it != m_decodeStartMsBySerial.constEnd(); ++it) {
        quint64 const serial = it.key();
        if (serial == ignoreSerial) {
            continue;
        }
        if (m_decodeModeBySerial.value(serial).trimmed().toUpper() != QStringLiteral("FT4")) {
            continue;
        }

        ++pendingFt4;
        qint64 const ageMs = qMax<qint64>(0, nowMs - it.value());
        if (ageMs > oldestAgeMs) {
            oldestAgeMs = ageMs;
            oldestSerial = serial;
        }
    }

    bool const tooOld = oldestAgeMs >= minAgeMs;
    bool const tooQueued = pendingFt4 >= 2 && oldestAgeMs >= 3500;
    bool const active = tooOld || tooQueued;
    if (detail) {
        *detail = QStringLiteral("pending=%1 oldestSerial=%2 oldestAgeMs=%3 minAgeMs=%4")
            .arg(pendingFt4)
            .arg(oldestSerial)
            .arg(oldestAgeMs)
            .arg(minAgeMs);
    }
    return active;
}

void DecodiumBridge::drainFt4LiveDecodeBacklog(quint64 keepSerial, const QString& reason)
{
    qint64 const nowMs = QDateTime::currentMSecsSinceEpoch();
    static constexpr qint64 kFt4PreserveRunningDecodeMaxAgeMs = 9000;
    quint64 preserveRunningSerial = 0;
    qint64 preserveRunningAgeMs = -1;

    for (auto it = m_decodeStartMsBySerial.constBegin(); it != m_decodeStartMsBySerial.constEnd(); ++it) {
        quint64 const serial = it.key();
        if (serial == keepSerial) {
            continue;
        }
        if (m_decodeModeBySerial.value(serial).trimmed().toUpper() != QStringLiteral("FT4")) {
            continue;
        }
        qint64 const ageMs = qMax<qint64>(0, nowMs - it.value());
        if (ageMs <= kFt4PreserveRunningDecodeMaxAgeMs
            && (preserveRunningSerial == 0 || ageMs > preserveRunningAgeMs)) {
            preserveRunningSerial = serial;
            preserveRunningAgeMs = ageMs;
        }
    }

    int removedMeta = 0;
    QList<quint64> const serials = m_decodeStartMsBySerial.keys();
    for (quint64 const serial : serials) {
        if (serial == keepSerial) {
            continue;
        }
        if (serial == preserveRunningSerial) {
            continue;
        }
        if (m_decodeModeBySerial.value(serial).trimmed().toUpper() != QStringLiteral("FT4")) {
            continue;
        }
        m_decodeStartMsBySerial.remove(serial);
        m_decodeModeBySerial.remove(serial);
        m_decodeUtcTokenBySerial.remove(serial);
        m_decodeSessionBySerial.remove(serial);
        ++removedMeta;
    }

    if (m_ft4Worker) {
        QCoreApplication::removePostedEvents(m_ft4Worker, QEvent::MetaCall);
    }

    activateFt4AdaptiveCpuLimit(nowMs, QStringLiteral("backlog drain %1").arg(reason), qint64 {3000});

    if (nowMs - m_lastFt4BacklogDrainLogMs >= 2000) {
        m_lastFt4BacklogDrainLogMs = nowMs;
        bridgeLog(QStringLiteral("FT4 live backlog drain: keepSerial=%1 removed=%2 preserveSerial=%3 preserveAgeMs=%4 %5")
                      .arg(keepSerial)
                      .arg(removedMeta)
                      .arg(preserveRunningSerial)
                      .arg(preserveRunningAgeMs)
                      .arg(reason));
    }
}

void DecodiumBridge::resetEarlyDecodeSchedule()
{
    m_ft8EarlyDecodeSlot = -1;
    m_ft8EarlyDecode41Sent = false;
    m_ft8EarlyDecode47Sent = false;
    m_ft8PendingDeepFollowups.clear();
    m_ft8DeepFollowupCooldownSlots = 0;  // P0 (1.0.403): re-abilita il deep su nuova sessione RX
    m_ft4EarlyDecodeSlot = -1;
    m_ft4EarlyDecodeSent = false;

    if (m_ft8Worker) {
        auto *worker = m_ft8Worker;
        QMetaObject::invokeMethod(worker, [worker]() {
            worker->resetDecoderState();
        }, Qt::QueuedConnection);
    }
}

void DecodiumBridge::resetFtxDecodeWorkersForModeChange(const QString& previousMode,
                                                        const QString& nextMode)
{
    if (!isFtx77MessageMode(previousMode) && !isFtx77MessageMode(nextMode)) {
        return;
    }

    bridgeLog(QStringLiteral("mode-change FTx worker reset: %1 -> %2").arg(previousMode, nextMode));

    m_asyncDecodePending = false;
    m_ft8EarlyDecodeSerials.clear();
    m_ft8DeepInTxSerials.clear();
    m_ft8PendingDeepFollowups.clear();
    m_ft8PendingSubpassHarvest.clear();
    m_ft8DeepFollowupCooldownSlots = 0;  // P0 (1.0.403): re-abilita il deep su cambio modo
    m_decodeStartMsBySerial.clear();
    m_decodeModeBySerial.clear();
    m_decodeUtcTokenBySerial.clear();
    m_decodeSessionBySerial.clear();
    if (m_decoding) {
        m_decoding = false;
        emit decodingChanged();
    }

    auto removeQueuedDecodeCalls = [](QObject* worker) {
        if (worker) {
            QCoreApplication::removePostedEvents(worker, QEvent::MetaCall);
        }
    };

    removeQueuedDecodeCalls(m_ft8Worker);
    removeQueuedDecodeCalls(m_ft2Worker);
    removeQueuedDecodeCalls(m_ft4Worker);

    quint64 const staleDecodeSerial = std::numeric_limits<quint64>::max();
    if (m_ft8Worker) {
        m_ft8Worker->markLatestDecodeSerial(staleDecodeSerial);
        m_ft8Worker->cancelCurrentDecode();
        auto* worker = m_ft8Worker;
        QMetaObject::invokeMethod(worker, [worker]() {
            worker->resetDecoderState();
        }, Qt::QueuedConnection);
    }
    if (m_ft2Worker) {
        m_ft2Worker->markLatestDecodeSerial(staleDecodeSerial);
        m_ft2Worker->cancelCurrentDecode();
    }
    if (m_ft4Worker) {
        m_ft4Worker->markLatestDecodeSerial(staleDecodeSerial);
    }
}

void DecodiumBridge::resetRxPeriodAccumulation(bool reserveAudioBuffer)
{
    m_periodTicks = 0;
    m_lastPeriodSlot = -1;
    m_periodProgress = 0;
    emit periodProgressChanged();
    resetEarlyDecodeSchedule();
    m_pendingTimeSyncDecodeAudio.clear();
    m_pendingTimeSyncDecodeSlot = -1;
    m_pendingTimeSyncDecodeMode.clear();
    m_pendingTimeSyncDecodeActive = false;
    m_forcedDecodeAudioSnapshot.clear();
    m_forcedDecodeAudioSnapshotActive = false;

    QMutexLocker locker(&m_audioBufferMutex);
    m_audioBuffer.clear();
    if (reserveAudioBuffer) {
        m_audioBuffer.reserve(m_periodTicksMax * TIMER_MS * SAMPLE_RATE / 1000);
    }
}

void DecodiumBridge::requestRigFrequencyFromBridge(double hz, const QString& reason)
{
    if (hz <= 0.0) {
        return;
    }

    qint64 const nowMs = QDateTime::currentMSecsSinceEpoch();
    m_localCatFrequencyPreviousHz = m_frequency;
    m_localCatFrequencyTargetHz = hz;
    m_localCatFrequencyGuardUntilMs = nowMs + 8000;
    m_localCatFrequencyGuardMaxMs = nowMs + 20000;  // 1.0.362 tetto re-arm guard
    setFrequency(hz);

    if (!m_catConnected) {
        bridgeLog(QStringLiteral("Local QSY requested by %1: %2 Hz (CAT not connected, bridge state only)")
                      .arg(reason, QString::number(hz, 'f', 0)));
        return;
    }

    // 1.0.192 — applica Frequency Calibration prima di scrivere al rig.
    // Compensa drift conoscuto: hz_corrected = hz + slope_ppm*hz*1e-6 + intercept_Hz.
    double const dialHz = applyFrequencyCalibration(hz);
    if (isHamlibFamilyBackend(m_catBackend)) {
        activeCatSetFreq(m_nativeCat, m_hamlibCat, m_catBackend, dialHz, m_omniRigCat, m_legacyBackend);
        schedulePostQsyCatSettledSync(hz, reason);
        bridgeLog(QStringLiteral("CAT local QSY requested by %1: %2 Hz via %3 (mode/split sync delayed)")
                      .arg(reason,
                           QString::number(hz, 'f', 0),
                           m_catBackend));
        return;
    }

    applyConfiguredCatRigMode(reason + QStringLiteral("/mode"));
    activeCatSetFreq(m_nativeCat, m_hamlibCat, m_catBackend, dialHz, m_omniRigCat, m_legacyBackend);
    syncActiveCatTxSplitFrequency(reason + QStringLiteral("/dial"));
    bridgeLog(QStringLiteral("CAT local QSY requested by %1: %2 Hz via %3")
                  .arg(reason,
                       QString::number(hz, 'f', 0),
                       m_catBackend));
}

void DecodiumBridge::schedulePostQsyCatSettledSync(double hz, const QString& reason, int delayMs)
{
    if (hz <= 0.0
        || !isHamlibFamilyBackend(m_catBackend)
        || !m_hamlibCat
        || !m_hamlibCat->connected()) {
        return;
    }

    qint64 const nowMs = QDateTime::currentMSecsSinceEpoch();
    m_catFrequencySettleUntilMs = std::max(m_catFrequencySettleUntilMs,
                                           nowMs + qMax(250, delayMs));
    quint64 const serial = ++m_catQsySettleSerial;
    QTimer::singleShot(qMax(250, delayMs), this, [this, hz, reason, serial]() {
        if (serial != m_catQsySettleSerial) {
            return;
        }
        if (!isHamlibFamilyBackend(m_catBackend)
            || !m_hamlibCat
            || !m_hamlibCat->connected()) {
            return;
        }
        if (m_localCatFrequencyTargetHz > 0.0
            && std::abs(m_localCatFrequencyTargetHz - hz) > 1.0) {
            return;
        }

        m_catFrequencySettleUntilMs = 0;
        QString const settledReason = reason + QStringLiteral("/settled");
        bridgeLog(QStringLiteral("CAT post-QSY settled sync (%1): %2 Hz")
                      .arg(settledReason, QString::number(hz, 'f', 0)));
        applyConfiguredCatRigMode(settledReason);
        syncActiveCatTxSplitFrequency(settledReason);
    });
}

bool DecodiumBridge::hamlibCatFrequencySettleActive(const QString& reason) const
{
    if (!isHamlibFamilyBackend(m_catBackend)
        || reason.contains(QStringLiteral("settled"), Qt::CaseInsensitive)) {
        return false;
    }
    return m_catFrequencySettleUntilMs > QDateTime::currentMSecsSinceEpoch();
}

bool DecodiumBridge::catSplitOperationActiveForMode() const
{
    if (!isHamlibFamilyBackend(m_catBackend)
        && m_catBackend != QStringLiteral("cat4om")) {
        return false;
    }

    QObject const* activeCat = catManagerObj();
    if (!activeCat) return false;
    QString const splitMode = normalizedCatSplitMode(activeCat->property("splitMode").toString());
    if (splitMode != QStringLiteral("rig") && splitMode != QStringLiteral("emulate")) {
        return false;
    }

    QString mode = canonicalApplicationDecodeMode(m_mode).trimmed().toUpper();
    if (mode.isEmpty()) {
        QString const rawMode = m_mode.trimmed().toUpper();
        if (rawMode.contains(QStringLiteral("FT8"))) {
            mode = QStringLiteral("FT8");
        } else if (rawMode.contains(QStringLiteral("FT4"))) {
            mode = QStringLiteral("FT4");
        } else if (rawMode.contains(QStringLiteral("FT2"))) {
            mode = QStringLiteral("FT2");
        } else if (rawMode.startsWith(QStringLiteral("FST4"))) {
            mode = rawMode;
        }
    }
    bool const wsjtSplitMode =
        mode == QStringLiteral("FT8")
        || mode == QStringLiteral("FT4")
        || mode == QStringLiteral("FT2")
        || mode == QStringLiteral("FST4")
        || mode.startsWith(QStringLiteral("FST4-"));

    return !m_vhfUhfFeatures || wsjtSplitMode;
}

int DecodiumBridge::catSplitXitHzForTxFrequency(int txFrequencyHz) const
{
    if (!catSplitOperationActiveForMode() || txFrequencyHz <= 0) {
        return 0;
    }

    return (txFrequencyHz / 500) * 500 - 1500;
}

int DecodiumBridge::effectiveTxAudioFrequencyHz() const
{
    int const xitHz = catSplitXitHzForTxFrequency(m_txFrequency);
    return qBound(0, m_txFrequency - xitHz, 5000);
}

double DecodiumBridge::catSplitTxDialFrequencyHz() const
{
    if (!catSplitOperationActiveForMode() || m_txFrequency <= 0) {
        return 0.0;
    }

    double dialHz = 0.0;
    qint64 const nowMs = QDateTime::currentMSecsSinceEpoch();
    bool const localQsyGuardActive =
        m_localCatFrequencyTargetHz > 0.0
        && m_localCatFrequencyGuardUntilMs > 0
        && nowMs <= m_localCatFrequencyGuardUntilMs;
    if (localQsyGuardActive) {
        dialHz = m_frequency;
    }
    if (dialHz <= 0.0 && isHamlibFamilyBackend(m_catBackend) && m_hamlibCat) {
        dialHz = m_hamlibCat->frequency();
    }
    if (dialHz <= 0.0 && m_catBackend == QStringLiteral("cat4om") && m_cat4OmCat) {
        dialHz = m_cat4OmCat->frequency();
    }
    if (dialHz <= 0.0) {
        dialHz = m_frequency;
    }
    if (dialHz <= 0.0) {
        return 0.0;
    }

    return dialHz + static_cast<double>(catSplitXitHzForTxFrequency(m_txFrequency));
}

void DecodiumBridge::syncActiveCatTxSplitFrequency(const QString& reason)
{
    QObject* const activeCat = catManagerObj();
    if (legacyOwnsRigControl(m_legacyBackend)
        || useLegacyRigControlFallback(m_legacyBackend, m_catBackend)
        || (!isHamlibFamilyBackend(m_catBackend)
            && m_catBackend != QStringLiteral("cat4om"))
        || !activeCat
        || !activeCat->property("connected").toBool()) {
        return;
    }

    if (hamlibCatFrequencySettleActive(reason)) {
        bridgeLog(QStringLiteral("CAT split sync delayed during QSY settle (%1)").arg(reason));
        return;
    }

    QString const splitMode = normalizedCatSplitMode(activeCat->property("splitMode").toString());
    if (splitMode == QStringLiteral("none")) {
        return;
    }

    double const txDialHz = catSplitTxDialFrequencyHz();
    if (txDialHz <= 0.0
        && !activeCat->property("split").toBool()
        && activeCat->property("txFrequency").toDouble() <= 1.0) {
        return;
    }

    // txDialHz <= 0 is the split-disable / no-valid-TX-dial sentinel. Preserve it:
    // calibration intercepts must never turn that sentinel into a positive TX VFO.
    double const txDialCalibrated = txDialHz > 0.0
        ? applyFrequencyCalibration(txDialHz)
        : 0.0;
    activeCatSetTxFreq(m_nativeCat, m_hamlibCat, m_catBackend, txDialCalibrated, m_omniRigCat);

    if (txDialHz > 0.0) {
        bridgeLog(QStringLiteral("CAT split sync (%1): mode=%2 dial=%3 tx_ui=%4 xit=%5 tx_dial=%6 tx_audio=%7 via %8")
                      .arg(reason,
                           splitMode,
                           QString::number(m_frequency, 'f', 0),
                           QString::number(m_txFrequency),
                           QString::number(catSplitXitHzForTxFrequency(m_txFrequency)),
                           QString::number(txDialHz, 'f', 0),
                           QString::number(effectiveTxAudioFrequencyHz()),
                           m_catBackend));
    } else {
        bridgeLog(QStringLiteral("CAT split sync (%1): split off mode=%2 tx_ui=%3 via %4")
                      .arg(reason,
                           splitMode.isEmpty() ? QStringLiteral("none") : splitMode,
                           QString::number(m_txFrequency),
                           m_catBackend));
    }
}

void DecodiumBridge::syncCatSplitModeToLegacy(const QString& mode, const QString& reason)
{
    QString const normalized = normalizedCatSplitMode(mode);
    QVariant const legacyValue = legacySplitModeSettingValue(normalized);

    QSettings settings(QSettings::IniFormat, QSettings::UserScope, QStringLiteral("Decodium"), QStringLiteral("Decodium3"));
    decodium::beginActiveSettingsProfile(settings);
    settings.beginGroup(QStringLiteral("Transceiver"));
    settings.setValue(QStringLiteral("splitMode"), normalized);
    settings.endGroup();
    settings.setValue(QStringLiteral("SplitMode"), legacyValue);
    settings.sync();
    syncSettingToLegacyIni(QStringLiteral("SplitMode"), legacyValue);

    if (legacyBackendAvailable()) {
        m_legacyBackend->setSplitMode(normalized);
    }

    bridgeLog(QStringLiteral("CAT split mode synced to legacy (%1): %2")
                  .arg(reason, normalized));
}

bool DecodiumBridge::shouldIgnoreCatFrequencyDuringLocalQsy(double hz, const QString& backend)
{
    if (hz <= 0.0 || m_localCatFrequencyTargetHz <= 0.0) {
        return false;
    }

    qint64 const nowMs = QDateTime::currentMSecsSinceEpoch();
    if (m_localCatFrequencyGuardUntilMs <= 0 || nowMs > m_localCatFrequencyGuardUntilMs) {
        return false;
    }

    if (std::abs(hz - m_localCatFrequencyTargetHz) <= 1.0) {
        m_localCatFrequencyGuardUntilMs = 0;
        m_localCatFrequencyGuardMaxMs = 0;
        m_localCatFrequencyTargetHz = 0.0;
        m_localCatFrequencyPreviousHz = 0.0;
        return false;
    }

    bool const looksLikePreviousDial =
        m_localCatFrequencyPreviousHz > 0.0
        && std::abs(hz - m_localCatFrequencyPreviousHz) <= 25.0;
    bool const looksLikeManualDialChange =
        !looksLikePreviousDial
        && std::abs(hz - m_localCatFrequencyTargetHz) > 100.0;
    if (looksLikeManualDialChange) {
        bridgeLog(QStringLiteral("CAT[%1] manual rig frequency accepted during local QSY guard: rig=%2 target=%3 previous=%4")
                      .arg(backend,
                           QString::number(hz, 'f', 0),
                           QString::number(m_localCatFrequencyTargetHz, 'f', 0),
                           QString::number(m_localCatFrequencyPreviousHz, 'f', 0)));
        m_localCatFrequencyGuardUntilMs = 0;
        m_localCatFrequencyGuardMaxMs = 0;
        m_localCatFrequencyTargetHz = 0.0;
        m_localCatFrequencyPreviousHz = 0.0;
        return false;
    }

    if (nowMs - m_lastIgnoredCatFrequencyLogMs >= 500) {
        bridgeLog(QStringLiteral("CAT[%1] stale frequency ignored after local QSY: rig=%2 target=%3 previous=%4 guard_ms=%5")
                      .arg(backend,
                           QString::number(hz, 'f', 0),
                           QString::number(m_localCatFrequencyTargetHz, 'f', 0),
                           QString::number(m_localCatFrequencyPreviousHz, 'f', 0),
                           QString::number(m_localCatFrequencyGuardUntilMs - nowMs)));
        m_lastIgnoredCatFrequencyLogMs = nowMs;
    }
    // 1.0.362 — ri-arma il guard finche' il rig continua a riportare una freq != target
    // (FT-991 lento): senza questo, dopo gli 8s iniziali una poll stale FT8 passava e la
    // freq tornava a FT8 in FT2. Bounded da m_localCatFrequencyGuardMaxMs (~20s totali).
    if (m_localCatFrequencyGuardMaxMs > 0 && nowMs < m_localCatFrequencyGuardMaxMs) {
        m_localCatFrequencyGuardUntilMs = std::min<qint64>(nowMs + 3000, m_localCatFrequencyGuardMaxMs);
    }
    return true;
}

void DecodiumBridge::applyRemoteDialFrequency(double hz, const QString& reason)
{
    if (hz <= 0.0) {
        return;
    }

    requestRigFrequencyFromBridge(hz, reason);
    if (m_monitoring) {
        resetRxPeriodAccumulation(true);
    }
}

bool DecodiumBridge::shouldIgnoreLegacyAudioFrequencyDuringLocalQsy(int hz, bool tx)
{
    int const targetHz = tx ? m_localTxFrequencyTargetHz : m_localRxFrequencyTargetHz;
    qint64& guardUntilMs = tx ? m_localTxFrequencyGuardUntilMs : m_localRxFrequencyGuardUntilMs;
    int& targetRef = tx ? m_localTxFrequencyTargetHz : m_localRxFrequencyTargetHz;

    if (targetHz < 0 || guardUntilMs <= 0) {
        return false;
    }

    qint64 const nowMs = QDateTime::currentMSecsSinceEpoch();
    if (nowMs > guardUntilMs) {
        guardUntilMs = 0;
        targetRef = 0;
        return false;
    }

    if (hz == targetHz) {
        guardUntilMs = 0;
        targetRef = 0;
        return false;
    }

    return true;
}

void DecodiumBridge::applyRemoteBandChange(const QString& band)
{
    if (!m_bandManager) {
        return;
    }

    QString normalized = band.trimmed().toUpper();
    if (normalized.isEmpty()) {
        return;
    }

    QString const beforeBand = m_bandManager->currentBandLambda();
    double const beforeFrequency = m_frequency;
    // 1.0.374: il cambio banda deve risolvere la freq col modo applicativo corrente
    // (changeBandByLambda usa m_currentMode, va tenuto allineato a m_mode).
    m_bandManager->setCurrentMode(m_mode);
    m_bandManager->changeBandByLambda(normalized);
    QString const afterBand = m_bandManager->currentBandLambda();
    if (afterBand.compare(beforeBand, Qt::CaseInsensitive) == 0
        && normalized.compare(beforeBand, Qt::CaseInsensitive) != 0
        && qFuzzyCompare(beforeFrequency + 1.0, m_frequency + 1.0)) {
        bridgeLog(QStringLiteral("Remote band change ignored: unknown band %1").arg(normalized));
        return;
    }

    double const targetFrequency = m_bandManager->dialFrequency();
    if (targetFrequency > 0.0
        && (!qFuzzyCompare(m_frequency + 1.0, targetFrequency + 1.0)
            || std::abs(m_localCatFrequencyTargetHz - targetFrequency) > 1.0)) {
        setFrequency(targetFrequency);
        requestRigFrequencyFromBridge(targetFrequency, QStringLiteral("remote-band"));
    }
    bridgeLog(QStringLiteral("Remote band change applied: %1 -> %2 Hz")
                  .arg(afterBand, QString::number(m_frequency, 'f', 0)));
}

void DecodiumBridge::armPeriodTimerForCurrentMode(quint64 sessionId, const QString& reason)
{
    if (!m_periodTimer) {
        return;
    }

    m_periodTimer->stop();

    QString const modeSnapshot = m_mode;
    int const periodMs = effectivePeriodMsForMode(modeSnapshot);
    qint64 const msNow = correctedUtcMsecsSinceStartOfDay();
    int const msInPeriod = (periodMs > 0) ? static_cast<int>(msNow % static_cast<qint64>(periodMs)) : 0;
    int msToNext = (periodMs > 0) ? (periodMs - msInPeriod) : TIMER_MS;
    if (msToNext < TIMER_MS) {
        msToNext += periodMs;
    }

    bridgeLog(reason + ": UTC sync wait=" + QString::number(msToNext) +
              "ms (period=" + QString::number(periodMs) +
              "ms mode=" + modeSnapshot +
              " ntp=" + QString::number((m_ntpEnabled && m_ntpSynced) ? m_ntpOffsetMs : 0.0, 'f', 1) +
              " session=" + QString::number(sessionId) + ")");

    if (modeSnapshot == QStringLiteral("WSPR")
        || bridgeOwnsLegacyJtRxWhenCatSuppressed(modeSnapshot)
        || bridgeOwnsFst4Audio(modeSnapshot)) {
        resetRxPeriodAccumulation(true);
        m_periodTicks = 0;
        m_lastPeriodSlot = -1;
        m_bridgeOwnedJtFallbackLastSlot = -1;
        m_bridgeOwnedJtFallbackLastDispatchMs = 0;
        m_bridgeOwnedJtFallbackLastMode.clear();
        m_periodTimer->start();
        bridgeLog(QStringLiteral("%1: %2 period timer started immediately; next UTC boundary in %3ms (session=%4)")
                      .arg(reason)
                      .arg(modeSnapshot)
                      .arg(msToNext)
                      .arg(sessionId));
        return;
    }

    QTimer::singleShot(msToNext, this, [this, sessionId, modeSnapshot]() {
        if (!m_monitoring) {
            return;
        }
        if (sessionId != m_periodTimerSessionId || m_mode != modeSnapshot) {
            bridgeLog("period timer start skipped: stale session/mode (wanted mode=" +
                      modeSnapshot + " session=" + QString::number(sessionId) +
                      ", current mode=" + m_mode +
                      " session=" + QString::number(m_periodTimerSessionId) + ")");
            return;
        }

        resetRxPeriodAccumulation(true);
        m_periodTimer->start();
        bridgeLog("period timer started at UTC boundary (mode=" + modeSnapshot +
                  " session=" + QString::number(sessionId) + ")");
    });
}

void DecodiumBridge::maybeDispatchBridgeOwnedJtDecodeFallback()
{
    QString const modeSnapshot = m_mode.trimmed().toUpper();
    bool const bridgeOwnedTimeSyncRx =
        bridgeOwnsLegacyJtRxWhenCatSuppressed(modeSnapshot)
        || bridgeOwnsFst4Audio(modeSnapshot);
    if (!bridgeOwnedTimeSyncRx) {
        return;
    }
    if (!m_monitoring || m_rxAudioSuspendedForTx || m_transmitting || m_tuning) {
        return;
    }
    if (m_pendingTimeSyncDecodeActive) {
        return;
    }

    int const periodMs = effectivePeriodMsForMode(modeSnapshot);
    int const targetSamples = targetDecodeSamplesForMode(modeSnapshot);
    int const minimumSamples = minimumDecodeSamplesForMode(modeSnapshot);
    if (periodMs <= 0 || targetSamples <= 0 || minimumSamples <= 0) {
        return;
    }

    qint64 const nowMs = correctedUtcEpochMs();
    qint64 const currentSlot = nowMs / periodMs;
    if (currentSlot <= 0) {
        return;
    }
    int const msInSlot = static_cast<int>(nowMs % static_cast<qint64>(periodMs));

    // Let the post-boundary audio callback settle, then decode the just-ended
    // bridge-owned long slot once. This is a defensive path for lab/no-CAT
    // macOS runs where the main period timer can be stale while audio capture
    // is healthy.
    if (msInSlot < 1500 || msInSlot > qMin(periodMs - 1000, 9000)) {
        return;
    }

    qint64 const completedSlot = currentSlot - 1;
    if (m_bridgeOwnedJtFallbackLastMode == modeSnapshot
        && m_bridgeOwnedJtFallbackLastSlot == completedSlot) {
        return;
    }
    if (nowMs - m_bridgeOwnedJtFallbackLastDispatchMs < qMax<qint64>(1500, periodMs / 4)) {
        return;
    }

    int bufferedSamples = 0;
    {
        QMutexLocker locker(&m_audioBufferMutex);
        bufferedSamples = m_audioBuffer.size();
    }
    if (bufferedSamples < minimumSamples) {
        return;
    }

    m_bridgeOwnedJtFallbackLastMode = modeSnapshot;
    m_bridgeOwnedJtFallbackLastSlot = completedSlot;
    m_bridgeOwnedJtFallbackLastDispatchMs = nowMs;
    qInfo().noquote()
        << "[TIMESYNC][FALLBACK]"
        << "mode=" << modeSnapshot
        << "slot=" << completedSlot
        << "msInSlot=" << msInSlot
        << "buffered=" << bufferedSamples
        << "target=" << targetSamples
        << "min=" << minimumSamples
        << "session=" << m_periodTimerSessionId;
    dispatchTimeSyncDecodeWhenReady(completedSlot, modeSnapshot, m_periodTimerSessionId, nowMs + 1000);
}

int DecodiumBridge::minimumDecodeSamplesForMode(const QString& mode) const
{
    QString const normalized = mode.trimmed().toUpper();
    if (normalized == QStringLiteral("FT8")) {
        return 144000; // 80% of a 15s, 12 kHz FT8 window.
    }
    if (normalized == QStringLiteral("FT4")) {
        return 60000;  // Leaves margin for FT4's shorter DSP window while dropping startup fragments.
    }
    if (normalized == QStringLiteral("WSPR")) {
        return 110 * SAMPLE_RATE; // WSPR needs almost the full 120s receive window.
    }
    if (normalized == QStringLiteral("FST4")
        || normalized == QStringLiteral("FST4W")
        || normalized.startsWith(QStringLiteral("FST4-"))
        || normalized.startsWith(QStringLiteral("FST4W-"))) {
        int const targetSamples = targetDecodeSamplesForMode(normalized);
        return targetSamples > 0 ? targetSamples * 4 / 5 : 0;
    }
    if (normalized == QStringLiteral("JT4")
        || normalized == QStringLiteral("JT65")
        || normalized == QStringLiteral("JT9")) {
        return 52 * SAMPLE_RATE; // Long-sync JT modes need a real 60 s accumulation.
    }
    return 0;
}

int DecodiumBridge::targetDecodeSamplesForMode(const QString& mode) const
{
    int const periodMs = effectivePeriodMsForMode(mode);
    if (periodMs <= 0) {
        return 0;
    }
    return periodMs * SAMPLE_RATE / 1000;
}

void DecodiumBridge::applyNtpSettings()
{
    QSettings s(QSettings::IniFormat, QSettings::UserScope, QStringLiteral("Decodium"), QStringLiteral("Decodium3"));
    decodium::beginActiveSettingsProfile(s);

    // 1.0.159 — DecoSyncTime fase 1: priorita' alla nuova chiave
    // DecoSyncTimeEnabled (default ON). Se l'utente NON ha mai toccato il
    // setting, parte abilitato. Backward compat: se NTPEnabled e' stato
    // toccato esplicitamente in passato (legacy), continua a rispettarlo
    // per non sovrascrivere preferenze utente.
    bool const decoSyncEnabledExplicit = s.contains(QStringLiteral("DecoSyncTimeEnabled"));
    bool const ntpEnabledExplicit      = s.contains(QStringLiteral("NTPEnabled"));
    bool enabled = true;  // default ON
    if (decoSyncEnabledExplicit) {
        enabled = s.value(QStringLiteral("DecoSyncTimeEnabled"), true).toBool();
    } else if (ntpEnabledExplicit) {
        enabled = s.value(QStringLiteral("NTPEnabled"), false).toBool();
    }
    bool const selfCalEnabled = s.value(QStringLiteral("DecoSyncSelfCalEnabled"), false).toBool();
    if (m_decoSyncTime) {
        m_decoSyncTime->setEnabled(enabled);
        m_decoSyncTime->setSelfCalibrationEnabled(enabled && selfCalEnabled);
    }
    QString const customServer =
        s.value(QStringLiteral("NTPCustomServer"), QString()).toString().trimmed();
    double const storedOffset = s.value(QStringLiteral("NTPOffset_ms"), 0.0).toDouble();

    bool const enabledChanged = (m_ntpEnabled != enabled);
    m_ntpEnabled = enabled;
    m_ntpCustomServer = customServer;
    if (enabledChanged) {
        emit ntpEnabledChanged();
    }

    if (!qFuzzyCompare(m_ntpOffsetMs + 1.0, storedOffset + 1.0)) {
        m_ntpOffsetMs = storedOffset;
        emit ntpOffsetMsChanged();
    }

    setGlobalNtpOffsetMs(enabled ? storedOffset : 0.0);

    bool const previousSynced = m_ntpSynced;
    if (!enabled) {
        m_ntpSynced = false;
    }
    if (previousSynced != m_ntpSynced) {
        emit ntpSyncedChanged();
    }

    if (!m_ntpClient) {
        return;
    }

    m_ntpClient->setCustomServer(customServer);
    m_ntpClient->setInitialOffset(storedOffset);
    configureNtpClientForMode(m_mode);
    m_ntpClient->setEnabled(enabled);
    bridgeLog(QStringLiteral("NTP settings applied: enabled=%1 server=%2 offset=%3 ms")
                  .arg(enabled ? QStringLiteral("1") : QStringLiteral("0"),
                       customServer.isEmpty() ? QStringLiteral("<auto>") : customServer,
                       QString::number(storedOffset, 'f', 1)));
    bridgeLog(QStringLiteral("DecoSync RF self-calibration: %1")
                  .arg(enabled && selfCalEnabled ? QStringLiteral("enabled") : QStringLiteral("disabled")));
    if (enabled) {
        m_ntpClient->syncNow();
    }
}

void DecodiumBridge::configureNtpClientForMode(const QString& mode)
{
    if (!m_ntpClient) {
        return;
    }

    QString const normalized = mode.trimmed().toUpper();
    int selfCalPeriodMs = 15000;
    if (normalized == QStringLiteral("FT2")) {
        m_ntpClient->setRefreshInterval(60000);
        m_ntpClient->setMaxRtt(55.0);
        selfCalPeriodMs = 2500;   // FT2 async ~2.5s slot
    } else if (normalized == QStringLiteral("FT4")) {
        m_ntpClient->setRefreshInterval(60000);
        m_ntpClient->setMaxRtt(65.0);
        selfCalPeriodMs = 7500;   // FT4 7.5s period
    } else if (normalized == QStringLiteral("FT8")) {
        m_ntpClient->setRefreshInterval(60000);
        m_ntpClient->setMaxRtt(60.0);
        selfCalPeriodMs = 15000;  // FT8 15s period
    } else {
        m_ntpClient->setRefreshInterval(300000);
        m_ntpClient->setMaxRtt(250.0);
        selfCalPeriodMs = 15000;
    }
    // 1.0.162 — DecoSyncTime fase 4: configura il self-cal con il period
    // appropriato per il mode corrente. Il bridge feeda dt via addDecodeDt
    // per ogni decode appended.
    if (m_decoSyncTime) m_decoSyncTime->setSelfCalPeriodMs(selfCalPeriodMs);
}

void DecodiumBridge::resetStartupTransientQsoState()
{
    // A startup must never reopen a stale QSO from persisted settings.
    m_txEnabled = false;
    m_manualTxHold = false;
    m_qsoProgress = 0;
    m_dxCall.clear();
    m_dxGrid.clear();
    m_tx1.clear();
    m_tx2.clear();
    m_tx3.clear();
    m_tx4.clear();
    m_tx5.clear();
    m_reportSent.clear();
    m_reportReceived = QStringLiteral("-10");
    m_txRetryCount = 0;
    m_lastNtx = -1;
    m_nTx73 = 0;
    m_autoSeqRogerReportBase.clear();
    m_lastTransmittedMessage.clear();
    m_activeTxNumber = 0;
    m_activeTxMessage.clear();
    m_qsoCooldown.clear();
    m_worldMapClosedQsoCallKeys.clear();
    clearPendingAutoLogSnapshot();
    clearLateAutoLogSnapshot();
    clearAutoCqPartnerLock();
    regenerateTxMessages();
    m_currentTx = m_tx6.trimmed().isEmpty() ? 1 : 6;
}

void DecodiumBridge::purgePersistentTransientQsoState()
{
    QSettings s(QSettings::IniFormat, QSettings::UserScope, QStringLiteral("Decodium"), QStringLiteral("Decodium3"));
    decodium::beginActiveSettingsProfile(s);
    s.remove(QStringLiteral("dxCall"));
    s.remove(QStringLiteral("dxGrid"));
    s.remove(QStringLiteral("tx1"));
    s.remove(QStringLiteral("tx2"));
    s.remove(QStringLiteral("tx3"));
    s.remove(QStringLiteral("tx4"));
    s.remove(QStringLiteral("tx5"));
    s.remove(QStringLiteral("reportReceived"));
    s.sync();
}

void DecodiumBridge::resetTimeSyncDecodeMetrics()
{
    m_decodeStartMsBySerial.clear();
    m_decodeModeBySerial.clear();
    m_decodeUtcTokenBySerial.clear();
    m_decodeSessionBySerial.clear();
    m_ft8PendingDeepFollowups.clear();
    m_ft8DeepFollowupCooldownSlots = 0;  // P0 (1.0.403): re-abilita il deep su reset time-sync
    bool const sampleCountChanged = (m_dtLastSampleCount != 0);
    m_dtLastSampleCount = 0;
    m_totalDecodesForDt = 0;
    m_dtSmoothFactor = 0.5;

    bool const avgChanged = !qFuzzyCompare(m_avgDt + 1.0, 1.0);
    bool const latencyChanged = !qFuzzyCompare(m_decodeLatencyMs + 1.0, 1.0);

    m_avgDt = 0.0;
    m_decodeLatencyMs = 0.0;

    if (avgChanged) {
        emit avgDtChanged();
    }
    if (latencyChanged) {
        emit decodeLatencyMsChanged();
    }
    if (sampleCountChanged) {
        emit timeSyncSampleCountChanged();
    }
}

bool DecodiumBridge::shouldTrackDtSample(int snr, double dtValue, const QString& message,
                                         const QString& decodeMode) const
{
    QString const normalized = decodeMode.trimmed().toUpper();
    if (normalized != QStringLiteral("FT4") && normalized != QStringLiteral("FT8")) {
        return false;
    }

    int const snrThreshold = (normalized == QStringLiteral("FT8")) ? -15 : -16;
    double const dtLimit = (normalized == QStringLiteral("FT8")) ? 0.60 : 0.80;

    if (snr < snrThreshold) {
        return false;
    }
    if (std::abs(dtValue) >= dtLimit) {
        return false;
    }

    return !message.trimmed().endsWith(QLatin1Char('?'));
}

void DecodiumBridge::finalizeTimeSyncDecodeCycle(quint64 serial, const QString& decodeMode,
                                                 const QVector<double>& dtSamples)
{
    qint64 const startedAtMs = m_decodeStartMsBySerial.take(serial);
    m_decodeModeBySerial.remove(serial);
    m_decodeUtcTokenBySerial.remove(serial);
    m_decodeSessionBySerial.remove(serial);

    if (!isTimeSyncDecodeMode(decodeMode)) {
        return;
    }

    if (startedAtMs > 0) {
        double const latencyMs =
            static_cast<double>(QDateTime::currentMSecsSinceEpoch() - startedAtMs);
        if (!qFuzzyCompare(m_decodeLatencyMs + 1.0, latencyMs + 1.0)) {
            m_decodeLatencyMs = latencyMs;
            emit decodeLatencyMsChanged();
        }
    }

    int const nextSampleCount = dtSamples.size();
    if (m_dtLastSampleCount != nextSampleCount) {
        m_dtLastSampleCount = nextSampleCount;
        emit timeSyncSampleCountChanged();
    } else {
        m_dtLastSampleCount = nextSampleCount;
    }

    bool avgChanged = false;
    if (dtSamples.size() >= m_dtMinSamples) {
        QVector<double> sorted = dtSamples;
        std::sort(sorted.begin(), sorted.end());
        double const medianDt = sorted[sorted.size() / 2];

        if (m_totalDecodesForDt < 20) {
            m_dtSmoothFactor = 0.5;
        } else if (std::abs(m_avgDt) < 0.1) {
            m_dtSmoothFactor = 0.15;
        } else {
            m_dtSmoothFactor = 0.3;
        }

        double const nextAvg = (m_totalDecodesForDt == 0)
            ? medianDt
            : (m_dtSmoothFactor * medianDt + (1.0 - m_dtSmoothFactor) * m_avgDt);

        if (!qFuzzyCompare(m_avgDt + 1.0, nextAvg + 1.0)) {
            m_avgDt = nextAvg;
            avgChanged = true;
        }
        m_totalDecodesForDt += dtSamples.size();
    } else if (dtSamples.isEmpty() && m_totalDecodesForDt > 0) {
        double const decayedAvg = (std::abs(m_avgDt) < 0.0005) ? 0.0 : (m_avgDt * 0.9);
        if (!qFuzzyCompare(m_avgDt + 1.0, decayedAvg + 1.0)) {
            m_avgDt = decayedAvg;
            avgChanged = true;
        }
    }

    if (avgChanged) {
        emit avgDtChanged();
    }
}

QString DecodiumBridge::mode() const { return m_mode; }

bool DecodiumBridge::ft2LinkAccessUnlocked() const
{
    return m_ft2LinkAccessUnlocked;
}

bool DecodiumBridge::ft2LinkAccessPasswordConfigured() const
{
    QByteArray const salt = ft2LinkConfiguredSalt();
    QByteArray const hash = ft2LinkConfiguredHash();
    int const iterations = ft2LinkConfiguredIterations();
    return salt.size() >= kFt2LinkAccessSaltBytes
        && hash.size() == kFt2LinkAccessHashBytes
        && iterations >= 10000;
}

bool DecodiumBridge::verifyFt2LinkAccessPassword(const QString& password)
{
    QByteArray const salt = ft2LinkConfiguredSalt();
    QByteArray const expected = ft2LinkConfiguredHash();
    int const iterations = ft2LinkConfiguredIterations();

    if (salt.size() < kFt2LinkAccessSaltBytes
        || expected.size() != kFt2LinkAccessHashBytes
        || iterations < 10000) {
        bridgeLog(QStringLiteral("FT2-Link access denied: password not configured"));
        return false;
    }

    QByteArray const actual = ft2LinkPbkdf2Sha256(
        password, salt, iterations, expected.size());
    bool const ok = constantTimeEquals(actual, expected);
    if (ok && !m_ft2LinkAccessUnlocked) {
        m_ft2LinkAccessUnlocked = true;
        emit ft2LinkAccessChanged();
    }
    bridgeLog(ok
              ? QStringLiteral("FT2-Link access unlocked")
              : QStringLiteral("FT2-Link access denied: bad password"));
    return ok;
}

void DecodiumBridge::lockFt2LinkAccess()
{
    if (!m_ft2LinkAccessUnlocked) {
        return;
    }
    m_ft2LinkAccessUnlocked = false;
    emit ft2LinkAccessChanged();
}

void DecodiumBridge::setMode(const QString& v) {
    QString const requestedMode = v.trimmed();
    QString const normalizedMode = canonicalApplicationDecodeMode(requestedMode);
    if (normalizedMode.isEmpty()) {
        if (isRadioOnlyModeLabel(requestedMode)) {
            if (m_catMode.compare(requestedMode, Qt::CaseInsensitive) != 0) {
                m_catMode = requestedMode;
                emit catModeChanged();
            }
            bridgeLog(QStringLiteral("setMode: ignored radio/CAT mode %1, keeping application mode %2")
                          .arg(requestedMode, m_mode));
        } else if (!requestedMode.isEmpty()) {
            bridgeLog(QStringLiteral("setMode: ignored unsupported application mode %1, keeping %2")
                          .arg(requestedMode, m_mode));
        }
        return;
    }

    if (isFt2LinkApplicationMode(normalizedMode) && !m_ft2LinkAccessUnlocked) {
        bridgeLog(QStringLiteral("FT2-Link access denied: mode change blocked until password is verified"));
        if (m_mode != QStringLiteral("FT2")) {
            setMode(QStringLiteral("FT2"));
        }
        return;
    }

    if (m_mode != normalizedMode) {
        // 1.0.179 — Smooth Decode Flow: cambio mode invalida la coda
        // residua (per evitare merge cross-mode); reset + stop timer.
        if (m_decodeReleaseTimer) m_decodeReleaseTimer->stop();
        m_pendingDecodeReleaseQueue.clear();
        QString const previousMode = m_mode;
        bool const monitorWasActive = m_monitoring;
        bool const monitorShouldStayActive = monitorWasActive || m_monitorRequested;
        bool const rearmModernMonitor = monitorWasActive && !usingLegacyBackendForRx();
        quint64 const monitorSessionId = monitorShouldStayActive ? ++m_periodTimerSessionId : m_periodTimerSessionId;
        if (rearmModernMonitor && m_periodTimer) {
            m_periodTimer->stop();
        }

        m_mode = normalizedMode;
        if ((m_mainQmlReady || m_startupServicesStarted) && !legacyBackendRequestedForRx()) {
            ensureDecodeWorkerForMode(m_mode);
        }
        if (m_ft2Worker) {
            m_ft2Worker->setDecodeEnabled(m_mode == QStringLiteral("FT2"));
        }
        if (m_legacyBackend) {
            m_legacyBackend->setFt2DecodeEnabled(m_mode == QStringLiteral("FT2"));
        }
        // 1.0.364+ MAM multi-stream nativo: un cambio modo invalida
        // ogni QSO multi-stream in corso.
        m_mamSlots.clear();
        m_mamMessages.clear();
        m_mamF0sHz.clear();
        // A mode switch invalidates short-lived CAT/audio-frequency guards
        // from the previous mode. Leaving them active can make a later CAT
        // poll look stale and keep the displayed frequency stuck.
        m_localCatFrequencyGuardUntilMs = 0;
        m_localCatFrequencyTargetHz = 0.0;
        m_localCatFrequencyPreviousHz = 0.0;
        m_localRxFrequencyGuardUntilMs = 0;
        m_localRxFrequencyTargetHz = 0;
        m_localTxFrequencyGuardUntilMs = 0;
        m_localTxFrequencyTargetHz = 0;
        invalidateTxAudioCache();
        updatePeriodTicksMax();
        resetTimeSyncDecodeMetrics();
        if (previousMode == QStringLiteral("FT2") && m_mode != QStringLiteral("FT2")) {
            if (m_asyncDecodeTimer) {
                m_asyncDecodeTimer->stop();
            }
            m_asyncDecodePending = false;
            m_asyncAudioPos.store(0, std::memory_order_release);
            m_ft2AsyncLastDispatchAudioPos = 0;
            m_lastFt2AsyncDecodeDispatchMs = 0;
            if (m_ft2Worker) {
                QCoreApplication::removePostedEvents(m_ft2Worker, QEvent::MetaCall);
                m_ft2Worker->markLatestDecodeSerial(std::numeric_limits<quint64>::max());
                m_ft2Worker->cancelCurrentDecode();
            }
            bridgeLog(QStringLiteral("Leaving FT2 mode: legacy FT2 async/sync decode stopped (next=%1)")
                          .arg(m_mode));
        }
        configureNtpClientForMode(m_mode);
        if (m_ntpClient && m_ntpEnabled && isTimeSyncDecodeMode(m_mode)) {
            m_ntpClient->syncNow();
        }
        // FT2 rule (mainwindow: "Async L2 is mandatory and always ON"):
        // cbAsyncDecode forced=true, disabled when in FT2.  Mirror that here.
        if (m_mode == "FT2") {
            if (!m_autoSeq)            { m_autoSeq = true;            emit autoSeqChanged(); }
            if (!m_asyncTxEnabled)     { m_asyncTxEnabled = true;     emit asyncTxEnabledChanged(); }
            if (!m_asyncDecodeEnabled) { m_asyncDecodeEnabled = true;  emit asyncDecodeEnabledChanged(); }
            m_qsoCooldown.clear();
        } else {
            // Uscendo da FT2, forza async decode OFF (mainwindow: cbAsyncDecode->setChecked(false))
            if (m_asyncDecodeEnabled)  { m_asyncDecodeEnabled = false; emit asyncDecodeEnabledChanged(); }
        }
        QString const bandMode = isFt2LinkApplicationMode(normalizedMode)
            ? QStringLiteral("FT2")
            : normalizedMode;
        m_bandManager->setCurrentMode(bandMode);
        if (m_preserveFrequencyOnModeChange) {
            m_bandManager->updateFromFrequency(m_frequency);
        } else {
            m_bandManager->updateForMode(bandMode);
            double const targetFrequency = m_bandManager->dialFrequency();
            if (targetFrequency > 0.0
                && (!qFuzzyCompare(m_frequency + 1.0, targetFrequency + 1.0)
                    || std::abs(m_localCatFrequencyTargetHz - targetFrequency) > 1.0)) {
                setFrequency(targetFrequency);
                requestRigFrequencyFromBridge(targetFrequency, QStringLiteral("remote/mode"));
            }
        }
        // Riavvia la cattura se attiva per adattare il periodo
        if (m_monitoring) {
            resetRxPeriodAccumulation(true);
            // Avvia/ferma async timer in base al modo
            if (m_mode == "FT2") {
                // store(release): il writer (callback audio) usa CAS sul commit
                // di m_asyncAudioPos, quindi questo reset annulla correttamente
                // eventuali increment in volo — il CAS del writer fallirà e il
                // campione verrà scartato.
                m_asyncAudioPos.store(0, std::memory_order_release);
                m_asyncDecodePending = false;
                m_asyncDecodeTimer->start();
            } else {
                m_asyncDecodeTimer->stop();
                m_asyncDecodePending = false;
            }
            if (rearmModernMonitor) {
                restartAudioCaptureForModeChange(previousMode);
                armPeriodTimerForCurrentMode(monitorSessionId, QStringLiteral("setMode"));
            }
        }
        clearDecodeWindowsForModeChange(previousMode, m_mode);
        resetFtxDecodeWorkersForModeChange(previousMode, m_mode);

        emit periodMillisecondsChanged();
        emit modeChanged();
        if (legacyBackendAvailable() && !isFt2LinkApplicationMode(normalizedMode)) {
            m_legacyBackend->setFt2DecodeEnabled(normalizedMode == QStringLiteral("FT2"));
            m_legacyBackend->setMode(normalizedMode);
            m_legacyStartupModeGuard = normalizedMode.trimmed();
            m_legacyStartupModeGuardUntilMs = QDateTime::currentMSecsSinceEpoch() + 6000;
        } else if (legacyBackendAvailable()) {
            m_legacyBackend->setFt2DecodeEnabled(false);
            m_legacyBackend->setMode(QStringLiteral("FT2"));
            m_legacyStartupModeGuard = QStringLiteral("FT2");
            m_legacyStartupModeGuardUntilMs = QDateTime::currentMSecsSinceEpoch() + 6000;
        }
        if (!m_callsign.trimmed().isEmpty()) {
            regenerateTxMessages();
        }
        QString const configuredRigMode = configuredCatRigMode();
        if (!configuredRigMode.isEmpty()) {
            applyConfiguredCatRigMode(QStringLiteral("mode-change"));
        } else if (m_catBackend == QStringLiteral("tci")
            && m_hamlibCat
            && m_hamlibCat->connected()
            && !isFt2LinkApplicationMode(normalizedMode)
            && !canonicalApplicationDecodeMode(normalizedMode).isEmpty()) {
            m_hamlibCat->setRigMode(normalizedMode);
        }
        syncActiveCatTxSplitFrequency(QStringLiteral("mode-change"));
        scheduleModeChangeMonitorRecovery(previousMode, m_mode, monitorSessionId, monitorShouldStayActive);
        scheduleTxAudioPrecompute();
    }
}

// === RX/TX STATE ===
bool DecodiumBridge::monitoring() const { return m_monitoring; }
void DecodiumBridge::setMonitoring(bool v) {
    // IU8LMC: da quando ascoltiamo. Serve all'autodiagnosi per distinguere
    // "banda chiusa / audio scollegato" (zero decode dopo minuti) dall'impazienza
    // di chi guarda per 20 secondi. Vedi DecodiumSelfCheck.
    if (v && !m_monitoring)
        m_monitoringSince = QDateTime::currentDateTimeUtc();
    if (v) startRx(); else stopRx();
}

QVariantList DecodiumBridge::runSelfCheck()
{
    DecodiumSelfCheck::State s;
    s.appVersion      = QStringLiteral(FORK_RELEASE_VERSION);
    s.latestVersion   = m_latestVersion;
    s.updateAvailable = m_updateAvailable;
    s.mode            = mode();
    s.callsign        = m_callsign;
    s.monitoring      = m_monitoring;
    s.ntpEnabled      = ntpEnabled();
    s.ntpSynced       = ntpSynced();
    s.ntpOffsetMs     = m_ntpOffsetMs;
    s.mamMultiStream  = mamMultiStream();
    s.ftThreads       = m_ftThreads;
    s.cpuCores        = QThread::idealThreadCount();
    s.totalDecodesReceived = totalDecodesReceived();
    s.monitoringSeconds = (m_monitoring && m_monitoringSince.isValid())
                              ? m_monitoringSince.secsTo(QDateTime::currentDateTimeUtc())
                              : 0;
    return DecodiumSelfCheck::toVariantList(DecodiumSelfCheck::run(s));
}
bool DecodiumBridge::transmitting() const { return m_transmitting; }
bool DecodiumBridge::decoding() const { return m_decoding; }

void DecodiumBridge::setRxFrequency(int f)
{
    f = qBound(0, f, 5000);
    m_localRxFrequencyTargetHz = f;
    m_localRxFrequencyGuardUntilMs = QDateTime::currentMSecsSinceEpoch() + 2500;
    if (m_rxFrequency != f) {
        m_rxFrequency = f;
        emit rxFrequencyChanged();
        if (legacyBackendAvailable()) {
            m_legacyBackend->setRxFrequency(f);
        }
        if (!usingLegacyBackendForTx()) {
            rebuildRxDecodeList();
        }
        QSettings s(QSettings::IniFormat, QSettings::UserScope, QStringLiteral("Decodium"), QStringLiteral("Decodium3"));
        decodium::beginActiveSettingsProfile(s);
        s.setValue(QStringLiteral("rxFrequency"), m_rxFrequency);
    }
}

void DecodiumBridge::setTxFrequency(int f)
{
    f = qBound(0, f, 5000);
    m_localTxFrequencyTargetHz = f;
    m_localTxFrequencyGuardUntilMs = QDateTime::currentMSecsSinceEpoch() + 2500;
    if (m_txFrequency != f) {
        m_txFrequency = f;
        emit txFrequencyChanged();
        invalidateTxAudioCache();
        if (legacyBackendAvailable()) {
            m_legacyBackend->setTxFrequency(f);
        }
        QSettings s(QSettings::IniFormat, QSettings::UserScope, QStringLiteral("Decodium"), QStringLiteral("Decodium3"));
        decodium::beginActiveSettingsProfile(s);
        s.setValue(QStringLiteral("txFrequency"), m_txFrequency);
        s.setValue(QStringLiteral("TXFrequency"), m_txFrequency);
        syncActiveCatTxSplitFrequency(QStringLiteral("tx-audio-change"));
        scheduleTxAudioPrecompute();
    }
}

// === AUDIO ===
double DecodiumBridge::audioLevel() const { return m_audioLevel; }
double DecodiumBridge::sMeter() const { return m_sMeter; }

void DecodiumBridge::setRxInputLevel(double v)
{
    applyRxInputLevel(v, false);
}

void DecodiumBridge::setAutoRxInputLevel(bool enabled)
{
    if (m_autoRxInputLevel == enabled) {
        return;
    }

    m_autoRxInputLevel = enabled;
    m_autoRxLevelLowStartMs = 0;
    m_autoRxLevelLastAdjustMs = 0;
    m_autoRxLevelManualHoldUntilMs = 0;
    bridgeLog(QStringLiteral("Auto RX Input Level %1").arg(enabled ? QStringLiteral("enabled")
                                                                  : QStringLiteral("disabled")));
    emit autoRxInputLevelChanged();
}

void DecodiumBridge::applyRxInputLevel(double level, bool automatic)
{
    double const bounded = qBound(0.0, level, 100.0);
    if (qFuzzyCompare(m_rxInputLevel + 1.0, bounded + 1.0)) {
        return;
    }

    if (!automatic && m_autoRxInputLevel) {
        m_autoRxInputLevel = false;
        m_autoRxLevelLowStartMs = 0;
        m_autoRxLevelLastAdjustMs = 0;
        m_autoRxLevelManualHoldUntilMs = 0;
        bridgeLog(QStringLiteral("Auto RX Input Level disabled by manual RX level change"));
        emit autoRxInputLevelChanged();
    }

    bridgeLog(QStringLiteral("%1RxInputLevel: requested=%2 previous=%3 legacy=%4")
                  .arg(automatic ? QStringLiteral("auto") : QStringLiteral("set"),
                       QString::number(bounded, 'f', 1),
                       QString::number(m_rxInputLevel, 'f', 1),
                       usingLegacyBackendForTx() ? QStringLiteral("1") : QStringLiteral("0")));
    m_rxInputLevel = bounded;
    if (usingLegacyBackendForTx()) {
        m_legacyBackend->setRxInputLevel(qRound(m_rxInputLevel));
    }
    if (m_soundInput) m_soundInput->setInputGain(rxInputGainFromLevel(m_rxInputLevel));
    emit rxInputLevelChanged();
}

void DecodiumBridge::setTxOutputLevel(double v)
{
    double const bounded = qBound(0.0, v, 450.0);
    if (qFuzzyCompare(m_txOutputLevel + 1.0, bounded + 1.0)) {
        return;
    }

    m_txOutputLevel = bounded;

    if (usingLegacyBackendForTx()) {
        m_legacyBackend->setTxOutputAttenuation(legacyTxAttenuationFromLevel(m_txOutputLevel));
    }

    qreal const attenuationDb = txAttenuationFromSlider(m_txOutputLevel);
    if (m_soundOutput) {
        m_soundOutput->setAttenuation(attenuationDb);
    }
    if (m_txAudioSink) {
        m_txAudioSink->setVolume(static_cast<float>(txGainFromSlider(m_txOutputLevel)));
    }

    emit txOutputLevelChanged();
}

QStringList DecodiumBridge::audioInputDevices() const { return m_audioInputDevices; }
QStringList DecodiumBridge::audioOutputDevices() const { return m_audioOutputDevices; }
QString DecodiumBridge::audioInputDevice() const { return m_audioInputDevice; }

void DecodiumBridge::rememberAudioInputDeviceIdentity(QAudioDevice const& device,
                                                      const QString& reason,
                                                      bool updateDisplayName)
{
    if (!updateDisplayName && m_audioInputDevice.trimmed().isEmpty()) {
        if (!m_audioInputDeviceId.isEmpty()) {
            m_audioInputDeviceId.clear();
            persistSingleAudioIdentity(true, m_audioInputDevice, m_audioInputDeviceId);
        }
        return;
    }

    QString const deviceName = device.description().trimmed();
    QString const deviceId = audioDeviceIdForSettings(device);
    bool changed = false;
    bool nameChanged = false;

    if (updateDisplayName
        && !deviceName.isEmpty()
        && !audioDeviceNameExactMatches(m_audioInputDevice, deviceName)) {
        m_audioInputDevice = deviceName;
        nameChanged = true;
        changed = true;
    }
    if (!deviceId.isEmpty()
        && m_audioInputDeviceId.compare(deviceId, Qt::CaseInsensitive) != 0) {
        m_audioInputDeviceId = deviceId;
        changed = true;
    }

    if (!changed) {
        return;
    }

    bridgeLog(QStringLiteral("audio input identity remembered (%1): %2")
                  .arg(reason.trimmed().isEmpty() ? QStringLiteral("resolved") : reason.trimmed(),
                       audioDeviceSelectionForLog(m_audioInputDevice, m_audioInputDeviceId)));
    persistSingleAudioIdentity(true, m_audioInputDevice, m_audioInputDeviceId);
    if (nameChanged) {
        syncAudioDeviceSettingsToLegacyIni();
        if (legacyBackendAvailable()) {
            m_legacyBackend->setAudioInputDeviceName(m_audioInputDevice);
        }
        emit audioInputDeviceChanged();
    }
}

void DecodiumBridge::rememberAudioOutputDeviceIdentity(QAudioDevice const& device,
                                                       const QString& reason,
                                                       bool updateDisplayName)
{
    if (!updateDisplayName && m_audioOutputDevice.trimmed().isEmpty()) {
        if (!m_audioOutputDeviceId.isEmpty()) {
            m_audioOutputDeviceId.clear();
            persistSingleAudioIdentity(false, m_audioOutputDevice, m_audioOutputDeviceId);
        }
        return;
    }

    QString const deviceName = device.description().trimmed();
    QString const deviceId = audioDeviceIdForSettings(device);
    bool changed = false;
    bool nameChanged = false;

    if (updateDisplayName
        && !deviceName.isEmpty()
        && !audioDeviceNameExactMatches(m_audioOutputDevice, deviceName)) {
        m_audioOutputDevice = deviceName;
        nameChanged = true;
        changed = true;
    }
    if (!deviceId.isEmpty()
        && m_audioOutputDeviceId.compare(deviceId, Qt::CaseInsensitive) != 0) {
        m_audioOutputDeviceId = deviceId;
        changed = true;
    }

    if (!changed) {
        return;
    }

    bridgeLog(QStringLiteral("audio output identity remembered (%1): %2")
                  .arg(reason.trimmed().isEmpty() ? QStringLiteral("resolved") : reason.trimmed(),
                       audioDeviceSelectionForLog(m_audioOutputDevice, m_audioOutputDeviceId)));
    persistSingleAudioIdentity(false, m_audioOutputDevice, m_audioOutputDeviceId);
    m_cachedTxOutputDeviceValid = false;
    invalidateTxAudioCache();
    if (nameChanged) {
        syncAudioDeviceSettingsToLegacyIni();
        if (legacyBackendAvailable()) {
            m_legacyBackend->setAudioOutputDeviceName(m_audioOutputDevice);
        }
        emit audioOutputDeviceChanged();
    }
}

void DecodiumBridge::syncAudioDeviceSettingsToLegacyIni()
{
    syncSettingToLegacyIni(QStringLiteral("SoundInName"), m_audioInputDevice);
    syncSettingToLegacyIni(QStringLiteral("SoundOutName"), m_audioOutputDevice);
    syncSettingToLegacyIni(QStringLiteral("AudioInputChannel"), audioChannelSettingValue(m_audioInputChannel));
    syncSettingToLegacyIni(QStringLiteral("AudioOutputChannel"), audioChannelSettingValue(m_audioOutputChannel));
}

void DecodiumBridge::applyAudioInputRuntimeChange(const QString& reason)
{
    if (usingLegacyBackendForRx() && !useModernSpectrumFeedWithLegacy()) {
        bridgeLog(QStringLiteral("audio input runtime change handled by legacy backend (%1)").arg(reason));
        return;
    }

    if (!m_monitoring) {
        return;
    }

    if (m_transmitting || m_tuning) {
        bridgeLog(QStringLiteral("audio input runtime change deferred while TX/Tune is active (%1)").arg(reason));
        scheduleMonitorRecovery(QStringLiteral("audio input change"), m_periodTimerSessionId, true);
        return;
    }

    if (useLegacyRigControlFallback(m_legacyBackend, m_catBackend)
        && !m_soundInput
        && !m_tciAudioCaptureActive
        && !usingTciAudioInput()) {
        bridgeLog(QStringLiteral("audio input runtime change skipped; legacy fallback owns RX audio (%1)").arg(reason));
        return;
    }

    qint64 const now = QDateTime::currentMSecsSinceEpoch();
    bridgeLog(QStringLiteral("audio input runtime change: restarting RX capture (%1)").arg(reason));
    stopAudioCapture();
    m_audioWatchdogIgnoreUntilMs = now + 5000;
    m_audioUnhealthyStartMs = 0;
    resetRxPeriodAccumulation(true);
    resetTimeSyncDecodeMetrics();
    m_spectrumBuf.clear();
    m_wfRingPos = 0;
    m_lastPanadapterData.clear();
    m_lastPanadapterFrameMs = now;
    m_lastSpectrumRecoveryMs = now;
    m_driftFrameCount = 0;
    m_driftExpectedFrames = 0;
    m_driftClock.restart();
    m_asyncDecodePending = false;
    if (m_mode == QStringLiteral("FT2")) {
        m_asyncAudioPos.store(0, std::memory_order_release);
    }
    startAudioCapture();
    emit statusMessage(QStringLiteral("Audio RX aggiornato: %1").arg(m_audioInputDevice));
}

void DecodiumBridge::applyAudioOutputRuntimeChange(const QString& reason)
{
    bridgeLog(QStringLiteral("audio output runtime change: invalidating TX output (%1)").arg(reason));
    m_cachedTxOutputDeviceValid = false;
    invalidateTxAudioCache();

    if (m_soundOutput) {
        m_soundOutput->setAttenuation(txAttenuationFromSlider(m_txOutputLevel));
    }
    if (m_txAudioSink) {
        m_txAudioSink->setVolume(static_cast<float>(txGainFromSlider(m_txOutputLevel)));
    }

    if (m_transmitting || m_tuning) {
        bridgeLog(QStringLiteral("audio output device will be used from next TX/Tune (%1)").arg(reason));
        return;
    }

    scheduleTxAudioPrecompute();
}

void DecodiumBridge::setAudioInputDevice(const QString& v) {
    QString const value = v.trimmed();
    if (m_audioInputDevice != value) {
        QString const previous = m_audioInputDevice;
        QString const previousId = m_audioInputDeviceId;
        m_audioInputDevice = value;
        QAudioDevice matchedDevice;
        QString matchReason;
        if (tryResolveAudioDeviceByIdentity(cachedAudioInputs(QStringLiteral("setAudioInputDevice"), false),
                                            value,
                                            QString(),
                                            &matchedDevice,
                                            &matchReason)) {
            m_audioInputDeviceId = audioDeviceIdForSettings(matchedDevice);
        } else {
            m_audioInputDeviceId.clear();
        }
        bridgeLog(QStringLiteral("audioInputDevice set to: %1 id=%2 match=%3 previous_id=%4")
                      .arg(m_audioInputDevice,
                           audioDeviceIdSettingForLog(m_audioInputDeviceId),
                           matchReason,
                           audioDeviceIdSettingForLog(previousId)));
        syncAudioDeviceSettingsToLegacyIni();
        if (legacyBackendAvailable()) {
            m_legacyBackend->setAudioInputDeviceName(value);
        }
        QSettings s(QSettings::IniFormat, QSettings::UserScope, "Decodium", "Decodium3");
        decodium::beginActiveSettingsProfile(s);
        s.setValue(QStringLiteral("audioInputDevice"), m_audioInputDevice);
        s.setValue(QStringLiteral("SoundInName"), m_audioInputDevice);
        if (m_audioInputDeviceId.isEmpty()) {
            s.remove(QStringLiteral("audioInputDeviceId"));
        } else {
            s.setValue(QStringLiteral("audioInputDeviceId"), m_audioInputDeviceId);
        }
        s.sync();
        emit audioInputDeviceChanged();
        applyAudioInputRuntimeChange(QStringLiteral("device %1 -> %2")
                                         .arg(audioDeviceSelectionForLog(previous, previousId),
                                              audioDeviceSelectionForLog(m_audioInputDevice, m_audioInputDeviceId)));
    }
}
QString DecodiumBridge::audioOutputDevice() const { return m_audioOutputDevice; }
void DecodiumBridge::setAudioOutputDevice(const QString& v) {
    QString const value = v.trimmed();
    if (m_audioOutputDevice == value) {
        QAudioDevice matchedDevice;
        QString matchReason;
        if (tryResolveAudioDeviceByIdentity(cachedAudioOutputs(QStringLiteral("setAudioOutputDevice same-value"), false),
                                            value,
                                            m_audioOutputDeviceId,
                                            &matchedDevice,
                                            &matchReason)) {
            QString const matchedId = audioDeviceIdForSettings(matchedDevice);
            if (!matchedId.isEmpty()
                && matchedId.compare(m_audioOutputDeviceId, Qt::CaseInsensitive) != 0) {
                rememberAudioOutputDeviceIdentity(matchedDevice,
                                                  QStringLiteral("setAudioOutputDevice same-value %1").arg(matchReason),
                                                  true);
            }
        }
        m_cachedTxOutputDeviceValid = false;
        invalidateTxAudioCache();
        return;
    }
    if (m_audioOutputDevice != value) {
        QString const previous = m_audioOutputDevice;
        QString const previousId = m_audioOutputDeviceId;
        m_audioOutputDevice = value;
        QAudioDevice matchedDevice;
        QString matchReason;
        if (tryResolveAudioDeviceByIdentity(cachedAudioOutputs(QStringLiteral("setAudioOutputDevice"), false),
                                            value,
                                            QString(),
                                            &matchedDevice,
                                            &matchReason)) {
            m_audioOutputDeviceId = audioDeviceIdForSettings(matchedDevice);
        } else {
            m_audioOutputDeviceId.clear();
        }
        bridgeLog(QStringLiteral("audioOutputDevice set to: %1 id=%2 match=%3 previous_id=%4")
                      .arg(m_audioOutputDevice,
                           audioDeviceIdSettingForLog(m_audioOutputDeviceId),
                           matchReason,
                           audioDeviceIdSettingForLog(previousId)));
#ifdef Q_OS_LINUX
        const QString pulseSinkName = linuxPulseSinkNameFromDisplay(m_audioOutputDevice);
        if (!pulseSinkName.isEmpty()) {
            QString pulseError;
            if (linuxSetDefaultPulseSink(pulseSinkName, &pulseError)) {
                bridgeLog(QStringLiteral("audioOutputDevice: selected Linux Pulse/PipeWire sink [%1]")
                              .arg(pulseSinkName));
                qInfo().noquote() << "[AUDIODEV] selected Pulse/PipeWire sink:" << pulseSinkName;
            } else {
                bridgeLog(QStringLiteral("audioOutputDevice: failed to select Linux Pulse/PipeWire sink [%1]: %2")
                              .arg(pulseSinkName, pulseError));
                qWarning().noquote() << "[AUDIODEV] failed to select Pulse/PipeWire sink:"
                                     << pulseSinkName << pulseError;
            }
        }
#endif
        syncAudioDeviceSettingsToLegacyIni();
        if (legacyBackendAvailable()) {
            m_legacyBackend->setAudioOutputDeviceName(value);
        }
        QSettings s(QSettings::IniFormat, QSettings::UserScope, "Decodium", "Decodium3");
        decodium::beginActiveSettingsProfile(s);
        s.setValue(QStringLiteral("audioOutputDevice"), m_audioOutputDevice);
        s.setValue(QStringLiteral("SoundOutName"), m_audioOutputDevice);
        if (m_audioOutputDeviceId.isEmpty()) {
            s.remove(QStringLiteral("audioOutputDeviceId"));
        } else {
            s.setValue(QStringLiteral("audioOutputDeviceId"), m_audioOutputDeviceId);
        }
        s.sync();
        emit audioOutputDeviceChanged();
        applyAudioOutputRuntimeChange(QStringLiteral("device %1 -> %2")
                                          .arg(audioDeviceSelectionForLog(previous, previousId),
                                               audioDeviceSelectionForLog(m_audioOutputDevice, m_audioOutputDeviceId)));
    }
}
